// --- GPU images (elg/gpu_image.h) ---

/// An image a native GPU producer publishes frames into, shown by GpuImageView(). Made with
/// elg_gpu_image_create() and freed with elg_gpu_image_destroy().
typedef struct ElgGpuImage ElgGpuImage;
// Fixed-width tags, not C enums, so Rust can use repr(C) without enum validity hazards.
#define ELG_GPU_IMAGE_OK 0u                 ///< Success.
#define ELG_GPU_IMAGE_INVALID_ARGUMENT 1u   ///< A null pointer, or a field out of range or missing.
#define ELG_GPU_IMAGE_DEVICE_UNAVAILABLE 2u ///< No live renderer to import into.
#define ELG_GPU_IMAGE_UNSUPPORTED 3u        ///< The renderer's backend or device can't import this transport.
#define ELG_GPU_IMAGE_IMPORT_FAILED 4u      ///< The import failed, or the memory doesn't match the frame.
#define ELG_GPU_IMAGE_SYNC_FAILED 5u        ///< Releasing: the fences couldn't be exported or waited for.
#define ELG_GPU_IMAGE_INTERNAL_ERROR 6u     ///< An unexpected failure inside Elegance.

#define ELG_GPU_IMAGE_IOSURFACE 1u
#define ELG_GPU_IMAGE_DXGI_HANDLE 2u
#define ELG_GPU_IMAGE_VULKAN_OPAQUE_FD 3u
#define ELG_GPU_IMAGE_RGBA8 1u
#define ELG_GPU_IMAGE_BGRA8 2u
#define ELG_GPU_IMAGE_TOP_LEFT 0u
#define ELG_GPU_IMAGE_BOTTOM_LEFT 1u

#define ELG_GPU_IMAGE_FENCE_NONE 0u
#define ELG_GPU_IMAGE_FENCE_MTL_SHARED_EVENT 1u
#define ELG_GPU_IMAGE_FENCE_DXGI_HANDLE 2u
#define ELG_GPU_IMAGE_FENCE_VK_OPAQUE_FD 3u

/// A GPU fence shared between the producer and Elegance: ElgGpuImageFrame::producer_fence, which
/// the producer's writes signal, or one of ElgGpuImageRelease::fences, which Elegance's reads
/// signal.
typedef struct ElgGpuImageFence {
    uint32_t type;  ///< One of the ELG_GPU_IMAGE_FENCE_* tags; the frame's must match its transport.
    void* handle;   ///< id<MTLSharedEvent> or shared D3D fence NT HANDLE; not a WebGPU handle
    int fd;         ///< VK_EXTERNAL_SEMAPHORE_HANDLE_TYPE_OPAQUE_FD_BIT, binary semaphore
    uint64_t value; ///< Metal/D3D timeline value; Vulkan binary semaphore: 1
} ElgGpuImageFence;

/// What the release callback gets once Elegance submits no more GPU work that reads a published
/// frame. The record and the fences in it are borrowed only during the callback.
typedef struct ElgGpuImageRelease {
    /// ELG_GPU_IMAGE_OK, or ELG_GPU_IMAGE_SYNC_FAILED / ELG_GPU_IMAGE_INTERNAL_ERROR: then
    /// synchronization is unknown (see elg_gpu_image_publish()).
    uint32_t status;
    uint64_t token; ///< unchanged producer token, not used as a cache identity
    /// The fences to wait for before reusing or freeing the allocation; null unless `status` is OK.
    const ElgGpuImageFence* fences;
    size_t fence_count;    ///< How many `fences` there are.
    int32_t vk_old_layout; ///< Vulkan: the old layout of the transition back to the producer.
    int32_t vk_new_layout; ///< Vulkan: the new layout of the transition back to the producer.
} ElgGpuImageRelease;

/// Called exactly once for each accepted frame, on any thread, when Elegance is done with it (see
/// elg_gpu_image_publish()). Must not throw, block waiting for renderer work, or call this API.
///
/// @param userdata ElgGpuImageFrame::userdata of the frame.
/// @param release The status, the frame's token, and the fences to wait for; borrowed only during
///   the call.
typedef void (*ElgGpuImageReleaseCallback)(void* userdata, const ElgGpuImageRelease* release);

/// One frame for elg_gpu_image_publish(): a 2D texture allocated by the producer, and how to
/// import and release it.
typedef struct ElgGpuImageFrame {
    /// ELG_GPU_IMAGE_IOSURFACE (Metal), ELG_GPU_IMAGE_DXGI_HANDLE (D3D12) or
    /// ELG_GPU_IMAGE_VULKAN_OPAQUE_FD (Vulkan); it must match the renderer's backend.
    uint32_t transport;
    uint32_t format; ///< ELG_GPU_IMAGE_RGBA8 or ELG_GPU_IMAGE_BGRA8: the texture's UNORM format.
    uint32_t width;  ///< The texture's width in pixels; not 0.
    uint32_t height; ///< The texture's height in pixels; not 0.
    void* handle;    ///< IOSurfaceRef (not IOSurfaceID), or DXGI texture NT HANDLE
    int memory_fd;   ///< Vulkan only: the allocation's opaque FD; not negative.
    /// Vulkan only: exact VkImageCreateInfo including its pNext chain, matching the exported
    /// image bound at allocation offset zero (no suballocations). Borrowed for publish() only.
    /// Same physical device/compatible memory type required.
    const void* vk_image_create_info;
    uint32_t vk_memory_type_index;    ///< Vulkan only: the allocation's memory type index.
    uint64_t vk_allocation_size;      ///< Vulkan only: the allocation's size in bytes; not 0.
    uint32_t vk_dedicated_allocation; ///< 0 or 1
    int32_t vk_old_layout; ///< Vulkan only: the old layout of the producer's ownership release.
    int32_t vk_new_layout; ///< Vulkan only: the new layout of the producer's ownership release.
    /// Signaled when the producer's writes are done; type ELG_GPU_IMAGE_FENCE_NONE asserts that
    /// they already are.
    ElgGpuImageFence producer_fence;
    uint64_t token;                     ///< The producer's own value, handed back in the release.
    void* userdata;                     ///< Passed to `release`.
    ElgGpuImageReleaseCallback release; ///< Required: called once Elegance is done with the frame.
} ElgGpuImageFrame;

/// Unsafe, low-level native sharing API. No CPU upload/readback and no conversion fallback.
/// Publication requires a live renderer. Fixed origin; one mip/layer/sample, 2D RGBA/BGRA
/// UNORM storage, sRGB-encoded RGB, straight alpha. Import must permit an sRGB sampling view.
/// Create dimensions must be nonzero and supply the initial natural size until a frame is accepted.
/// Each publication may have different nonzero dimensions; successful frames update natural size
/// asynchronously on the UI thread without replacing the source. Clear retains the last natural size.
/// No YUV, keyed mutex, DMA-BUF, cross-adapter or device-loss recovery support.
///
/// @param width The initial natural width in pixels; not 0.
/// @param height The initial natural height in pixels; not 0.
/// @param origin ELG_GPU_IMAGE_TOP_LEFT, or ELG_GPU_IMAGE_BOTTOM_LEFT for images stored bottom
///   row first (views flip them).
/// @return The image, owned by the caller (free it with elg_gpu_image_destroy()), or null when an
///   argument is invalid or allocation fails.
ElgGpuImage* elg_gpu_image_create(uint32_t width, uint32_t height, uint32_t origin);
/// Frees the handle. Not a drain: views showing the image keep its last frame, and release
/// callbacks still come.
///
/// @param image The image, or null (nothing happens). Must not be in use by another thread.
void elg_gpu_image_destroy(ElgGpuImage* image);
/// Thread-safe against publish/clear on a LIVE handle, not against destroy. Synchronous import;
/// returns a status above. On failure ownership stays with caller, no callback and no reads;
/// the previous frame and natural size remain unchanged.
/// On success, exactly one release callback follows, possibly before publish returns if another
/// thread clears/replaces the frame. Keep userdata/resources alive until that callback.
///
/// Each accepted publication is a fresh, exclusive allocation: never publish aliases of an
/// outstanding allocation. Stop all producer writes before publication. Supply its producer
/// fence, or NONE as an explicit assertion that producer GPU writes have ALREADY COMPLETED.
/// Handles/FDs are borrowed, never closed/released by Elegance; keep them and the allocation
/// alive until release. A Vulkan semaphore must be exportable/importable as a BINARY semaphore.
/// Producer must release external queue-family ownership as required by Dawn's Vulkan sharing
/// contract and supply the corresponding old/new layouts. Elegance returns the reverse layout
/// transition at retirement; producer must acquire ownership before accessing the image again.
///
/// Release means NO FUTURE consumer submissions, NOT GPU completion. All returned fences must
/// be imported/waited before overwriting, recycling OR freeing the allocation. Fence handles
/// and the release record are BORROWED ONLY DURING CALLBACK: duplicate/retain them there.
/// A consuming native import (e.g. vkImportSemaphoreFdKHR) must consume a DUPLICATE, not the
/// borrowed exported FD/handle.
/// On non-OK release, synchronization is unknown: quarantine the allocation until independently
/// establishing GPU completion/device teardown; do not infer safety from an empty fence list.
/// Retirement normally runs asynchronously on an internal worker; clear/destroy do not drain
/// callbacks. Metal scheduling waits are bounded (5 seconds), then report SYNC_FAILED.
/// Callback may run on any thread, must not throw/unwind, block waiting for renderer work, or
/// reenter this API. destroy is not a drain: views/snapshots may retain frames. Accepted frames
/// retain the Dawn device/instance for retirement after the UI renderer stops; new publications
/// then return DEVICE_UNAVAILABLE. Stop/join producers and clear images when the app exits,
/// retaining callback state until every accepted frame has retired.
///
/// @param image The image to show the frame in.
/// @param frame The frame; borrowed for the call (its handles until the release callback).
/// @return ELG_GPU_IMAGE_OK when the frame was accepted, else the reason it wasn't:
///   INVALID_ARGUMENT, DEVICE_UNAVAILABLE, UNSUPPORTED, IMPORT_FAILED or INTERNAL_ERROR.
uint32_t elg_gpu_image_publish(ElgGpuImage* image, const ElgGpuImageFrame* frame);
/// Stops showing the current frame (it's released once nothing draws it). The natural size stays.
/// Thread-safe like elg_gpu_image_publish().
///
/// @param image The image, or null (nothing happens).
void elg_gpu_image_clear(ElgGpuImage* image);

// --- Structs and callbacks ---

/// UTF-8 text: `len` bytes at `ptr`, not NUL-terminated. A null `ptr` is the empty string.
/// Malformed UTF-8 in text that Elegance shows, edits or exposes to assistive technology reads as
/// U+FFFD, as it does through the C++ API. Passed to Elegance, it's read during the call
/// (Elegance copies what it keeps). Passed to a callback or returned, it points into Elegance's
/// memory: valid during the callback, or as long as the function says.
typedef struct ElgStr {
    const char* ptr; ///< The first byte, or null.
    size_t len;      ///< Length in bytes.
} ElgStr;

/// Bytes: `len` of them at `ptr`. Read during the call or valid during the callback, like ElgStr.
/// A null `ptr` is no bytes.
typedef struct ElgBytes {
    const unsigned char* ptr; ///< The first byte, or null.
    size_t len;               ///< How many bytes.
} ElgBytes;

/// Calls a Rust closure. `args` and `ret` point at values whose types depend on the call site.
///
/// @param data The closure's ElgClosure::data.
/// @param args The closure's argument, or null. Each function's doc says what it points to.
/// @param ret Where the closure writes its result, or null. Each function's doc says what it
///   points to.
/// @return false if the closure panicked.
typedef bool (*ElgCallFn)(void* data, void* args, void* ret);

/// Frees a Rust closure that Elegance owns, once Elegance is done with it.
///
/// @param data The closure's ElgClosure::data.
typedef void (*ElgDropFn)(void* data);

/// A Rust closure. `call` null: no closure, which only optional callbacks accept; a function that
/// needs the closure fails with a usage error. `drop` null: borrowed for the duration of the call.
///
/// Elegance calls a closure's `drop` exactly once, when it no longer needs the closure: when the
/// view or object that keeps it goes, right after the call for a closure it only calls during the
/// call, and also when the call fails or doesn't use the closure. Each function's doc says what
/// `args` and `ret` point to.
typedef struct ElgClosure {
    void* data;     ///< The closure's state, passed to `call` and `drop`.
    ElgCallFn call; ///< Runs the closure; null: no closure.
    ElgDropFn drop; ///< Frees `data`; null: nothing to free.
} ElgClosure;

/// An exception that escaped app code while the app ran, as elg_app_on_error()'s handler gets it.
typedef struct ElgAppError {
    int32_t kind;   ///< The error's kind, numbered as elg_take_error() numbers them.
    ElgStr message; ///< What it says; valid only during the call.
    /// The kind of app code it escaped, elg::AppCode: 0 a view's body, 1 an effect, 2 an event
    /// handler or action, 3 a task, 4 a timer, 5 on_appear or on_disappear, 6 layout, 7 a Canvas's
    /// drawing, 8 another callback.
    int32_t code;
} ElgAppError;

/// Receives a string from Elegance (an error message, a font family, a device's error).
///
/// @param ctx The `ctx` the function was given along with the sink.
/// @param ptr The string's UTF-8 bytes, not NUL-terminated, valid only during the call.
/// @param len Length in bytes.
typedef void (*ElgStrSink)(void* ctx, const char* ptr, size_t len);

/// An elg::Color: sRGB with straight (non-premultiplied) alpha.
typedef struct ElgColor {
    float r, g, b, a; ///< Red, green, blue, and alpha (opacity), each 0 to 1.
} ElgColor;

/// A width and height (elg::Size), in points unless a function says pixels.
typedef struct ElgSize {
    float width, height; ///< Width and height.
} ElgSize;

/// An elg::PixelSize: physical dimensions, unlike the logical points of ElgSize.
typedef struct ElgPixelSize {
    uint32_t width, height; ///< Width and height in pixels.
} ElgPixelSize;

/// An elg::Point in points, y growing downward. Where a function says so, a UnitPoint instead:
/// (0, 0) is a view's top-leading corner, (1, 1) its bottom-trailing one.
typedef struct ElgPoint {
    float x, y; ///< Horizontal and vertical position.
} ElgPoint;

/// An elg::Rect, in points.
typedef struct ElgRect {
    float x, y, width, height; ///< Top-left corner and size.
} ElgRect;

/// An elg::Font.
typedef struct ElgFont {
    ElgStr family;  ///< A family registered with register_font(); empty: the system font.
    float size;     ///< Size in points.
    int32_t weight; ///< An elg::Weight, 1 to 1000: 400 regular, 700 bold.
    bool italic;    ///< The italic face.
} ElgFont;

/// An elg::GradientStop.
typedef struct ElgGradientStop {
    ElgColor color; ///< The color at this stop.
    float location; ///< Where along the gradient, 0 to 1.
} ElgGradientStop;

/// An elg::ShapeStyle: a color or a gradient. Points are unit points of the filled shape's bounds.
///
/// kind 0: color; 1: linear gradient from (x0, y0) to (x1, y1); 2: radial gradient around (x0, y0)
/// from radius r0 to r1; 3: elliptical gradient around (x0, y0) from radius fraction r0 to r1;
/// 4: angular gradient around (x0, y0) from angle r0 to r1 (degrees).
typedef struct ElgShapeStyle {
    int32_t kind;                 ///< 0 to 4, as above. Other values are a color.
    ElgColor color;               ///< Kind 0: the color.
    const ElgGradientStop* stops; ///< Gradients: the color stops, read during the call.
    size_t stop_count;            ///< Number of `stops`.
    float x0, y0, x1, y1;         ///< Kind 1: the start and end points. Kinds 2 to 4: the center (x0, y0).
    /// Kinds 2 to 4: the start and end radius in points (radial), as a fraction of the bounds' size
    /// (elliptical; 0.5 reaches the edges), or the angles in degrees, clockwise from trailing (angular).
    float r0, r1;
} ElgShapeStyle;

/// An elg::EdgeInsets, in points.
typedef struct ElgEdgeInsets {
    float top, leading, bottom, trailing; ///< The inset on each side.
} ElgEdgeInsets;

/// A reactive argument (an elg::Prop). kind 0: `value` points at the static value (its C form);
/// 1: `fn` returns it (ret: a C++ T*); 2: `fn` takes the environment (args: const
/// EnvironmentValues*); 3: the theme color `theme` (Color and ShapeStyle props).
typedef struct ElgProp {
    int32_t kind;  ///< 0 to 3, as above.
    int32_t theme; ///< Kind 3: an elg::ThemeColor. Props of other types get their default value.
    /// Kind 0: the value's C form (`float*`, `bool*`, `ElgStr*`, `ElgColor*`, ...), read during the
    /// call.
    const void* value;
    /// Consumed. Kinds 1 and 2: runs whenever Elegance reads the prop, and writes the C++ value
    /// into `ret` (strings with elg_string_assign()); a null `call` is a usage error. Other kinds
    /// don't call it, and drop it.
    ElgClosure fn;
} ElgProp;

/// An elg::ProposedSize: the size a parent offers during layout. An unspecified dimension asks
/// for the ideal size, 0 for the minimum, and infinity for the maximum.
typedef struct ElgProposedSize {
    bool has_width;  ///< false: the width is unspecified.
    float width;     ///< The proposed width in points, if `has_width`.
    bool has_height; ///< false: the height is unspecified.
    float height;    ///< The proposed height in points, if `has_height`.
} ElgProposedSize;

/// An optional length (elg::OptionalLength, std::optional<float>).
typedef struct ElgOptLen {
    bool has;    ///< false: none.
    float value; ///< The value, if `has`.
} ElgOptLen;

/// An elg::Alignment.
typedef struct ElgAlignment {
    int32_t horizontal; ///< An elg::HorizontalAlignment: 0 leading, 1 center, 2 trailing.
    int32_t vertical;   ///< An elg::VerticalAlignment: 0 top, 1 center, 2 bottom.
} ElgAlignment;

/// An elg::KeyEvent.
typedef struct ElgKeyEvent {
    int32_t kind;       ///< KeyEvent::Kind: 0 down, 1 up.
    int32_t key;        ///< An elg::Key: the key by meaning (layout-mapped), not its position.
    uint32_t modifiers; ///< elg::KeyModifiers bits: 1 shift, 2 control, 4 alt, 8 super (Cmd, the Windows key).
    bool repeat;        ///< Auto-repeat while held.
} ElgKeyEvent;

/// An elg::PointerEvent.
typedef struct ElgPointerEvent {
    int32_t kind;             ///< PointerEvent::Kind: 0 down, 1 up, 2 move, 3 cancel, 4 hover.
    /// In points: window coordinates for an event handler, the view's own for View::on_pointer.
    ElgPoint location;
    int32_t button;           ///< An elg::MouseButton: 0 left, 1 middle, 2 right, 3 other.
    int32_t click_count;      ///< 2 for the second click of a double click, ...
    uint32_t modifiers;       ///< elg::KeyModifiers held when the button went down or up (see ElgKeyEvent).
    ElgPoint window_location; ///< Always in the window's coordinates.
} ElgPointerEvent;

/// An elg::ScrollEvent: a mouse wheel or trackpad scroll. Deltas are in points, positive toward
/// the end of the content (wheel down: positive dy).
typedef struct ElgScrollEvent {
    /// Where the pointer is: window coordinates for an event handler, the view's own for
    /// View::on_scroll.
    ElgPoint location;
    ElgPoint window_location; ///< Always in the window's coordinates.
    float dx, dy;             ///< How far it scrolled.
    bool precise;             ///< Trackpad-style fine deltas (apply directly) rather than wheel notches.
    uint32_t modifiers;       ///< elg::KeyModifiers held while scrolling (see ElgKeyEvent).
    int32_t phase;            ///< An elg::GesturePhase: 0 none, 1 began, 2 changed, 3 ended, 4 cancelled.
    bool momentum;            ///< The system's momentum after a flick, as the scroll coasts to a stop.
    double time;              ///< When it happened, in seconds on the event source's clock; 0 if unknown.
} ElgScrollEvent;

/// An elg::ClickEvent: a click on a view (View::on_click), pressed and released inside it.
typedef struct ElgClickEvent {
    ElgPoint location;        ///< Where it was released, in the view's own coordinates.
    ElgPoint window_location; ///< The same, in the window's.
    int32_t button;           ///< An elg::MouseButton (see ElgPointerEvent).
    uint32_t modifiers;       ///< elg::KeyModifiers held when it was released (see ElgKeyEvent).
    int32_t click_count;      ///< 2 for a double click, ...
} ElgClickEvent;

/// An elg::DragEvent: a drag in progress. Locations are in the view's own coordinates; the
/// translation is measured in the window.
typedef struct ElgDragEvent {
    ElgPoint location;       ///< Where the pointer is now.
    ElgPoint start_location; ///< Where the press went down.
    ElgPoint translation;    ///< How far the pointer has moved since the press.
    ElgPoint velocity;       ///< Points per second, over the last moments of the drag.
    int32_t button;          ///< An elg::MouseButton (see ElgPointerEvent).
    uint32_t modifiers;      ///< elg::KeyModifiers held when the press went down (see ElgKeyEvent).
} ElgDragEvent;

/// An elg::MagnifyEvent: pinching on a trackpad (or a touch screen).
typedef struct ElgMagnifyEvent {
    ElgPoint location; ///< Where the gesture is.
    float scale;       ///< Since the gesture began: 2 is twice as big.
    float delta;       ///< Since the last event, as a factor.
    int32_t phase;     ///< An elg::GesturePhase (see ElgScrollEvent).
} ElgMagnifyEvent;

/// An elg::RotateEvent: turning two fingers on a trackpad.
typedef struct ElgRotateEvent {
    ElgPoint location; ///< Where the gesture is.
    float degrees;     ///< Since the gesture began, clockwise.
    float delta;       ///< Since the last event, in degrees.
    int32_t phase;     ///< An elg::GesturePhase (see ElgScrollEvent).
} ElgRotateEvent;

/// An elg::TextInputEvent: text from the keyboard or an input method.
typedef struct ElgTextInputEvent {
    /// TextInputEvent::Kind: 0 commit (insert `text`), 1 composition (an IME's in-progress text,
    /// replacing the previous one; empty ends it).
    int32_t kind;
    ElgStr text;   ///< The text, valid during the call.
    size_t cursor; ///< Composition: the IME's caret, in bytes into `text`.
} ElgTextInputEvent;

/// An elg::EventResult: what an event handler did with an event.
typedef struct ElgEventResult {
    /// Stops the event from reaching outer handlers. Consuming a down captures the pointer: the
    /// handler then receives the moves and the up, wherever the pointer goes.
    bool consumed;
    bool redraw; ///< The handler changed how something looks; the window needs a new frame.
    /// With `consumed` on a down: gesture recognizers around the view may take the press over, and
    /// the handler then gets a cancel. For presses that are clicks; handlers that track the pointer
    /// themselves leave it false.
    bool cancellable;
} ElgEventResult;

/// elg::FloatingPlacement: edge (FloatingEdge), alignment (FloatingAlignment), and an optional
/// position instead of an edge.
typedef struct ElgFloatingPlacement {
    /// The anchor's side the content opens on, flipped when there isn't room: 0 bottom, 1 top,
    /// 2 trailing, 3 leading.
    int32_t edge;
    int32_t alignment; ///< Across that edge, lined up with the anchor's: 0 start, 1 center, 2 end.
    float spacing;     ///< Between the anchor and the content, in points (negative: overlapping).
    ElgPoint offset;   ///< Then moved by this, in points.
    bool has_position; ///< Use `position` instead of `edge`.
    ElgPoint position; ///< The content's top-leading corner, in the anchor's coordinates.
} ElgFloatingPlacement;

/// An optional elg::PopupMotion: `has` false is nullopt (the style's); null transition or
/// animation is PopupMotion::none(). Borrowed.
typedef struct ElgPopupMotion {
    bool has;                        ///< false: nullopt.
    const ElgTransition* transition; ///< How the content enters and leaves.
    const ElgAnimation* animation;   ///< The transition's timing.
} ElgPopupMotion;

/// An elg::HoverDelay: how long the pointer must rest on a view before it counts as hovered, and
/// how long after it leaves before it stops counting.
typedef struct ElgHoverDelay {
    double enter; ///< Seconds before it's hovered.
    double exit;  ///< Seconds before it's no longer hovered.
} ElgHoverDelay;

/// An elg::Shadow.
typedef struct ElgShadow {
    ElgColor color;     ///< The shadow's color.
    float radius, x, y; ///< The blur radius and the offset, in points.
    float spread;       ///< Grows (negative: shrinks) a single shape before blurring, in points.
} ElgShadow;

/// An elg::StrokeStyle.
typedef struct ElgStrokeStyle {
    float width;       ///< Line width in points.
    int32_t cap;       ///< An elg::LineCap: 0 butt, 1 round, 2 square.
    int32_t join;      ///< An elg::LineJoin: 0 miter, 1 round, 2 bevel.
    float miter_limit; ///< Miter joins longer than this many widths become bevels.
    const float* dash; ///< On, off, on, off... lengths, read during the call; null: solid.
    size_t dash_count; ///< Number of `dash` lengths.
    float dash_phase;  ///< How far into the dash pattern the stroke starts.
} ElgStrokeStyle;

/// An elg::RunStyle: how a run of text looks. Unset parts come from the environment.
typedef struct ElgRunStyle {
    bool has_weight;     ///< false: the font's weight.
    int32_t weight;      ///< An elg::Weight, if `has_weight`.
    bool italic;         ///< The italic face.
    ElgStr family;       ///< A registered family (e.g. monospace for code); empty: the font's.
    bool has_color;      ///< false: the environment's foreground style.
    ElgColor color;      ///< The text color, if `has_color`.
    bool has_background; ///< false: no highlight.
    ElgColor background; ///< A rounded highlight behind the run (mentions, inline code), if `has_background`.
    bool underline;      ///< Underlined.
    bool strikethrough;  ///< Struck through.
    bool keep_together;  ///< Never broken across lines (implied by a background).
} ElgRunStyle;

/// An elg::ImageSource: an icon, an image file, or image data. Set exactly one of the first three
/// and leave the others empty.
typedef struct ElgImageSource {
    ElgStr system_name; ///< An icon, named as for elg::Image(): "set.icon-name.variant", set and variant optional.
    ElgStr file;        ///< A raster image file's path (PNG, JPEG, ...).
    ElgBytes data;      ///< Encoded image data in memory, in any of those formats (copied).
    float scale;        ///< Raster images: pixels per point, e.g. 2 for double-resolution artwork.
    /// Raster images: the most pixels (width times height) the image may have; one with more isn't
    /// shown. 0: the default, 2^27.
    uint64_t max_pixels;
    /// Raster images: the longest side the image is decoded at; a larger one is scaled down to fit.
    /// 0: the default, 8192.
    uint32_t max_side;
} ElgImageSource;

/// An elg::Theme: its light colors, then its dark ones (17 each, in elg::ColorTokens' order), then
/// its blur radii (7, in elg::BlurTokens' order).
typedef struct ElgTheme {
    ElgColor colors[34]; ///< `light`, then `dark`.
    float blur[7];       ///< `blur`.
} ElgTheme;

/// An elg::LayoutChild, which a custom layout gets an array of: one pointer, Elegance's, only for
/// passing back to the C API.
typedef struct ElgLayoutChild {
    void* element; ///< Elegance's.
} ElgLayoutChild;

/// An elg::WindowDesc: how a window opens (elg_app_window()). Sizes are in logical points.
typedef struct ElgWindowDesc {
    ElgStr title;                      ///< The window's title.
    int32_t width;                     ///< Initial width.
    int32_t height;                    ///< Initial height.
    bool resizable;                    ///< Whether the user can resize it.
    bool has_min_size;                 ///< false: no minimum size.
    ElgSize min_size;                  ///< Smallest size the user can resize to, if `has_min_size`.
    /// false: the default background, the theme's (ThemeColor::background), or clear for
    /// transparent windows.
    bool has_background;
    ElgColor background;               ///< Shown where no view draws, if `has_background`.
    int32_t title_bar;                 ///< An elg::TitleBar: 0 system, 1 hidden, 2 integrated.
    bool has_system_controls_position; ///< false: the system's window controls go where it puts them.
    /// TitleBar::integrated on macOS: where the system's window controls go, as the first one's
    /// top-left corner in points from the window's top-left corner.
    ElgPoint system_controls_position;
    bool transparent;                  ///< The desktop shows through where the content isn't opaque.
    float opacity;                     ///< The whole window's opacity, 0 to 1.
    /// Covers the whole display it opens on, without a frame. `width` and `height` are its size
    /// when it leaves fullscreen.
    bool fullscreen;
} ElgWindowDesc;

/// A Transition::Pose: how a view looks partway through a transition.
typedef struct ElgPose {
    float opacity, scale, x, y; ///< Opacity and scale (1: as is), and the offset in points.
    float anchor_x, anchor_y;   ///< What it scales around, as fractions of its frame (0.5: the middle).
} ElgPose;

/// The options of elg_text_field() (`TextFieldOptions`) and elg_text_area() (`TextAreaOptions`, which has no
/// `secure` or `line_limit`).
typedef struct ElgTextFieldOptions {
    /// Runs on Enter; in a text area, on Ctrl+Enter (Cmd+Enter on macOS). No args; may be none.
    ElgClosure on_submit;
    /// A bool prop: a password field (`TextFieldOptions::secure`). elg_text_area() doesn't read it (and
    /// drops its closure).
    ElgProp secure;
    /// An int prop: more than 1 wraps the text and grows up to this many lines (`TextFieldOptions::line_limit`).
    /// elg_text_area() doesn't read it (and drops its closure).
    ElgProp line_limit;
    /// Styles ranges of the text after every change (`TextFieldOptions::styler`); may be none.
    /// args: ElgStr* text, ret: std::vector<TextSpan>* (filled with elg_text_spans_push).
    ElgClosure styler;
    /// Sees key presses before the field does (`TextFieldOptions::on_key`); may be none.
    /// args: ElgKeyEvent*, ret: bool* (true takes the key, and the field ignores it).
    ElgClosure on_key;
} ElgTextFieldOptions;

/// The options of elg_number_input(): `NumberInputOptions`.
typedef struct ElgNumberInputOptions {
    /// Double props: the range, and the step of the arrows, Up/Down (Shift: 10 steps) and scrubbing.
    ElgProp min, max, step;
    /// An int prop: digits after the point; -1: as many as the value needs (up to 6).
    ElgProp decimals;
    /// Text for a value; none: a plain number. args: double*, ret: std::string* (write it with
    /// elg_string_assign).
    ElgClosure format;
    /// A value for text; none: plain numbers, ignoring spaces around them. args: ElgStr*, ret: ElgOptNumber*.
    ElgClosure parse;
    /// A bool prop: apply each valid number as it's typed, instead of on Enter or when the field loses focus.
    ElgProp live;
    ElgProp shows_buttons; ///< A bool prop: the style's increment and decrement buttons.
    /// A bool prop: dragging sideways on the field (while it isn't being edited) changes the value.
    ElgProp scrubs;
} ElgNumberInputOptions;

/// What ElgNumberInputOptions::parse writes: a number, or none.
typedef struct ElgOptNumber {
    bool has;     ///< false: the text isn't a number.
    double value; ///< The number, when `has`.
} ElgOptNumber;

/// One ForEach item (`detail::ForEachItem`), for elg_for_each_items_push().
typedef struct ElgForEachItem {
    bool key_is_string; ///< The item's key is `string_key`; otherwise `int_key`.
    int64_t int_key;    ///< The key, when it isn't a string.
    ElgStr string_key;  ///< The key, when it's a string (copied).
    /// Owns the Rust item, which Elegance keeps to compare with the next update's; its `call` is unused
    /// and may be null.
    ElgClosure value;
    /// Compares two items' Rust data (their `value` closures' `data`): true when they're equal, so the item
    /// keeps its view.
    bool (*equals)(void* a, void* b);
    ElgClosure view;    ///< Builds the item's view. ret: View*. Required: none is a usage error.
} ElgForEachItem;

/// Lines between a lazy stack's items (`StackSeparators`), for elg_lazy_stack().
typedef struct ElgStackSeparators {
    ElgProp color;   ///< A Color prop: the lines' color.
    float inset;     ///< From the leading edge (the top, in a horizontal stack), in points.
    float thickness; ///< The lines' thickness, in points.
} ElgStackSeparators;

/// How a split view's dividers look (`SplitViewOptions`).
typedef struct ElgSplitViewOptions {
    ElgProp divider;               ///< A Color prop: the line.
    const ElgProp* active_divider; ///< A Color prop for while it's hovered or dragged; null: the tint.
    float thickness;               ///< The line's thickness, in points.
    float active_thickness;        ///< Drawn over the line while it's hovered or dragged, in points.
} ElgSplitViewOptions;

/// A column's width range, in points (`ColumnWidth`).
typedef struct ElgColumnWidth {
    float min, ideal, max; ///< The narrowest, starting and widest width.
} ElgColumnWidth;

/// The options of elg_navigation_split_view(): `NavigationSplitViewOptions`.
typedef struct ElgNavigationSplitViewOptions {
    ElgBindingBool* take_sidebar_visible;    ///< Shows and hides the sidebar (consumed); null: always shown.
    const ElgTransition* sidebar_transition; ///< How the sidebar comes and goes (borrowed; required).
    ElgProp sidebar_background;              ///< A Color prop: behind the sidebar; clear: none.
    ElgColumnWidth sidebar_width;            ///< The sidebar's width range.
    ElgColumnWidth content_width;            ///< The content column's width range (the three-column form only).
    ElgColumnWidth detail_width;             ///< The detail's width range; an ideal of 0: the rest of the width.
    ElgSplitViewOptions dividers;            ///< How the dividers look.
} ElgNavigationSplitViewOptions;

/// One run of elg_styled_text() (`TextRun`).
typedef struct ElgTextRun {
    ElgStr text;           ///< The run's text (copied); newlines start paragraphs.
    ElgRunStyle style;     ///< How it looks; unset parts come from the environment.
    ElgClosure on_tap;     ///< Runs when the run is clicked (links, mentions). No args; none: not clickable.
    /// Shown in the line instead of the text, which stays the accessible label (consumed); null: none.
    ElgView* take_attachment;
    float attachment_size; ///< The attachment's square, in ems; it's centered on the line.
} ElgTextRun;

/// One flattened subpath (`Path::Polyline`): points joined by straight lines. What elg_path_flatten()'s
/// `polyline` gets.
typedef struct ElgPolyline {
    const ElgPoint* points; ///< The points, valid during the call.
    size_t count;           ///< How many `points` there are.
    bool closed;            ///< The last point joins the first.
} ElgPolyline;

/// Where an AsyncImage is (`AsyncImagePhase`): what elg_async_image_content()'s `content` gets.
typedef struct ElgAsyncImagePhase {
    int32_t kind;         ///< `AsyncImagePhase::Kind`: 0 loading, 1 success, 2 failure.
    const ElgView* image; ///< Success: the image, valid during the call (clone it to keep it).
    ElgStr error;         ///< Failure: why, valid during the call.
} ElgAsyncImagePhase;

/// A font file, or font data in memory (`IconFont`): `data` if it's set, else `file`, else none.
typedef struct ElgIconFont {
    ElgStr file;   ///< The font file's path.
    ElgBytes data; ///< The font data (copied when registered).
} ElgIconFont;

/// Another weight of an icon set (`IconSetOptions::weights`), for `.font_weight()`.
typedef struct ElgIconWeight {
    int32_t weight;   ///< The `Weight`, 1...1000.
    ElgIconFont font; ///< That weight's font.
} ElgIconWeight;

/// A variant of an icon set (`IconVariant`), named "set.icon.variant".
typedef struct ElgIconVariant {
    ElgStr name;       ///< The variant's name.
    ElgIconFont font;  ///< Its font.
    ElgStr names;      ///< Its own name map's file, when its codepoints differ from the set's; empty: the set's.
    ElgStr names_data; ///< Or that map's text (read during the call).
} ElgIconVariant;

/// The options of elg_mod_frame(): `FrameOptions`, or `FlexibleFrameOptions` when any minimum, ideal or
/// maximum is set. A fixed dimension in a flexible frame is its minimum, ideal and maximum.
typedef struct ElgFrameOptions {
    ElgOptLen width, height;                        ///< Fixed dimensions; unset ones follow the content.
    ElgOptLen min_width, ideal_width, max_width;    ///< A width range: the proposed width, clamped.
    ElgOptLen min_height, ideal_height, max_height; ///< A height range: the proposed height, clamped.
    ElgAlignment alignment;                         ///< Where the content sits in the frame.
} ElgFrameOptions;

/// How a pointer gesture competes with others for a press (`GestureOptions`).
typedef struct ElgGestureOptions {
    int32_t priority;  ///< `GesturePriority`: 0 normal, 1 high (offered the press before gestures inside).
    bool simultaneous; ///< Recognizes alongside whatever has the press, without taking it.
} ElgGestureOptions;

/// When a drag begins (`DragOptions`).
typedef struct ElgDragOptions {
    float minimum_distance; ///< How far the pointer moves, in points, before the drag begins; 0: on the press.
    int32_t button;         ///< `MouseButton`: 0 left, 1 middle, 2 right, 3 other.
    double hold;            ///< Seconds the press must be held before the drag can begin; 0: no hold.
    float hold_tolerance;   ///< How far the pointer may move during the hold, in points.
} ElgDragOptions;

/// When a press is long (`LongPressOptions`, without `pressing`).
typedef struct ElgLongPressOptions {
    double duration;        ///< Seconds the press is held.
    float maximum_distance; ///< How far the pointer may wander, in points, before the press stops counting.
    int32_t button;         ///< `MouseButton`: 0 left, 1 middle, 2 right, 3 other.
} ElgLongPressOptions;

/// Files dropped on a view: what elg_mod_on_drop()'s `files` gets.
typedef struct ElgDropFiles {
    const ElgStr* paths; ///< Their paths, in UTF-8, valid during the call.
    size_t count;        ///< How many `paths` there are.
    ElgPoint location;   ///< Where they were dropped, in the view's coordinates.
} ElgDropFiles;

/// Text dropped on a view: what elg_mod_on_drop()'s `text` gets.
typedef struct ElgDropText {
    ElgStr text;       ///< The text, valid during the call.
    ElgPoint location; ///< Where it was dropped, in the view's coordinates.
} ElgDropText;

/// The options of elg_mod_floating(): `FloatingOptions`.
typedef struct ElgFloatingOptions {
    ElgFloatingPlacement placement; ///< Where the content goes, by the view.
    int32_t boundary;               ///< `FloatingBoundary`: 0 screen, 1 window, 2 container.
    bool outside_click;             ///< A press anywhere outside closes it (and only closes it).
    bool escape;                    ///< Esc closes it, unless something focused handles it first.
    ElgPopupMotion motion;          ///< How it opens and closes; `has` false: at once.
} ElgFloatingOptions;

/// The options of elg_mod_tooltip(): `TooltipOptions`.
typedef struct ElgTooltipOptions {
    ElgFloatingPlacement placement; ///< Where the tooltip goes, by the view.
    int32_t boundary;               ///< `FloatingBoundary`: 0 screen, 1 window, 2 container.
    double delay;                   ///< Seconds the pointer rests on the view before it shows.
    ElgPopupMotion motion;          ///< How it opens and closes; `has` false: the TooltipStyle's.
} ElgTooltipOptions;

/// A ForEach key (`ItemKey`), for selections.
typedef struct ElgItemKey {
    bool is_string;    ///< The key is `string_key`; otherwise `int_key`.
    int64_t int_key;   ///< The key, when it isn't a string.
    ElgStr string_key; ///< The key, when it's a string.
} ElgItemKey;

/// Selected keys: what elg_mod_selection()'s `set` gets.
typedef struct ElgItemKeys {
    const ElgItemKey* keys; ///< The keys, valid during the call.
    size_t count;           ///< How many `keys` there are.
} ElgItemKeys;

/// One preview of a Rust views module, for elg_rust_module_entry() (`PreviewEntry`).
typedef struct ElgPreviewDesc {
    ElgStr name;  ///< The preview's name (copied).
    ElgStr file;  ///< The source file it's in (copied).
    int32_t line; ///< Its line in `file`.
} ElgPreviewDesc;

/// Builds view `index` into `ret` (-1: the root view; otherwise a preview); false if it panicked.
typedef bool (*ElgModuleBuild)(int32_t index, ElgView* ret);

/// How a VGrid column or HGrid row is sized (`GridItem`).
typedef struct ElgGridItem {
    int32_t kind;           ///< `GridItem::Kind`: 0 fixed (exactly `minimum` points), 1 flexible, 2 adaptive.
    float minimum;          ///< The least a track takes, in points.
    float maximum;          ///< The most a flexible or adaptive track takes, in points.
    ElgOptLen spacing;      ///< After this track (between its tracks too, if adaptive); unset: the grid's.
    bool has_alignment;     ///< `alignment` is set; otherwise the grid's.
    ElgAlignment alignment; ///< Where views sit in this track's cells.
} ElgGridItem;

/// One resolved track (`GridTrack`): what elg_resolve_grid_tracks()'s `each` gets.
typedef struct ElgGridTrack {
    float size;             ///< The track's size, in points.
    float spacing;          ///< The space after it, in points.
    bool has_alignment;     ///< `alignment` is set (its item's).
    ElgAlignment alignment; ///< Where views sit in its cells.
} ElgGridTrack;

/// A VGrid or HGrid (kind 0 or 1: tracks `items`, `spacing_a` between lines) or a Grid (kind 2: `spacing_a`
/// between columns, `spacing_b` between rows).
typedef struct ElgGridDesc {
    int32_t kind;             ///< 0 VGrid, 1 HGrid, anything else Grid.
    const ElgGridItem* items; ///< A VGrid's columns or an HGrid's rows (borrowed).
    size_t item_count;        ///< How many `items` there are.
    ElgAlignment alignment;   ///< Of views in their cells (and of a VGrid's or HGrid's tracks).
    /// Between a VGrid's rows or an HGrid's columns (and tracks without their own), or a Grid's columns; unset:
    /// `default_stack_spacing`.
    ElgOptLen spacing_a;
    ElgOptLen spacing_b;      ///< Between a Grid's rows (unused by VGrid and HGrid); unset: `default_stack_spacing`.
} ElgGridDesc;

/// What a Rust layout's closure (elg_rust_layout_view()) is asked to do: one of elg::Layout's
/// methods.
typedef struct ElgLayoutCall {
    /// 0: size_that_fits (ret ElgSize*), 1: place_children, 2: spacer_axis (ret int32_t*: -1 none,
    /// else an elg::Axis, 0 horizontal or 1 vertical).
    int32_t op;
    ElgProposedSize proposal;       ///< Ops 0 and 1: the size the parent proposes.
    ElgRect bounds;                 ///< Op 1: where the children go, with the size reported for `proposal`.
    const ElgLayoutChild* children; ///< Ops 0 and 1: the children, valid during the call.
    size_t count;                   ///< Number of `children`.
    /// Ops 0 and 1: the view's cache storage, for the elg_layout_cache_* functions, valid during the
    /// call; null: uncached.
    ElgLayoutCache* cache;
} ElgLayoutCall;

/// What a Rust layout modifier's closure (elg_mod_rust_layout_modifier()) is asked to do: one of
/// elg::LayoutModifier's methods.
typedef struct ElgLayoutModifierCall {
    int32_t op;                    ///< 0: size_that_fits (ret ElgSize*), 1: place, 2: layout_priority (ret ElgOptLen*)
    ElgProposedSize proposal;      ///< Ops 0 and 1: the size the parent proposes.
    ElgRect bounds;                ///< Op 1: where the view goes, with the size reported for `proposal`.
    const ElgLayoutChild* content; ///< Ops 0 and 1: the wrapped content, valid during the call; op 2: null.
} ElgLayoutModifierCall;

/// An event for a Rust event handler (elg_mod_rust_event_modifier()): a call of one of
/// elg::EventHandler's methods.
typedef struct ElgEventCall {
    /// 0 pointer, 1 hover, 2 scroll, 3 key, 4 focusable (ret bool*), 5 focus, 6 accepts_text_input
    /// (ret bool*), 7 text_input, 8 hover_delay (ret ElgOptHoverDelay*), 9 covers_frame (ret bool*),
    /// 10 pointer_style (ret int32_t*), 11 magnify, 12 rotate, 13 two_finger_double_tap.
    /// The others: ret ElgEventResult*. `frame`: pointer and scroll.
    int32_t op;
    ElgPointerEvent pointer; ///< Op 0: the event.
    ElgRect frame;           ///< Ops 0 and 2: the view's current frame, in window coordinates.
    bool flag;               ///< hover: inside; focus: focused
    ElgScrollEvent scroll;   ///< Op 2: the event.
    ElgKeyEvent key;         ///< Op 3: the event.
    ElgTextInputEvent text;  ///< Op 7: the event; its text is valid during the call.
    ElgPoint location;       ///< pointer_style, two_finger_double_tap
    ElgMagnifyEvent magnify; ///< Op 11: the event.
    ElgRotateEvent rotate;   ///< Op 12: the event.
} ElgEventCall;

/// An optional elg::HoverDelay, an event handler's own (ElgEventCall op 8).
typedef struct ElgOptHoverDelay {
    bool has;            ///< false: the environment's delay.
    ElgHoverDelay delay; ///< The delay, if `has`.
} ElgOptHoverDelay;

/// An audio device (elg::AudioDevice) or a camera (elg::CameraDevice), passed to a callback.
typedef struct ElgDevice {
    ElgStr id;       ///< For a `device_id` argument; valid during the callback.
    ElgStr name;     ///< As the system shows it; valid during the callback.
    bool is_default; ///< The system's default device; always false for cameras.
} ElgDevice;

/// A buffer for an audio stream's `on_render` closure to fill.
typedef struct ElgRenderBuffer {
    float* samples; ///< Interleaved samples, -1 to 1, zeroed beforehand; valid during the call.
    size_t count;   ///< Number of samples (frames times channels).
} ElgRenderBuffer;

/// Recorded samples, passed to a callback.
typedef struct ElgSamples {
    const float* samples; ///< Interleaved samples, -1 to 1; valid during the callback.
    size_t count;         ///< Number of samples (frames times channels).
} ElgSamples;

/// An elg::FileFilter: a choice in a file dialog's type list, e.g. "Images" with png and jpg.
typedef struct ElgFileFilter {
    ElgStr name;              ///< What the dialog shows.
    const ElgStr* extensions; ///< Extensions without the dot, read during the call; none: all files.
    size_t extension_count;   ///< Number of `extensions`.
} ElgFileFilter;

/// Paths a dialog's `done` closure gets.
typedef struct ElgPaths {
    const ElgStr* paths; ///< UTF-8 paths, valid during the callback.
    size_t count;        ///< Number of `paths`; 0 if the dialog was cancelled.
} ElgPaths;

/// An elg::TrayMenuItem: a command, a check box, a submenu, or a separator (an empty title). The
/// function that takes the menu consumes its closures.
typedef struct ElgTrayMenuItem {
    ElgStr title;                          ///< What the menu shows; empty: a separator.
    ElgClosure action;                     ///< Runs when chosen (`call` null: none); args and ret: null.
    int32_t checked;                       ///< -1: not a check box, 0/1: initially unchecked/checked
    /// Check boxes: runs when chosen, with the new state (`call` null: none); args: bool*, ret: null.
    ElgClosure toggled;
    bool enabled;                          ///< false: it can't be chosen.
    const struct ElgTrayMenuItem* submenu; ///< The submenu's items, read during the call.
    size_t submenu_count;                  ///< Number of `submenu` items; 0: no submenu.
} ElgTrayMenuItem;

/// The options of elg_switch_toggle_style(): `SwitchToggleStyleOptions`.
typedef struct ElgSwitchToggleStyleOptions {
    const ElgProp* on;             ///< A Color prop: the track while on; null: the tint.
    ElgProp off;                   ///< A Color prop: the track while off.
    ElgProp knob;                  ///< A Color prop: the knob.
    /// The switch's width and height, the gap between the knob and the track's edge, and the space between the
    /// label and the switch, in points.
    float width, height, knob_inset, spacing;
    /// The label at the leading edge and the switch at the trailing one, across the width it's offered (a
    /// settings row); false: as wide as the label and the switch.
    bool fills_width;
    const ElgAnimation* animation; ///< How a flip animates (borrowed); null: it flips at once.
} ElgSwitchToggleStyleOptions;

/// The options of elg_box_checkbox_style(): `BoxCheckboxStyleOptions`.
typedef struct ElgBoxCheckboxStyleOptions {
    float size, corner_radius;     ///< The box's size and corner radius, in points.
    const ElgProp* fill;           ///< A Color prop: the box while checked or mixed; null: the tint.
    ElgProp empty;                 ///< A Color prop: the box while unchecked.
    ElgProp border;                ///< A Color prop: the outline while unchecked (checked or mixed, it's the fill).
    float border_width;            ///< The outline's width, in points.
    ElgProp mark;                  ///< A Color prop: the check and the dash.
    ElgView* take_check;           ///< Shown while checked (consumed); null: a check mark.
    ElgView* take_dash;            ///< Shown while mixed (consumed); null: a dash.
    float spacing;                 ///< Between the box and the label, in points.
    const ElgAnimation* animation; ///< How checking and unchecking animate (borrowed); null: at once.
} ElgBoxCheckboxStyleOptions;

/// The options of a `BoxNumberInputStyle` (`BoxNumberInputStyleOptions`), for elg_number_input_style_builtin().
typedef struct ElgBoxNumberInputStyleOptions {
    ElgProp background;                ///< A Color prop: the box.
    ElgProp border;                    ///< A Color prop: the outline.
    const ElgProp* focused_border;     ///< A Color prop: the outline while editing; null: the tint.
    float border_width, corner_radius; ///< The outline's width and the box's corner radius, in points.
    ElgEdgeInsets padding;             ///< Around the number, inside the box.
    float arrow_size;                  ///< The stacked arrows' icons, in points.
} ElgBoxNumberInputStyleOptions;

/// The options of elg_progress_style_builtin(): `LinearProgressStyleOptions` or
/// `CircularProgressStyleOptions`.
typedef struct ElgProgressStyleOptions {
    ElgProp track;       ///< A Color prop: the track.
    const ElgProp* fill; ///< A Color prop: the fill; null: the tint.
    float a;             ///< Linear: the bar's thickness; circular: the ring's diameter. In points.
    float b;             ///< Circular: the ring's line width, in points; unused by the linear style.
} ElgProgressStyleOptions;

/// The options of elg_knob_slider_style(): `KnobSliderStyleOptions`.
typedef struct ElgKnobSliderStyleOptions {
    ElgProp track;         ///< A Color prop: the track.
    const ElgProp* fill;   ///< A Color prop: the track up to the knob; null: the tint.
    float track_thickness; ///< The track's thickness, in points.
    float knob_size;       ///< The knob's diameter, in points.
} ElgKnobSliderStyleOptions;

/// The options of a `BarNavigationStackStyle` (`BarNavigationStackStyleOptions`), for
/// elg_navigation_stack_style_builtin().
typedef struct ElgBarNavigationStackStyleOptions {
    float height;              ///< The bar's height, in points.
    ElgProp background;        ///< A Color prop: behind the bar.
    ElgFont title_font;        ///< The title's font.
    const ElgProp* back_color; ///< A Color prop: the back button; null: the tint.
    bool shows_divider;        ///< A line under the bar.
} ElgBarNavigationStackStyleOptions;

/// The options of a `HighlightRowStyle` (`HighlightRowStyleOptions`), for elg_row_style_builtin().
typedef struct ElgHighlightRowStyleOptions {
    const ElgProp* selected; ///< A Color prop: the selected rows' highlight; null: the tint.
    ElgProp on_selected;     ///< A Color prop: the selected rows' text and icons.
    ElgProp hovered;         ///< A Color prop: the hovered row's highlight, drawn at half opacity.
    float corner_radius;     ///< The highlight's corner radius, in points.
    ElgEdgeInsets padding;   ///< Around the content, inside the highlight.
} ElgHighlightRowStyleOptions;

// --- Errors ---

/// Takes this thread's pending error: the pending error's kind (0: none), with its message sent to
/// `out`; clears it. A call that fails records its exception here, replacing any earlier one.
/// Callable from any thread.
///
/// @param out Receives the message, if there's an error.
/// @param ctx Passed to `out`.
/// @return The error's kind: 0 none, 1 a Rust callback panicked, 2 elg::UsageError,
///   3 elg::ResourceError, 4 elg::GpuError, 5 elg::PlatformError, 6 another elg::Error, 7 any other
///   C++ exception. 0 on failure.
int32_t elg_take_error(ElgStrSink out, void* ctx);

/// Whether this thread has an error that elg_take_error() hasn't taken yet.
/// Callable from any thread.
///
/// @return true if an error is pending. False on failure.
bool elg_error_pending(void);

/// Sets a C++ std::string: how a closure returns a string (ret: `std::string*`), as a
/// `Binding<std::string>` getter or a string prop does.
///
/// @param target The string to set (borrowed).
/// @param value The new contents, copied.
void elg_string_assign(ElgCppString* target, ElgStr value);

/// The contents of a C++ std::string, such as a closure's `std::string*` argument.
///
/// @param s The string (borrowed).
/// @return Its bytes, valid while `s` lives and doesn't change. Empty on failure.
ElgStr elg_string_view(const ElgCppString* s);

// --- Views ---

/// Wraps `View()`: an empty view, which takes no space and draws nothing.
///
/// @return The new view, owned by the caller. Null on failure.
ElgView* elg_view_empty(void);

/// Copies a view (an immutable value, cheap to copy).
///
/// @param view The view (borrowed).
/// @return The copy, owned by the caller. Null on failure.
ElgView* elg_view_clone(const ElgView* view);

/// Frees a view.
///
/// @param view The view (consumed); may be null.
void elg_view_free(ElgView* view);

/// Moves `take_view` into `*target` (a closure's View result).
///
/// @param target The closure's `ret` (borrowed); what it held is replaced.
/// @param take_view The view (consumed).
void elg_view_move_into(ElgView* target, ElgView* take_view);

/// Wraps `View::is_empty()`: whether this is an empty view (View(), EmptyView()), e.g. a style's
/// label for a control made without one.
///
/// @param view The view (borrowed).
/// @return true if it's empty. False on failure.
bool elg_view_is_empty(const ElgView* view);

/// A Rust component: `body` (ret: View*) runs each time the view is mounted. The C++ side of a
/// component (a type with `View body() const`).
///
/// @param body Consumed closure; args: null, ret: `View*` (set it with elg_view_move_into()).
///   Required: none is a usage error.
/// @return The new view, owned by the caller, or nullptr on failure.
ElgView* elg_view_component(ElgClosure body);

// --- Reactive state ---

/// A signal node owning `owner`: the C++ side of a Rust State, for dependency tracking. It belongs
/// to the current Scope and ends with it; made outside any scope (before App::run), it lives for
/// the whole program.
///
/// @param owner Consumed closure that's never called; its `drop` runs when the node ends.
/// @return A handle to the node, for elg_node_track() and elg_node_notify(); its scope owns the
///   node, not the caller. Once the node has ended, using the handle is a usage error. 0 on failure.
uint64_t elg_signal_new(ElgClosure owner);

/// A computed node: the C++ side of a Rust Computed, owned by the current Scope like
/// elg_signal_new()'s. `compute` (ret: uint64_t*) brings the Rust value up to date and returns a
/// version that changes whenever the value does.
///
/// @param compute Consumed closure, run when the node is read and may have changed; args: null,
///   ret: `uint64_t*`. When the version stays the same, the node's dependents don't rerun.
///   Required: none is a usage error.
/// @return A handle to the node, for elg_node_track(); its scope owns the node, not the caller.
///   Once the node has ended, using the handle is a usage error. 0 on failure.
uint64_t elg_computed_new(ElgClosure compute);

/// A read (`ReactiveNode::track()`): subscribes the running computed/effect, bringing a computed
/// up to date first.
///
/// @param node A handle from elg_signal_new() or elg_computed_new(); one whose node has ended is a
///   usage error.
void elg_node_track(uint64_t node);

/// A write happened (UI thread only): `ReactiveNode::notify_changed()` marks the node's dependents
/// and schedules the effects it affects. Off the UI thread, records a UsageError instead.
///
/// @param node A handle from elg_signal_new(); one whose node has ended is a usage error.
void elg_node_notify(uint64_t node);

/// Records a UsageError when called off the UI thread of a running App, as every function of the
/// UI thread does: for a binding to check where it is before work of its own.
void elg_check_ui_thread(void);

/// Wraps `elg::effect()`: runs `function` now and again whenever state it read changes (after the
/// current event, before the next frame). Call it while building views; it ends when those views
/// are removed. Elsewhere it records a UsageError.
///
/// @param function Consumed closure; args and ret: null. Required: none is a usage error.
void elg_effect(ElgClosure function);

/// Runs `function` (borrowed) without tracking reads: `elg::untrack()`.
///
/// @param function Borrowed closure, called once before this returns; args and ret: null.
///   Required: none is a usage error.
void elg_untrack(ElgClosure function);

/// Wraps `elg::batch()`: runs `function`, grouping its writes so that effects run once, after the
/// outermost batch ends.
///
/// @param function Borrowed closure, called once before this returns; args and ret: null.
///   Required: none is a usage error.
void elg_batch(ElgClosure function);

/// Wraps `elg::with_animation()`: runs `changes` in an animated transaction, so every property
/// change its writes cause animates with `animation`, including layout and If/ForEach insertions
/// and removals.
///
/// @param animation The animation (borrowed).
/// @param changes Borrowed closure, called once before this returns; args and ret: null.
///   Required: none is a usage error.
void elg_with_animation(const ElgAnimation* animation, ElgClosure changes);

// --- Bindings to the C++ value types controls take ---

/// A `Binding<bool>` over a Rust value, for a control: `get` reads it, `set` writes it.
///
/// @param get Consumed closure; args: null, ret: `bool*`. Required: none is a usage error.
/// @param set Consumed closure; args: `bool*` (the new value), ret: null. Required: none is a
///   usage error.
/// @return The binding, owned by the caller until a function takes it (`take_*`) or
///   elg_binding_bool_free() frees it; nullptr on failure.
ElgBindingBool* elg_binding_bool(ElgClosure get, ElgClosure set);

/// A `Binding<float>` over a Rust value, for a control: `get` reads it, `set` writes it.
///
/// @param get Consumed closure; args: null, ret: `float*`. Required: none is a usage error.
/// @param set Consumed closure; args: `float*` (the new value), ret: null. Required: none is a
///   usage error.
/// @return The binding, owned by the caller until a function takes it (`take_*`) or
///   elg_binding_f32_free() frees it; nullptr on failure.
ElgBindingF32* elg_binding_f32(ElgClosure get, ElgClosure set);

/// A `Binding<int>` over a Rust value, for a control: `get` reads it, `set` writes it.
///
/// @param get Consumed closure; args: null, ret: `int32_t*`. Required: none is a usage error.
/// @param set Consumed closure; args: `int32_t*` (the new value), ret: null. Required: none is a
///   usage error.
/// @return The binding, owned by the caller until a function takes it (`take_*`) or
///   elg_binding_i32_free() frees it; nullptr on failure.
ElgBindingI32* elg_binding_i32(ElgClosure get, ElgClosure set);

/// A `Binding<std::string>` over a Rust value, for a control: `get` reads it, `set` writes it.
///
/// @param get Consumed closure; args: null, ret: `std::string*` (set it with elg_string_assign()).
///   Required: none is a usage error.
/// @param set Consumed closure; args: `std::string*`, the new value (read it with elg_string_view());
///   ret: null. Required: none is a usage error.
/// @return The binding, owned by the caller until a function takes it (`take_*`) or
///   elg_binding_string_free() frees it; nullptr on failure.
ElgBindingString* elg_binding_string(ElgClosure get, ElgClosure set);

/// A `Binding<double>` over a Rust value, for a control: `get` reads it, `set` writes it.
///
/// @param get Consumed closure; args: null, ret: `double*`. Required: none is a usage error.
/// @param set Consumed closure; args: `double*` (the new value), ret: null. Required: none is a
///   usage error.
/// @return The binding, owned by the caller until a function takes it (`take_*`) or
///   elg_binding_f64_free() frees it; nullptr on failure.
ElgBindingF64* elg_binding_f64(ElgClosure get, ElgClosure set);

/// Writes an optional float into a closure's std::optional<float> result.
///
/// @param target The closure's `ret` (borrowed).
/// @param value The value; `has` false: nullopt.
void elg_opt_float_assign(ElgOptFloat* target, ElgOptLen value);

/// Reads a binding made by Elegance (AudioPlayer::time_binding, ...): `Binding<float>::get()`.
///
/// @param binding The binding (borrowed).
/// @return The value, or 0 on failure.
float elg_binding_f32_get(const ElgBindingF32* binding);

/// Writes a binding made by Elegance: `Binding<float>::set()` (an audio player's time binding
/// seeks, ...).
///
/// @param binding The binding (borrowed).
/// @param value The new value.
void elg_binding_f32_set(const ElgBindingF32* binding, float value);

/// Frees a `Binding<float>` the caller owns, from elg_audio_player_binding(), elg_binding_f32(), ...
///
/// @param binding The binding (consumed); may be null.
void elg_binding_f32_free(ElgBindingF32* binding);

/// Frees a `Binding<bool>` the caller owns, from elg_binding_bool().
///
/// @param binding The binding (consumed); may be null.
void elg_binding_bool_free(ElgBindingBool* binding);

/// Frees a `Binding<int>` the caller owns, from elg_binding_i32().
///
/// @param binding The binding (consumed); may be null.
void elg_binding_i32_free(ElgBindingI32* binding);

/// Frees a `Binding<std::string>` the caller owns, from elg_binding_string().
///
/// @param binding The binding (consumed); may be null.
void elg_binding_string_free(ElgBindingString* binding);

/// Frees a `Binding<double>` the caller owns, from elg_binding_f64().
///
/// @param binding The binding (consumed); may be null.
void elg_binding_f64_free(ElgBindingF64* binding);

// --- Environment ---

/// A copy of the environment of the views being built (`detail::current_environment()`), as
/// `Environment<Key>()` reads it: while a body, a modifier's body, a style's make_body, or a
/// window's content function runs.
///
/// @return The environment, owned by the caller (elg_env_free()), or nullptr with a UsageError
///   when no views are being built.
ElgEnvironmentValues* elg_env_current(void);

/// An empty environment (`EnvironmentValues()`): every key reads its default.
///
/// @return The environment, owned by the caller (elg_env_free()). Null on failure.
ElgEnvironmentValues* elg_env_new(void);

/// Copies an environment (cheap: copies share their entries).
///
/// @param environment The environment (borrowed).
/// @return The copy, owned by the caller. Null on failure.
ElgEnvironmentValues* elg_env_clone(const ElgEnvironmentValues* environment);

/// Frees an environment.
///
/// @param environment The environment (consumed); may be null.
void elg_env_free(ElgEnvironmentValues* environment);

/// Wraps `EnvironmentValues::color()`: a semantic color in this environment's theme and color
/// scheme. A tracked read.
///
/// @param environment The environment (borrowed).
/// @param token An elg::ThemeColor.
/// @return The color, or all zeros on failure.
ElgColor elg_env_color(const ElgEnvironmentValues* environment, int32_t token);

/// Reads the environment's font (FontKey). A tracked read.
///
/// @param environment The environment (borrowed).
/// @param family Receives the font's family; empty for the system font.
/// @param ctx Passed to `family`.
/// @param size Receives the size in points.
/// @param weight Receives the elg::Weight.
/// @param italic Receives whether it's italic.
void elg_env_font(const ElgEnvironmentValues* environment, ElgStrSink family, void* ctx, float* size, int32_t* weight, bool* italic);

/// Reads the environment's color scheme (ColorSchemeKey). A tracked read.
///
/// @param environment The environment (borrowed).
/// @return The elg::ColorScheme: 0 light, 1 dark. 0 on failure.
int32_t elg_env_color_scheme(const ElgEnvironmentValues* environment);

/// Reads the environment's theme (ThemeKey). A tracked read.
///
/// @param environment The environment (borrowed).
/// @param result Receives the theme (borrowed); left as it was on failure.
void elg_env_theme(const ElgEnvironmentValues* environment, ElgTheme* result);

/// Wraps `system_accent_color()`: the accent color the person chose in the system's settings.
/// Reactive while an App runs (a tracked read, on the UI thread); without one, it asks the system
/// each time.
///
/// @param color Receives the color when there is one; left as it was otherwise.
/// @return Whether the system has an accent color; false on failure.
bool elg_system_accent_color(ElgColor* color);

/// Reads the environment's foreground (ForegroundKey): the color of text and unfilled shapes. A
/// tracked read.
///
/// @param environment The environment (borrowed).
/// @return The color, or all zeros on failure.
ElgColor elg_env_foreground(const ElgEnvironmentValues* environment);

/// Reads the environment's tint (TintKey): the accent color of controls. A tracked read.
///
/// @param environment The environment (borrowed).
/// @return The color, or all zeros on failure.
ElgColor elg_env_tint(const ElgEnvironmentValues* environment);

/// Reads DisabledKey: controls inside a disabled view don't respond to input and look disabled. A
/// tracked read.
///
/// @param environment The environment (borrowed).
/// @return true if disabled; false on failure.
bool elg_env_disabled(const ElgEnvironmentValues* environment);

/// Reads the environment's hover delay (HoverDelayKey). A tracked read.
///
/// @param environment The environment (borrowed).
/// @return The delay, or zeros on failure.
ElgHoverDelay elg_env_hover_delay(const ElgEnvironmentValues* environment);

/// Reads the window the views are in (WindowKey). Outside any window, the handle does nothing.
///
/// @param environment The environment (borrowed).
/// @return The window's handle, owned by the caller (elg_window_free()), or nullptr on failure.
ElgWindowHandle* elg_env_window(const ElgEnvironmentValues* environment);

/// Reads the environment's button style (ButtonStyleKey).
///
/// @param environment The environment (borrowed).
/// @return The style, owned by the caller (elg_button_style_free()), or nullptr on failure.
ElgButtonStyle* elg_env_button_style(const ElgEnvironmentValues* environment);

/// Reads the environment's toggle style (ToggleStyleKey).
///
/// @param environment The environment (borrowed).
/// @return The style, owned by the caller (elg_toggle_style_free()), or nullptr on failure.
ElgToggleStyle* elg_env_toggle_style(const ElgEnvironmentValues* environment);

/// Reads the environment's text field style (TextFieldStyleKey).
///
/// @param environment The environment (borrowed).
/// @return The style, owned by the caller (elg_text_field_style_free()), or nullptr on failure.
ElgTextFieldStyle* elg_env_text_field_style(const ElgEnvironmentValues* environment);

/// Inside a selectable row: whether it's selected (RowSelectedKey). A tracked read.
///
/// @param environment The environment (borrowed).
/// @return true inside a selected row; false elsewhere and on failure.
bool elg_env_row_selected(const ElgEnvironmentValues* environment);

/// The Rust side's map, or null: the `data` of the closure elg_env_set_rust_values() set.
///
/// @param environment The environment (borrowed).
/// @return The map, owned by the environment; null if none was set, or on failure.
void* elg_env_rust_values(const ElgEnvironmentValues* environment);

/// Sets the font (FontKey).
///
/// @param environment The environment to change (borrowed): an environment modifier's `args`.
/// @param value The font: an ElgProp of elg::Font (kind 0: `ElgFont*`; kinds 1 and 2 write it with
///   elg_font_assign()).
void elg_env_set_font(ElgEnvironmentValues* environment, ElgProp value);

/// Sets the color scheme (ColorSchemeKey).
///
/// @param environment The environment to change (borrowed).
/// @param value The scheme: an ElgProp of elg::ColorScheme (kind 0: `int32_t*`, 0 light, 1 dark).
void elg_env_set_color_scheme(ElgEnvironmentValues* environment, ElgProp value);

/// Sets the theme (ThemeKey).
///
/// @param environment The environment to change (borrowed).
/// @param value The theme: an ElgProp of elg::Theme (kind 0: `ElgTheme*`).
void elg_env_set_theme(ElgEnvironmentValues* environment, ElgProp value);

/// Sets the foreground (ForegroundKey): the color of text and unfilled shapes.
///
/// @param environment The environment to change (borrowed).
/// @param value The color: an ElgProp of elg::Color (kind 0: `ElgColor*`; kind 3: a theme color).
void elg_env_set_foreground(ElgEnvironmentValues* environment, ElgProp value);

/// Sets the tint (TintKey): the accent color of controls.
///
/// @param environment The environment to change (borrowed).
/// @param value The color: an ElgProp of elg::Color (kind 0: `ElgColor*`; kind 3: a theme color).
void elg_env_set_tint(ElgEnvironmentValues* environment, ElgProp value);

/// Sets DisabledKey: controls inside don't respond to input and look disabled.
///
/// @param environment The environment to change (borrowed).
/// @param value Whether they're disabled: an ElgProp of bool (kind 0: `bool*`).
void elg_env_set_disabled(ElgEnvironmentValues* environment, ElgProp value);

/// Sets the hover delay (HoverDelayKey), for on_hover handlers without their own and controls.
///
/// @param environment The environment to change (borrowed).
/// @param value The delay: an ElgProp of elg::HoverDelay (kind 0: `ElgHoverDelay*`).
void elg_env_set_hover_delay(ElgEnvironmentValues* environment, ElgProp value);

/// Sets RowSelectedKey: whether the views are in a selected row.
///
/// @param environment The environment to change (borrowed).
/// @param value Whether it's selected: an ElgProp of bool (kind 0: `bool*`).
void elg_env_set_row_selected(ElgEnvironmentValues* environment, ElgProp value);

/// Sets the window the views are in (WindowKey).
///
/// @param environment The environment to change (borrowed).
/// @param window The window's handle (borrowed; copied).
void elg_env_set_window(ElgEnvironmentValues* environment, const ElgWindowHandle* window);

/// Sets the button style (ButtonStyleKey).
///
/// @param environment The environment to change (borrowed).
/// @param style The style (borrowed; the environment shares it).
void elg_env_set_button_style(ElgEnvironmentValues* environment, const ElgButtonStyle* style);

/// Sets the toggle style (ToggleStyleKey).
///
/// @param environment The environment to change (borrowed).
/// @param style The style (borrowed; the environment shares it).
void elg_env_set_toggle_style(ElgEnvironmentValues* environment, const ElgToggleStyle* style);

/// Sets the text field style (TextFieldStyleKey).
///
/// @param environment The environment to change (borrowed).
/// @param style The style (borrowed; the environment shares it).
void elg_env_set_text_field_style(ElgEnvironmentValues* environment, const ElgTextFieldStyle* style);

/// Sets the Rust side's map of environment values, which elg_env_rust_values() returns.
///
/// @param environment The environment to change (borrowed).
/// @param values Consumed closure that's never called: its `data` is the map, and its `drop` runs
///   once no environment refers to it.
void elg_env_set_rust_values(ElgEnvironmentValues* environment, ElgClosure values);

// --- Windows ---

/// Copies a window handle; the copy refers to the same window.
///
/// @param window The handle (borrowed).
/// @return The copy, owned by the caller. Null on failure.
ElgWindowHandle* elg_window_clone(const ElgWindowHandle* window);

/// Frees a window handle (not the window).
///
/// @param window The handle (consumed); may be null.
void elg_window_free(ElgWindowHandle* window);

/// Whether two handles refer to the same window (`WindowHandle`'s operator==).
///
/// @param a A handle (borrowed).
/// @param b Another handle (borrowed).
/// @return true for the same window, or for two handles outside any window. False on failure.
bool elg_window_eq(const ElgWindowHandle* a, const ElgWindowHandle* b);

/// Wraps `WindowHandle::close()`: like the system close button, the window closes (the app quits
/// with its last window).
///
/// @param window The window's handle (borrowed).
void elg_window_close(const ElgWindowHandle* window);

/// Wraps `WindowHandle::minimize()`.
///
/// @param window The window's handle (borrowed).
void elg_window_minimize(const ElgWindowHandle* window);

/// Wraps `WindowHandle::toggle_maximized()`: maximizes the window, or restores a maximized one.
///
/// @param window The window's handle (borrowed).
void elg_window_toggle_maximized(const ElgWindowHandle* window);

/// Wraps `WindowHandle::is_maximized()`. A tracked read.
///
/// @param window The window's handle (borrowed).
/// @return true if the window is maximized; false outside any window and on failure.
bool elg_window_is_maximized(const ElgWindowHandle* window);

/// Wraps `WindowHandle::is_active()`: whether the window has keyboard focus (title bars usually dim
/// when it doesn't). A tracked read.
///
/// @param window The window's handle (borrowed).
/// @return true if the window is active, and outside any window; false on failure.
bool elg_window_is_active(const ElgWindowHandle* window);

/// Wraps `WindowHandle::title_bar()`: the window's WindowDesc::title_bar.
///
/// @param window The window's handle (borrowed).
/// @return The elg::TitleBar: 0 system, 1 hidden, 2 integrated. 0 outside any window and on
///   failure.
int32_t elg_window_title_bar(const ElgWindowHandle* window);

/// Wraps `WindowHandle::system_controls_frame()`: where the system draws its window controls over
/// the content (the traffic lights of a TitleBar::integrated window on macOS), in the window's
/// points. Keep content clear of it.
///
/// @param window The window's handle (borrowed).
/// @return The frame; empty where the system doesn't draw over the content, and on failure.
ElgRect elg_window_system_controls_frame(const ElgWindowHandle* window);

/// Wraps `WindowControls()`: minimize, maximize/restore, and close buttons for a custom title bar.
/// They act on the window they're in, and dim while it isn't active.
///
/// @param style An elg::WindowControlsStyle: 0 automatic (the platform's, and only in
///   TitleBar::hidden windows), 1 caption buttons, 2 traffic lights.
/// @param minimize Whether to show the minimize button.
/// @param maximize Whether to show the maximize/restore button.
/// @return The new view, owned by the caller, or nullptr on failure.
ElgView* elg_window_controls(int32_t style, bool minimize, bool maximize);

// --- App ---

/// Wraps `App()`: owns the application's lifetime, windows, event loop, and render thread.
///
/// @return The new app, owned by the caller (elg_app_free()), or nullptr on failure.
ElgApp* elg_app_new(void);

/// Destroys an app.
///
/// @param app The app (consumed); may be null.
void elg_app_free(ElgApp* app);

/// Wraps `App::window()`: adds a window that opens when the app runs. `content` (ret: View*)
/// builds the window's root view when it opens. Records a UsageError while the app runs.
///
/// @param app The app (borrowed).
/// @param desc How the window opens (borrowed).
/// @param content Consumed closure, called once on the UI thread; args: null, ret: `View*` (set
///   it with elg_view_move_into()). Required: none is a usage error.
void elg_app_window(ElgApp* app, const ElgWindowDesc* desc, ElgClosure content);

/// Wraps `App::run()`: opens the windows and runs the event loop until the last window closes or
/// elg_app_quit() is called. Errors and panics in app callbacks are written to the log and passed
/// to elg_app_on_error()'s handler, and the app goes on, unless the handler ends the run.
///
/// @param app The app (borrowed).
/// @return The process exit code, or -1 on failure (no windows, already running, an error the
///   error handler ended the run with, or one of Elegance's own).
int32_t elg_app_run(ElgApp* app);

/// Wraps `App::on_error()`: calls `handler` with each exception that escapes app code while the app
/// runs, binding callbacks included, on the UI thread between events.
///
/// @param app The app (borrowed).
/// @param handler Consumed closure; args: `const ElgAppError*`, valid during the call; ret:
///   `int32_t*`, which it sets to 1 to end the run (elg_app_run() then fails with that error) or
///   leaves 0 to go on. A null `call` removes the handler. What it panics with is only logged.
void elg_app_on_error(ElgApp* app, ElgClosure handler);

/// Wraps `App::quit()`: makes elg_app_run() return after the current event. Call it on the UI
/// thread.
///
/// @param app The app (borrowed).
void elg_app_quit(ElgApp* app);

/// Wraps `post_to_ui_thread()`: runs `task` on the UI thread soon, between events, where state may
/// be written. Callable from any thread; tasks run in the order posted. Posted while no App runs,
/// a task waits for the next one.
///
/// @param task Consumed closure, a Send closure; it runs on the UI thread. args and ret: null.
///   Required: none is a usage error.
void elg_post_to_ui_thread(ElgClosure task);

/// Wraps `version()`: the library's version string, e.g. "0.1.0".
/// Callable from any thread.
///
/// @return A static, NUL-terminated string; don't free it. Null on failure.
const char* elg_version(void);

/// The C API's ABI version: a binding checks it when it loads the library, and refuses to run
/// with a version it wasn't built for. It changes whenever an exported function's signature, a
/// struct's layout, or a documented constant's value does.
/// Callable from any thread.
///
/// @return The version, 1 or more; 0 on failure.
uint32_t elg_abi_version(void);

// --- Animation ---

/// Wraps `Animation::linear()`: constant speed.
///
/// @param duration Seconds (the C++ default is 0.25); negative counts as 0.
/// @return The animation, owned by the caller (elg_animation_free()). Null on failure.
ElgAnimation* elg_animation_linear(double duration);

/// Wraps `Animation::ease_in()`: starts slowly.
///
/// @param duration Seconds (the C++ default is 0.25); negative counts as 0.
/// @return The animation, owned by the caller (elg_animation_free()). Null on failure.
ElgAnimation* elg_animation_ease_in(double duration);

/// Wraps `Animation::ease_out()`: ends slowly.
///
/// @param duration Seconds (the C++ default is 0.25); negative counts as 0.
/// @return The animation, owned by the caller (elg_animation_free()). Null on failure.
ElgAnimation* elg_animation_ease_out(double duration);

/// Wraps `Animation::ease_in_out()`: starts and ends slowly.
///
/// @param duration Seconds (the C++ default is 0.35); negative counts as 0.
/// @return The animation, owned by the caller (elg_animation_free()). Null on failure.
ElgAnimation* elg_animation_ease_in_out(double duration);

/// Wraps `Animation::spring()`: a spring settling at the target, like SwiftUI's
/// .spring(response:dampingFraction:).
///
/// @param response Roughly the time to get there, in seconds (the C++ default is 0.5).
/// @param damping_fraction 1 settles without overshoot; lower values bounce (the C++ default is
///   0.825).
/// @return The animation, owned by the caller (elg_animation_free()). Null on failure.
ElgAnimation* elg_animation_spring(double response, double damping_fraction);

/// Wraps `Animation::smooth()`: a gentle spring without overshoot.
///
/// @param duration Roughly the time to get there, in seconds (the C++ default is 0.4).
/// @return The animation, owned by the caller (elg_animation_free()). Null on failure.
ElgAnimation* elg_animation_smooth(double duration);

/// Wraps `Animation::custom()`: `curve` (args: double* t, ret: double*) maps progress 0...1 to
/// eased progress. It may go past 0 or 1 to overshoot; the animation lands on the target once
/// `duration` is up regardless.
///
/// @param curve Consumed closure; args: `double*`, the fraction of `duration` elapsed (0 to 1);
///   ret: `double*`, the progress (0 at the start, 1 at the target), set to the fraction beforehand.
///   A panic in it propagates like one in any callback: from an animated property, out of
///   App::run; from elg_animation_progress(), as its error. Required: none is a usage error.
/// @param duration Seconds; negative counts as 0.
/// @return The animation, owned by the caller (elg_animation_free()), or nullptr on failure.
ElgAnimation* elg_animation_custom(ElgClosure curve, double duration);

/// Wraps `Animation::delay()`: a copy of `animation` that waits before starting.
///
/// @param animation The animation (borrowed).
/// @param seconds How long to wait, added to any delay it has. Negative starts partway in, like
///   CSS: -0.1 begins where it would be 0.1 s in.
/// @return The new animation, owned by the caller (elg_animation_free()). Null on failure.
ElgAnimation* elg_animation_delay(const ElgAnimation* animation, double seconds);

/// Wraps `Animation::timing_curve()`: a cubic Bézier through (0, 0), (x1, y1), (x2, y2) and (1, 1), like
/// CSS's cubic-bezier().
///
/// @param x1 The first control point's time, 0 to 1 (clamped).
/// @param y1 The first control point's progress; outside 0 to 1 overshoots.
/// @param x2 The second control point's time, 0 to 1 (clamped).
/// @param y2 The second control point's progress; outside 0 to 1 overshoots.
/// @param duration Seconds; negative counts as 0 (no animation).
/// @return The animation, owned by the caller (elg_animation_free()). Null on failure.
ElgAnimation* elg_animation_timing_curve(double x1, double y1, double x2, double y2, double duration);

/// Wraps `Animation::repeat_count()`: a copy of `animation` that plays `count` times.
///
/// @param animation The animation (borrowed).
/// @param count How many times; less than 1 counts as 1.
/// @param autoreverses Every other time runs backward, from the target to where it started.
/// @return The new animation, owned by the caller (elg_animation_free()). Null on failure.
ElgAnimation* elg_animation_repeat_count(const ElgAnimation* animation, int32_t count, bool autoreverses);

/// Wraps `Animation::repeat_forever()`: a copy of `animation` that plays until it's replaced.
///
/// @param animation The animation (borrowed).
/// @param autoreverses Every other time runs backward, from the target to where it started.
/// @return The new animation, owned by the caller (elg_animation_free()). Null on failure.
ElgAnimation* elg_animation_repeat_forever(const ElgAnimation* animation, bool autoreverses);

/// Wraps `Animation::progress()`.
///
/// @param animation The animation (borrowed).
/// @param seconds Time since the start.
/// @return The progress: 0 at the start, 1 at the end (springs overshoot). 1 on failure.
double elg_animation_progress(const ElgAnimation* animation, double seconds);

/// Wraps `Animation::finished()`.
///
/// @param animation The animation (borrowed).
/// @param seconds Time since the start.
/// @return true once it has finished (never for one that repeats forever); true on failure.
bool elg_animation_finished(const ElgAnimation* animation, double seconds);

/// Copies an animation.
///
/// @param animation The animation (borrowed).
/// @return The copy, owned by the caller (elg_animation_free()). Null on failure.
ElgAnimation* elg_animation_clone(const ElgAnimation* animation);

/// Frees an animation.
///
/// @param animation The animation (consumed); may be null.
void elg_animation_free(ElgAnimation* animation);

// --- Timers ---

/// Wraps `after()`: runs `action` once, `seconds` from now (0: as soon as the current event is handled), on
/// the UI thread. A timer started while views are built, or in on_appear, ends with that view.
///
/// @param seconds The delay; negative counts as 0. Positive infinity never runs the action. NaN is a usage
///   error.
/// @param action The action. No args. May be none: the timer is never active.
/// @return The timer, owned by the caller (elg_timer_free(), which doesn't stop it). Null on failure.
ElgTimer* elg_timer_after(double seconds, ElgClosure action);

/// Wraps `every()`: runs `action` every `seconds` (at least a millisecond), the first time `seconds` from
/// now, on the UI thread. Missed runs are skipped. A timer started while views are built, or in
/// on_appear, ends with that view.
///
/// @param seconds The interval; less than a millisecond counts as a millisecond. Positive infinity never runs
///   the action. NaN is a usage error.
/// @param action The action. No args. May be none: the timer is never active.
/// @return The timer, owned by the caller (elg_timer_free(), which doesn't stop it). Null on failure.
ElgTimer* elg_timer_every(double seconds, ElgClosure action);

/// Wraps `Timer::cancel()`: the action doesn't run again. Fine to call more than once.
///
/// @param timer The timer (borrowed).
void elg_timer_cancel(const ElgTimer* timer);

/// Wraps `Timer::active()`: whether the timer is still going: not cancelled, its view still there, and for
/// elg_timer_after(), not fired yet.
///
/// @param timer The timer (borrowed).
/// @return true while it's going; false on failure.
bool elg_timer_active(const ElgTimer* timer);

/// Copies a timer handle: both refer to the same timer.
///
/// @param timer The timer (borrowed).
/// @return The copy, owned by the caller (elg_timer_free()). Null on failure.
ElgTimer* elg_timer_clone(const ElgTimer* timer);

/// Frees a timer handle. The timer goes on running.
///
/// @param timer The timer (consumed); may be null.
void elg_timer_free(ElgTimer* timer);

// --- Transition ---

/// Wraps `Transition::opacity()`: the view fades in and out.
///
/// @return The transition, owned by the caller (elg_transition_free()). Null on failure.
ElgTransition* elg_transition_opacity(void);

/// Wraps `Transition::identity()`: the view appears and disappears at once.
///
/// @return The transition, owned by the caller (elg_transition_free()). Null on failure.
ElgTransition* elg_transition_identity(void);

/// Wraps `Transition::scale()`: the view grows from (and shrinks to) `from` times its size.
///
/// @param from The scale it starts and ends at (the C++ default is 0).
/// @param anchor The point of its frame it scales around.
/// @return The transition, owned by the caller (elg_transition_free()). Null on failure.
ElgTransition* elg_transition_scale(float from, ElgAlignment anchor);

/// Wraps `Transition::offset()`: the view moves in from (and out to) an offset.
///
/// @param x Horizontal offset in points.
/// @param y Vertical offset in points.
/// @return The transition, owned by the caller (elg_transition_free()). Null on failure.
ElgTransition* elg_transition_offset(float x, float y);

/// Wraps `Transition::move()`: the view slides in from (and out to) beyond an edge of its frame.
///
/// @param edge elg::Edges bits: 1 top, 2 leading, 4 bottom, 8 trailing.
/// @return The transition, owned by the caller (elg_transition_free()). Null on failure.
ElgTransition* elg_transition_move(uint32_t edge);

/// Wraps `Transition::slide()`: the view moves in from the leading edge and out to the trailing
/// edge.
///
/// @return The transition, owned by the caller (elg_transition_free()). Null on failure.
ElgTransition* elg_transition_slide(void);

/// Wraps `Transition::asymmetric()`: different transitions for insertion and removal.
///
/// @param insertion How the view enters (borrowed).
/// @param removal How the view leaves (borrowed).
/// @return The transition, owned by the caller (elg_transition_free()). Null on failure.
ElgTransition* elg_transition_asymmetric(const ElgTransition* insertion, const ElgTransition* removal);

/// Wraps `Transition::combined()`: both transitions at once.
///
/// @param a A transition (borrowed).
/// @param b Another transition (borrowed).
/// @return The transition, owned by the caller (elg_transition_free()). Null on failure.
ElgTransition* elg_transition_combined(const ElgTransition* a, const ElgTransition* b);

/// Wraps `Transition::pose()`: how the view looks at `progress`.
///
/// @param transition The transition (borrowed).
/// @param progress 0: fully out, 1: in place.
/// @param removal true for the view leaving, false for it entering.
/// @param view_size The view's size in points, for transitions that move it beyond an edge.
/// @return The pose. Zero on failure.
ElgPose elg_transition_pose(const ElgTransition* transition, float progress, bool removal, ElgSize view_size);

/// Copies a transition.
///
/// @param transition The transition (borrowed).
/// @return The copy, owned by the caller (elg_transition_free()). Null on failure.
ElgTransition* elg_transition_clone(const ElgTransition* transition);

/// Frees a transition.
///
/// @param transition The transition (consumed); may be null.
void elg_transition_free(ElgTransition* transition);

// --- ABI layout (shim.h's structs and this file's) ---

/// Describes the layout of shim.h's structs and this file's, for a binding's layout test: one line
/// per struct, "name size align", then " field:offset" for each of its fields, in order.
///
/// @param out Receives each line.
/// @param ctx Passed to `out`.
void elg_layouts_core(ElgStrSink out, void* ctx);

// --- Containers ---

/// Wraps `VStack()` (`VStackLayout`): the children in a column.
///
/// @param alignment How the children line up across the column (`HorizontalAlignment`).
/// @param spacing Between the children; unset: `default_stack_spacing`.
/// @param children The children (consumed).
/// @param count How many `children` there are.
/// @return The stack, owned by the caller, or null on failure.
ElgView* elg_vstack(int32_t alignment, ElgOptLen spacing, ElgView** children, size_t count);

/// Wraps `HStack()` (`HStackLayout`): the children in a row.
///
/// @param alignment How the children line up across the row (`VerticalAlignment`).
/// @param spacing Between the children; unset: `default_stack_spacing`.
/// @param children The children (consumed).
/// @param count How many `children` there are.
/// @return The stack, owned by the caller, or null on failure.
ElgView* elg_hstack(int32_t alignment, ElgOptLen spacing, ElgView** children, size_t count);

/// Wraps `ZStack()` (`ZStackLayout`): the children drawn on top of each other, the first at the back.
///
/// @param alignment Where children smaller than the stack sit.
/// @param children The children (consumed).
/// @param count How many `children` there are.
/// @return The stack, owned by the caller, or null on failure.
ElgView* elg_zstack(ElgAlignment alignment, ElgView** children, size_t count);

/// Wraps `Spacer()`: flexible space that expands along its stack's axis.
///
/// @param min_length The least it shrinks to, in points; unset: `default_stack_spacing`.
/// @return The spacer, owned by the caller, or null on failure.
ElgView* elg_spacer(ElgOptLen min_length);

/// Wraps `EmptyView()`: takes no space and draws nothing.
///
/// @return The view, owned by the caller, or null on failure.
ElgView* elg_empty_view(void);

/// Wraps `aligned_position()`: where a child of size `content` goes inside `container`.
///
/// @param container The space the child goes in.
/// @param content The child's size.
/// @param a How the child lines up in `container`.
/// @return The child's top-leading corner, in `container`'s coordinates. Zero on failure.
ElgPoint elg_aligned_position(ElgRect container, ElgSize content, ElgAlignment a);

/// Wraps `size_that_fits()` of `VStackLayout`, `HStackLayout` or `ZStackLayout`, for custom layouts that
/// measure their children as a stack does.
///
/// @param kind 0: `VStackLayout`; 1: `HStackLayout`; anything else: `ZStackLayout`.
/// @param a The stack's alignment: a VStack reads `horizontal`, an HStack `vertical`, a ZStack both.
/// @param spacing Between the children of a VStack or HStack; unset: `default_stack_spacing`.
/// @param proposal The size offered to the stack.
/// @param children The custom layout's children (borrowed).
/// @param count How many `children` there are.
/// @return The size the stack takes; zero on failure.
ElgSize elg_stack_layout_size(int32_t kind, ElgAlignment a, ElgOptLen spacing, ElgProposedSize proposal, const ElgLayoutChild* children, size_t count);

/// Wraps `place_children()` of `VStackLayout`, `HStackLayout` or `ZStackLayout`, for custom layouts that
/// place their children as a stack does.
///
/// @param kind 0: `VStackLayout`; 1: `HStackLayout`; anything else: `ZStackLayout`.
/// @param a The stack's alignment: a VStack reads `horizontal`, an HStack `vertical`, a ZStack both.
/// @param spacing Between the children of a VStack or HStack; unset: `default_stack_spacing`.
/// @param bounds Where the stack is, at the size elg_stack_layout_size() reported for `proposal`.
/// @param proposal The size offered to the stack.
/// @param children The custom layout's children (borrowed).
/// @param count How many `children` there are.
void elg_stack_layout_place(int32_t kind, ElgAlignment a, ElgOptLen spacing, ElgRect bounds, ElgProposedSize proposal, const ElgLayoutChild* children, size_t count);

// --- Controls ---

/// Wraps `Button()` with a view label: a push button. Its look comes from the ButtonStyle.
///
/// @param take_label What the button shows (consumed).
/// @param on_click Runs when the button is clicked, or activated with Space or Enter while it has focus. No
///   args. Required: none is a usage error.
/// @return The button, owned by the caller, or null on failure.
ElgView* elg_button(ElgView* take_label, ElgClosure on_click);

/// Wraps `Button()` with a title: like elg_button(), labeled with text.
///
/// @param title A string prop: the button's text.
/// @param on_click Runs when the button is clicked, or activated with Space or Enter while it has focus. No
///   args. Required: none is a usage error.
/// @return The button, owned by the caller, or null on failure.
ElgView* elg_button_title(ElgProp title, ElgClosure on_click);

/// Appends a `TextSpan` to a styler's result (ElgTextFieldOptions::styler).
///
/// @param spans The styler's `ret`.
/// @param begin Where the span starts, in bytes into the text.
/// @param end Where it ends, in bytes into the text.
/// @param style How the range looks (borrowed).
/// @param label Null: none. Otherwise the range shows as this text and is edited as one unit, e.g. a mention
///   shown as a chip (copied).
void elg_text_spans_push(ElgTextSpans* spans, size_t begin, size_t end, const ElgRunStyle* style, const ElgStr* label);

/// Wraps `TextField()`: a single-line text editor bound to `take_text`. Its look comes from the TextFieldStyle.
///
/// @param placeholder A string prop: shown while the text is empty.
/// @param take_text The text (consumed).
/// @param o The options (borrowed; their closures are taken over).
/// @return The text field, owned by the caller, or null on failure: a UsageError when a static `secure` is
///   true and a static `line_limit` is above 1.
ElgView* elg_text_field(ElgProp placeholder, ElgBindingString* take_text, const ElgTextFieldOptions* o);

/// Wraps `TextArea()`: a multiline text editor bound to `take_text`. It takes the height it's offered and
/// scrolls through longer text; its look comes from the TextFieldStyle.
///
/// @param placeholder A string prop: shown while the text is empty.
/// @param take_text The text (consumed).
/// @param o The options (borrowed; their closures are taken over). `secure` and `line_limit` are
///   ignored, and their closures dropped.
/// @return The text area, owned by the caller, or null on failure.
ElgView* elg_text_area(ElgProp placeholder, ElgBindingString* take_text, const ElgTextFieldOptions* o);

/// Wraps `Slider()`: a value in [`min`, `max`] picked by dragging a knob along a track, or with the arrow
/// keys, Page Up/Down and Home/End while focused. Takes the width it's offered.
///
/// @param take_value The value (consumed).
/// @param min A float prop: the low end.
/// @param max A float prop: the high end.
/// @param step A float prop: the increment; 0: continuous.
/// @param on_editing_changed Called with true when a drag starts and false when it ends. args: bool*; may be
///   none.
/// @return The slider, owned by the caller, or null on failure.
ElgView* elg_slider(ElgBindingF32* take_value, ElgProp min, ElgProp max, ElgProp step, ElgClosure on_editing_changed);

/// Wraps `NumberInput()`: a number you can type, step with the arrows or Up/Down, or scrub by dragging. Values
/// stay within [min, max]; text that isn't a number reverts. Its look comes from the NumberInputStyle.
///
/// @param take_value The value (consumed).
/// @param integer Whole numbers: values are rounded and shown without decimals, as `NumberInput()` does for
///   an int.
/// @param o The options (borrowed; their closures are taken over).
/// @return The number input, owned by the caller, or null on failure.
ElgView* elg_number_input(ElgBindingF64* take_value, bool integer, const ElgNumberInputOptions* o);

/// Wraps `Progress()`: how far along something is, drawn by the ProgressStyle.
///
/// @param fraction An optional float prop (ElgOptLen): 0...1, or unset while indeterminate.
/// @return The progress view, owned by the caller, or null on failure.
ElgView* elg_progress(ElgProp fraction);

/// Wraps `Picker()`: one of several options, chosen by index. Its look comes from the PickerStyle.
///
/// @param labels The options' labels (copied).
/// @param count How many `labels` there are.
/// @param selected The chosen option's index, `count` while none is. ret: size_t*. Required: none is a usage
///   error.
/// @param select Chooses an option. args: size_t* (its index). Required: none is a usage error.
/// @return The picker, owned by the caller, or null on failure.
ElgView* elg_picker(const ElgStr* labels, size_t count, ElgClosure selected, ElgClosure select);

/// Wraps `Toggle()`: an on/off control bound to `take_is_on`. Its look comes from the ToggleStyle (a switch by
/// default); a click, Space or Enter flips it.
///
/// @param take_label The label (consumed); null: just the switch (give it an accessibility label).
/// @param take_is_on Whether it's on (consumed).
/// @return The toggle, owned by the caller, or null on failure.
ElgView* elg_toggle(ElgView* take_label, ElgBindingBool* take_is_on);

/// Wraps `Toggle()` with a title: like elg_toggle(), labeled with text.
///
/// @param title A string prop: the label.
/// @param take_is_on Whether it's on (consumed).
/// @return The toggle, owned by the caller, or null on failure.
ElgView* elg_toggle_title(ElgProp title, ElgBindingBool* take_is_on);

/// Wraps `Checkbox()`: a check box bound to `take_is_checked`. Its look comes from the CheckboxStyle; a click,
/// Space or Enter checks or unchecks it.
///
/// @param take_label The label (consumed); null: just the box (give it an accessibility label).
/// @param take_is_checked Whether it's checked (consumed).
/// @param mixed A bool prop: some of what it stands for is checked, shown with a dash (`CheckboxOptions::mixed`).
/// @return The check box, owned by the caller, or null on failure.
ElgView* elg_checkbox(ElgView* take_label, ElgBindingBool* take_is_checked, ElgProp mixed);

/// Wraps `Checkbox()` with a title: like elg_checkbox(), labeled with text.
///
/// @param title A string prop: the label.
/// @param take_is_checked Whether it's checked (consumed).
/// @param mixed A bool prop: some of what it stands for is checked, shown with a dash (`CheckboxOptions::mixed`).
/// @return The check box, owned by the caller, or null on failure.
ElgView* elg_checkbox_title(ElgProp title, ElgBindingBool* take_is_checked, ElgProp mixed);

/// Wraps `Separator()`: a thin line between groups, as long as it's offered.
///
/// @param axis `Axis`: 0 horizontal, 1 vertical.
/// @param color A Color prop: the line's color.
/// @param thickness The line's thickness, in points.
/// @param inset Left clear at both ends, in points.
/// @return The separator, owned by the caller, or null on failure.
ElgView* elg_separator(int32_t axis, ElgProp color, float thickness, float inset);

// --- Structure ---

/// Wraps `If()`: `take_then` while `condition` holds, otherwise `take_else`. Switching branches removes the old
/// branch's views, with any state created inside them, and builds the other.
///
/// @param condition A bool prop.
/// @param take_then Shown while `condition` holds (consumed).
/// @param take_else Shown otherwise (consumed); an empty view for nothing.
/// @return The view, owned by the caller, or null on failure.
ElgView* elg_if(ElgProp condition, ElgView* take_then, ElgView* take_else);

/// Wraps `ForEach()`: one view per item, identified by key. When the items change, unchanged ones keep their
/// views (and state), changed ones are rebuilt and removed ones are removed.
///
/// @param items Lists the items; a tracked read, so the ForEach updates when what it reads changes. ret:
///   std::vector<ForEachItem>* (filled with elg_for_each_items_push). Required: none is a usage error.
/// @return The ForEach, owned by the caller, or null on failure.
ElgView* elg_for_each(ElgClosure items);

/// Appends items to a list of ForEach items: the `ret` of elg_for_each()'s `items` and
/// elg_navigation_stack()'s `pages`.
///
/// @param target The closure's `ret`.
/// @param items The items (borrowed; their `value` and `view` closures are taken over).
/// @param count How many `items` there are.
void elg_for_each_items_push(ElgForEachItems* target, const ElgForEachItem* items, size_t count);

// --- Scrolling ---

/// Wraps `ScrollPosition()`: scrolls a scroll view from code. Pass it to elg_scroll_view(), then call the
/// elg_scroll_position_to_* functions, e.g. from event handlers.
///
/// @return The position, owned by the caller (free it with elg_scroll_position_free()), or null on failure.
ElgScrollPosition* elg_scroll_position_new(void);

/// Copies a ScrollPosition: copies refer to the same scroll view.
///
/// @param position The position to copy (borrowed).
/// @return The copy, owned by the caller. Null on failure.
ElgScrollPosition* elg_scroll_position_clone(const ElgScrollPosition* position);

/// Frees a ScrollPosition. The scroll view keeps its own copy.
///
/// @param position The position (consumed); may be null.
void elg_scroll_position_free(ElgScrollPosition* position);

/// Wraps `ScrollPosition::scroll_to_top()`: scrolls the scroll view to its top.
///
/// @param position The scroll view's position (borrowed).
/// @param animated Whether the scroll animates.
void elg_scroll_position_to_top(const ElgScrollPosition* position, bool animated);

/// Wraps `ScrollPosition::scroll_to_end()`: scrolls the scroll view to its end.
///
/// @param position The scroll view's position (borrowed).
/// @param animated Whether the scroll animates.
void elg_scroll_position_to_end(const ElgScrollPosition* position, bool animated);

/// Wraps `ScrollPosition::scroll_to()` with an integer key: scrolls the item with this ForEach key, in a lazy
/// stack inside the scroll view, to the top.
///
/// @param position The scroll view's position (borrowed).
/// @param key The item's ForEach key.
void elg_scroll_position_to_int(const ElgScrollPosition* position, int64_t key);

/// Wraps `ScrollPosition::scroll_to()` with a string key: scrolls the item with this ForEach key, in a lazy
/// stack inside the scroll view, to the top.
///
/// @param position The scroll view's position (borrowed).
/// @param key The item's ForEach key (copied).
void elg_scroll_position_to_string(const ElgScrollPosition* position, ElgStr key);

/// Wraps `ScrollView()`: `take_content` at its ideal size along the scroll axes, clipped to the space the
/// scroll view takes (all it's offered). The wheel, trackpad, scroll bars and keys scroll it.
///
/// @param take_content What scrolls (consumed).
/// @param axes `ScrollAxes`: 1 vertical, 2 horizontal, 3 both.
/// @param shows_indicators A bool prop: scroll bars, shown while scrolling or hovered.
/// @param position Scrolls it from code; null: none. Borrowed: the scroll view keeps a copy, which refers to
///   the same scroll view.
/// @param sticks_to_end A bool prop: starts at the end and, while scrolled to the end, stays there as the
///   content grows (chat logs).
/// @return The scroll view, owned by the caller, or null on failure.
ElgView* elg_scroll_view(ElgView* take_content, int32_t axes, ElgProp shows_indicators, const ElgScrollPosition* position, ElgProp sticks_to_end);

/// Wraps `LazyVStack()` and `LazyHStack()`: like a stack over a ForEach, but only the items in or near the
/// visible part of the enclosing scroll view are built. Outside a scroll view every item is built.
///
/// @param vertical true: a LazyVStack; false: a LazyHStack.
/// @param alignment How the items line up across the stack: a `HorizontalAlignment` in a vertical stack, a
///   `VerticalAlignment` in a horizontal one.
/// @param spacing Between the items; unset: `default_stack_spacing`.
/// @param separators Lines between the items (borrowed; the color's closure is taken over); null: none.
/// @param take_for_each A ForEach from elg_for_each() (consumed).
/// @return The stack, owned by the caller, or null on failure: a UsageError when `take_for_each` isn't a
///   ForEach.
ElgView* elg_lazy_stack(bool vertical, int32_t alignment, ElgOptLen spacing, const ElgStackSeparators* separators, ElgView* take_for_each);

// --- Menus ---

/// Wraps `MenuItem()`: a menu command. Choosing it closes the menu, then runs `on_choose`.
///
/// @param title A string prop: the item's text.
/// @param on_choose Runs when the item is chosen. No args.
/// @param shortcut A string prop: a hint shown on the right, e.g. "Ctrl+R"; empty: none.
/// @param destructive A bool prop: shown in the danger color.
/// @param checked A bool prop for a check mark in front (borrowed; its closure is taken over); null: none.
/// @param image An icon in front (borrowed); null: none.
/// @return The menu item, owned by the caller, or null on failure.
ElgView* elg_menu_item(ElgProp title, ElgClosure on_choose, ElgProp shortcut, ElgProp destructive, const ElgProp* checked, const ElgImageSource* image);

/// Wraps `Submenu()`: a menu item that opens another menu beside it (on hover, click, or Right).
///
/// @param title A string prop: the item's text.
/// @param menu Builds the menu, usually with elg_menu(). ret: View*. Required: none is a usage error.
/// @return The submenu item, owned by the caller, or null on failure.
ElgView* elg_submenu(ElgProp title, ElgClosure menu);

/// Wraps `Menu()`: the menu panel, its items stacked in the MenuStyle's panel. Up/Down move between items,
/// Enter chooses, Esc closes, Left/Right leave and enter submenus.
///
/// @param items The items (consumed): elg_menu_item(), elg_submenu(), separators, or any view.
/// @param count How many `items` there are.
/// @return The menu, owned by the caller, or null on failure.
ElgView* elg_menu(ElgView** items, size_t count);

/// Wraps `MenuButton()`: a button that opens the menu `menu` builds, in a popup window.
///
/// @param take_label The button's label (consumed); null: `title` is.
/// @param title A string prop for the label, read when `take_label` is null (borrowed; its closure is taken
///   over); null: `take_label` is. One of the two is required: both null is a usage error.
/// @param menu Builds the menu, usually with elg_menu(). ret: View*. Required: none is a usage error.
/// @param placement Where the menu opens (borrowed; required).
/// @param shows_indicator A bool prop: the chevron after the label.
/// @param popup_motion How the menu opens and closes; `has` false: the MenuStyle's.
/// @return The menu button, owned by the caller, or null on failure.
ElgView* elg_menu_button(ElgView* take_label, const ElgProp* title, ElgClosure menu, const ElgFloatingPlacement* placement, ElgProp shows_indicator, ElgPopupMotion popup_motion);

// --- Navigation ---

/// Wraps `HSplitView()` and `VSplitView()`: panes with a divider between each two; dragging a divider resizes
/// the panes on either side of it.
///
/// @param axis `Axis`: 0 side by side (HSplitView), 1 top to bottom (VSplitView).
/// @param panes The panes (consumed).
/// @param count How many `panes` there are.
/// @param options How the dividers look (borrowed; required).
/// @return The split view, owned by the caller, or null on failure.
ElgView* elg_split_view(int32_t axis, ElgView** panes, size_t count, const ElgSplitViewOptions* options);

/// Wraps `NavigationSplitView()`: a sidebar, optionally a content column, and the detail of what's chosen,
/// with draggable dividers between them. The detail takes the rest of the width.
///
/// @param take_sidebar The sidebar (consumed).
/// @param take_content The content column (consumed); null: the two-column form.
/// @param take_detail The detail (consumed).
/// @param o The options (borrowed; required). Their binding and closures are taken over.
/// @return The split view, owned by the caller, or null on failure.
ElgView* elg_navigation_split_view(ElgView* take_sidebar, ElgView* take_content, ElgView* take_detail, const ElgNavigationSplitViewOptions* o);

/// Wraps `NavigationStack()` over a path kept in Rust: the root, then a page for each route in the path. Only
/// the last is shown; its look around the pages comes from the NavigationStackStyle.
///
/// @param take_root The root page (consumed).
/// @param pages A page per route in the path; a tracked read of the path, as NavigationStack does. ret:
///   std::vector<ForEachItem>* (filled with elg_for_each_items_push). Required: none is a usage error.
/// @param titles The root's title, then each pushed page's, for the style; a tracked read of the path. ret:
///   std::vector<std::string>* (filled with elg_strings_push). Required: none is a usage error.
/// @param pop Removes the last route from the path (Alt+Left, the back gestures, a style's back button). No
///   args. Required: none is a usage error.
/// @param transition `PageTransition`: 0 slide, 1 fade, 2 none.
/// @param animation For pushes and pops that aren't animated themselves (borrowed); null: they change at once.
/// @param back_gestures Alt+Left, and swiping right with two fingers on a trackpad (macOS), go back.
/// @return The navigation stack, owned by the caller, or null on failure.
ElgView* elg_navigation_stack(ElgView* take_root, ElgClosure pages, ElgClosure titles, ElgClosure pop, int32_t transition, const ElgAnimation* animation, bool back_gestures);

/// Appends a string to a closure's `std::vector<std::string>` result (elg_navigation_stack()'s `titles`).
///
/// @param target The closure's `ret`.
/// @param value The string (copied).
void elg_strings_push(ElgStrings* target, ElgStr value);

// --- Text ---

/// Wraps `Text()`: text in one font and color, wrapping at word boundaries to the proposed width.
///
/// @param content A string prop: the text.
/// @return The text, owned by the caller (free it with elg_text_free()), or null on failure.
ElgText* elg_text(ElgProp content);

/// Copies a Text.
///
/// @param text The text to copy (borrowed).
/// @return The copy, owned by the caller. Null on failure.
ElgText* elg_text_clone(const ElgText* text);

/// Frees a Text.
///
/// @param text The text (consumed); may be null.
void elg_text_free(ElgText* text);

/// A Text as a View, for containers and view modifiers.
///
/// @param text The text (borrowed).
/// @return The view, owned by the caller. Null on failure.
ElgView* elg_text_to_view(const ElgText* text);

/// Wraps `Text::font()`.
///
/// @param text The text (borrowed).
/// @param f A Font prop (ElgFont).
/// @return `text` in that font (a new Text, owned by the caller), or null on failure.
ElgText* elg_text_font(const ElgText* text, ElgProp f);

/// Wraps `Text::font_weight()`.
///
/// @param text The text (borrowed).
/// @param weight A Weight prop (int32_t, 1...1000).
/// @return `text` in that weight (a new Text, owned by the caller), or null on failure.
ElgText* elg_text_font_weight(const ElgText* text, ElgProp weight);

/// Wraps `Text::bold()`.
///
/// @param text The text (borrowed).
/// @return `text` in bold (a new Text, owned by the caller), or null on failure.
ElgText* elg_text_bold(const ElgText* text);

/// Wraps `Text::foreground_style()`.
///
/// @param text The text (borrowed).
/// @param color A Color prop.
/// @return `text` in that color (a new Text, owned by the caller), or null on failure.
ElgText* elg_text_foreground_style(const ElgText* text, ElgProp color);

/// Wraps `Text::line_limit()`: the text truncates with an ellipsis past this many lines.
///
/// @param text The text (borrowed).
/// @param lines The most lines it takes; 0: no limit.
/// @return `text` with the limit (a new Text, owned by the caller), or null on failure.
ElgText* elg_text_line_limit(const ElgText* text, int32_t lines);

/// Wraps `Text::multiline_text_alignment()`: how lines align when the text wraps.
///
/// @param text The text (borrowed).
/// @param alignment `TextAlignment`: 0 leading, 1 center, 2 trailing.
/// @return `text` with that alignment (a new Text, owned by the caller), or null on failure.
ElgText* elg_text_multiline_alignment(const ElgText* text, int32_t alignment);

/// Wraps `Text::selectable()`: the person using the app can select the text with the pointer, and
/// copy it.
///
/// @param text The text (borrowed).
/// @param selectable A bool prop: whether it can be selected.
/// @return `text`, selectable while `selectable` is true (a new Text, owned by the caller), or null on
///   failure.
ElgText* elg_text_selectable(const ElgText* text, ElgProp selectable);

/// Wraps `StyledText()`: text made of runs in different weights, colors and highlights, wrapping like Text.
///
/// @param runs The runs (borrowed; their closures and attachments are taken over).
/// @param count How many `runs` there are.
/// @return The view, owned by the caller, or null on failure.
ElgView* elg_styled_text(const ElgTextRun* runs, size_t count);

// --- Shapes ---

/// Copies a Shape.
///
/// @param shape The shape to copy (borrowed).
/// @return The copy, owned by the caller. Null on failure.
ElgShape* elg_shape_clone(const ElgShape* shape);

/// Frees a Shape.
///
/// @param shape The shape (consumed); may be null.
void elg_shape_free(ElgShape* shape);

/// A Shape as a View, for containers and view modifiers.
///
/// @param shape The shape (borrowed).
/// @return The view, owned by the caller. Null on failure.
ElgView* elg_shape_to_view(const ElgShape* shape);

/// Wraps `Rectangle()`: a shape filling its frame.
///
/// @return The shape, owned by the caller (free it with elg_shape_free()). Null on failure.
ElgShape* elg_rectangle(void);

/// Wraps `RoundedRectangle()` with a radius per corner (`CornerRadii`). Radii are in points.
///
/// @param top_left The top-left corner's radius.
/// @param top_right The top-right corner's radius.
/// @param bottom_right The bottom-right corner's radius.
/// @param bottom_left The bottom-left corner's radius.
/// @return The shape, owned by the caller, or null on failure.
ElgShape* elg_rounded_rectangle(float top_left, float top_right, float bottom_right, float bottom_left);

/// Wraps `Capsule()`: fully rounded ends along the shorter side.
///
/// @return The shape, owned by the caller. Null on failure.
ElgShape* elg_capsule(void);

/// Wraps `Circle()`: the largest circle that fits, centered.
///
/// @return The shape, owned by the caller. Null on failure.
ElgShape* elg_circle(void);

/// Wraps `PathShape()`: a vector path as a shape.
///
/// @param path The path (borrowed; copied).
/// @param view_box The path's own coordinate box, as in SVG: the path is scaled to fit the frame, keeping its
///   aspect ratio, and centered (borrowed). Null: path coordinates are points from the frame's corner.
/// @param fill_rule `FillRule`: 0 non-zero, 1 even-odd.
/// @return The shape, owned by the caller, or null on failure.
ElgShape* elg_path_shape(const ElgPath* path, const ElgRect* view_box, int32_t fill_rule);

/// Wraps `CustomShape()`: a shape whose path depends on its frame, rebuilt when the frame's size changes.
///
/// @param path Builds the outline for the frame's size, given as a rect at (0, 0). args: ElgRect*, ret: Path*
///   (written with elg_path_assign). Required: none is a usage error.
/// @param fill_rule `FillRule`: 0 non-zero, 1 even-odd.
/// @return The shape, owned by the caller, or null on failure.
ElgShape* elg_custom_shape(ElgClosure path, int32_t fill_rule);

/// Wraps `Shape::fill()`.
///
/// @param shape The shape (borrowed).
/// @param style A ShapeStyle prop (ElgShapeStyle): a color or gradient.
/// @return `shape` filled with `style` (a new Shape, owned by the caller), or null on failure.
ElgShape* elg_shape_fill(const ElgShape* shape, ElgProp style);

/// Wraps `Shape::stroke()` with a `StrokeStyle`: a line centered on the shape's edge, with caps, joins and
/// dashes.
///
/// @param shape The shape (borrowed).
/// @param color A Color prop: the line's color.
/// @param style The line's width, caps, joins and dashes (borrowed).
/// @return `shape` with the line (a new Shape, owned by the caller), or null on failure.
ElgShape* elg_shape_stroke(const ElgShape* shape, ElgProp color, const ElgStrokeStyle* style);

/// Wraps `Shape::stroke_border()`: a line inside the shape's edge.
///
/// @param shape The shape (borrowed).
/// @param color A Color prop: the line's color.
/// @param line_width The line's width, in points.
/// @return `shape` with the line (a new Shape, owned by the caller), or null on failure.
ElgShape* elg_shape_stroke_border(const ElgShape* shape, ElgProp color, float line_width);

// --- Paths ---

/// Wraps `Path()`: an empty path, to build with the elg_path_* functions.
///
/// @return The path, owned by the caller (free it with elg_path_free()). Null on failure.
ElgPath* elg_path_new(void);

/// Copies a Path.
///
/// @param path The path to copy (borrowed).
/// @return The copy, owned by the caller. Null on failure.
ElgPath* elg_path_clone(const ElgPath* path);

/// Frees a Path.
///
/// @param path The path (consumed); may be null.
void elg_path_free(ElgPath* path);

/// Copies `source` into `target`, e.g. into the Path result of elg_custom_shape()'s closure.
///
/// @param target The path to overwrite.
/// @param source The path to copy (borrowed).
void elg_path_assign(ElgPath* target, const ElgPath* source);

/// Wraps Path's `operator==`.
///
/// @param a A path (borrowed).
/// @param b Another path (borrowed).
/// @return Whether the two are the same path, segment for segment. False on failure.
bool elg_path_eq(const ElgPath* a, const ElgPath* b);

/// Wraps `Path::move_to()`: starts a new subpath at `p`.
///
/// @param path The path to add to.
/// @param p Where the subpath starts.
void elg_path_move_to(ElgPath* path, ElgPoint p);

/// Wraps `Path::line_to()`: a straight line to `p`.
///
/// @param path The path to add to.
/// @param p Where the line ends.
void elg_path_line_to(ElgPath* path, ElgPoint p);

/// Wraps `Path::quad_to()`: a quadratic Bézier curve to `end`.
///
/// @param path The path to add to.
/// @param control The control point.
/// @param end Where the curve ends.
void elg_path_quad_to(ElgPath* path, ElgPoint control, ElgPoint end);

/// Wraps `Path::cubic_to()`: a cubic Bézier curve to `end`.
///
/// @param path The path to add to.
/// @param control1 The first control point.
/// @param control2 The second control point.
/// @param end Where the curve ends.
void elg_path_cubic_to(ElgPath* path, ElgPoint control1, ElgPoint control2, ElgPoint end);

/// Wraps `Path::arc_to()`: an elliptical arc to `end`, as in SVG.
///
/// @param path The path to add to.
/// @param rx The ellipse's horizontal radius.
/// @param ry The ellipse's vertical radius.
/// @param rotation The ellipse's x-axis rotation, in degrees.
/// @param large_arc Take the longer of the two arcs.
/// @param sweep Go clockwise.
/// @param end Where the arc ends.
void elg_path_arc_to(ElgPath* path, float rx, float ry, float rotation, bool large_arc, bool sweep, ElgPoint end);

/// Wraps `Path::close()`: closes the current subpath with a line back to its start.
///
/// @param path The path to add to.
void elg_path_close(ElgPath* path);

/// Wraps `Path::add_rect()`: a rectangle as a closed subpath.
///
/// @param path The path to add to.
/// @param r The rectangle.
void elg_path_add_rect(ElgPath* path, ElgRect r);

/// Wraps `Path::add_rounded_rect()`: a rounded rectangle as a closed subpath.
///
/// @param path The path to add to.
/// @param r The rectangle.
/// @param radius The corners' radius.
void elg_path_add_rounded_rect(ElgPath* path, ElgRect r, float radius);

/// Wraps `Path::add_ellipse()`: the ellipse inside `r` as a closed subpath.
///
/// @param path The path to add to.
/// @param r The rectangle the ellipse fills.
void elg_path_add_ellipse(ElgPath* path, ElgRect r);

/// Wraps `Path::add_circle()`: a circle as a closed subpath.
///
/// @param path The path to add to.
/// @param center The circle's center.
/// @param radius The circle's radius.
void elg_path_add_circle(ElgPath* path, ElgPoint center, float radius);

/// Wraps `Path::add_path()`: appends another path's subpaths.
///
/// @param path The path to add to.
/// @param other The path to append (borrowed).
void elg_path_add_path(ElgPath* path, const ElgPath* other);

/// Wraps `Path::svg()`: parses SVG path data ("M10 10 L20 20 Z", all commands, relative and absolute).
///
/// @param data The path data.
/// @return The path, owned by the caller, or null on failure: a UsageError with the position of anything it
///   can't read.
ElgPath* elg_path_svg(ElgStr data);

/// Wraps `Path::empty()`.
///
/// @param path The path (borrowed).
/// @return Whether the path has nothing in it. False on failure.
bool elg_path_empty(const ElgPath* path);

/// Wraps `Path::bounds()`.
///
/// @param path The path (borrowed).
/// @return The smallest rect around the path's outline (curves included, not their control points). Zero on failure.
ElgRect elg_path_bounds(const ElgPath* path);

/// Wraps `Path::contains()`.
///
/// @param path The path (borrowed).
/// @param p The point to test.
/// @param rule `FillRule`: 0 non-zero, 1 even-odd.
/// @return Whether the path's outline encloses `p`. False on failure.
bool elg_path_contains(const ElgPath* path, ElgPoint p, int32_t rule);

/// Wraps `Path::transformed()`: the path scaled, then moved: (x * sx + dx, y * sy + dy).
///
/// @param path The path (borrowed).
/// @param sx The horizontal scale.
/// @param sy The vertical scale.
/// @param dx The horizontal move, after scaling.
/// @param dy The vertical move, after scaling.
/// @return The new path, owned by the caller. Null on failure.
ElgPath* elg_path_transformed(const ElgPath* path, float sx, float sy, float dx, float dy);

/// Wraps `Path::flatten()`: lines approximating the path's curves.
///
/// @param path The path (borrowed).
/// @param tolerance The farthest the lines may stray from the curves, in points.
/// @param polyline Called once per flattened subpath, during this call. args: ElgPolyline*. Required: none is a
///   usage error.
void elg_path_flatten(const ElgPath* path, float tolerance, ElgClosure polyline);

/// Wraps `Path::stroked()`: the outline of the path's stroke, to fill with the non-zero rule.
///
/// @param path The path (borrowed).
/// @param style The stroke's width, caps, joins and dashes (borrowed).
/// @param tolerance How far curves may be flattened from their true shape first, in points.
/// @return The outline, owned by the caller, or null on failure.
ElgPath* elg_path_stroked(const ElgPath* path, const ElgStrokeStyle* style, float tolerance);

// --- Drawing ---

/// Wraps `Canvas()`: immediate-mode drawing. It takes the proposed size.
///
/// @param draw Runs every time the view is drawn. args: GraphicsContext* (valid during the call; draw with
///   the elg_gc_* functions). Required: none is a usage error.
/// @return The canvas, owned by the caller, or null on failure.
ElgView* elg_canvas(ElgClosure draw);

/// Wraps `GraphicsContext::size()`.
///
/// @param gc The context a Canvas's `draw` got.
/// @return The drawable area, in points. Zero on failure.
ElgSize elg_gc_size(const ElgGraphicsContext* gc);

/// Wraps `GraphicsContext::scale()`.
///
/// @param gc The context a Canvas's `draw` got.
/// @return Pixels per point. 0 on failure.
float elg_gc_scale(const ElgGraphicsContext* gc);

/// Wraps `GraphicsContext::time()`: the frame clock, the same instant for everything drawn in a frame.
///
/// @param gc The context a Canvas's `draw` got.
/// @return The frame clock's time, in seconds. 0 on failure.
double elg_gc_time(const ElgGraphicsContext* gc);

/// Wraps `GraphicsContext::request_frame()`: draws the canvas again next frame. Call it on every draw while the
/// drawing should keep moving; the window goes back to idle once nothing asks.
///
/// @param gc The context a Canvas's `draw` got.
void elg_gc_request_frame(ElgGraphicsContext* gc);

/// Wraps `GraphicsContext::fill_rect()`.
///
/// @param gc The context a Canvas's `draw` got.
/// @param r The rectangle, in the canvas's points.
/// @param c The fill color.
/// @param radii Four corner radii: top-left, top-right, bottom-right, bottom-left (required).
void elg_gc_fill_rect(ElgGraphicsContext* gc, ElgRect r, ElgColor c, const float* radii);

/// Wraps `GraphicsContext::stroke_rect()`: a border inside `r`.
///
/// @param gc The context a Canvas's `draw` got.
/// @param r The rectangle, in the canvas's points.
/// @param c The border's color.
/// @param width The border's width, in points.
/// @param radii Four corner radii: top-left, top-right, bottom-right, bottom-left (required).
void elg_gc_stroke_rect(ElgGraphicsContext* gc, ElgRect r, ElgColor c, float width, const float* radii);

/// Wraps `GraphicsContext::draw_rect()`: a fill and a border in one.
///
/// @param gc The context a Canvas's `draw` got.
/// @param r The rectangle, in the canvas's points.
/// @param radii Four corner radii: top-left, top-right, bottom-right, bottom-left (required).
/// @param fill The fill color.
/// @param border The border's color.
/// @param border_width The border's width, in points.
void elg_gc_draw_rect(ElgGraphicsContext* gc, ElgRect r, const float* radii, ElgColor fill, ElgColor border, float border_width);

/// Wraps `GraphicsContext::fill_path()`.
///
/// @param gc The context a Canvas's `draw` got.
/// @param path The path, in the canvas's points (borrowed).
/// @param style A color or gradient (borrowed).
/// @param rule `FillRule`: 0 non-zero, 1 even-odd.
void elg_gc_fill_path(ElgGraphicsContext* gc, const ElgPath* path, const ElgShapeStyle* style, int32_t rule);

/// Wraps `GraphicsContext::stroke_path()`.
///
/// @param gc The context a Canvas's `draw` got.
/// @param path The path, in the canvas's points (borrowed).
/// @param c The line's color.
/// @param style The line's width, caps, joins and dashes (borrowed).
void elg_gc_stroke_path(ElgGraphicsContext* gc, const ElgPath* path, ElgColor c, const ElgStrokeStyle* style);

/// Wraps `GraphicsContext::push_clip()`: drawing until the matching elg_gc_pop_clip() shows only inside `r`.
/// Clips nest; ones left pushed are popped when the drawing ends.
///
/// @param gc The context a Canvas's `draw` got.
/// @param r The clip, in the canvas's points.
/// @param radii Four corner radii: top-left, top-right, bottom-right, bottom-left (required).
void elg_gc_push_clip(ElgGraphicsContext* gc, ElgRect r, const float* radii);

/// Wraps `GraphicsContext::pop_clip()`: ends the last clip pushed.
///
/// @param gc The context a Canvas's `draw` got.
void elg_gc_pop_clip(ElgGraphicsContext* gc);

// --- Images ---

/// Wraps `Image()`: an icon, an image file, or image data. Raster images decode in the background and are
/// drawn at their own size unless made resizable; one that can't be read or decoded logs a warning and shows
/// nothing.
///
/// @param source What it shows: set exactly one of `system_name`, `file` and `data` (borrowed; data is
///   copied).
/// @return The image, owned by the caller, or null on failure: a UsageError for an unknown icon.
ElgView* elg_image(const ElgImageSource* source);

/// Wraps `Image()` with an icon name: "set.icon", or "icon" in the default set, with ".variant" after either.
///
/// @param system_name The icon's name.
/// @return The image, owned by the caller, or null on failure: a UsageError for an unknown icon.
ElgView* elg_image_named(ElgStr system_name);

/// Wraps `AsyncImage()`: loads an image over HTTP(S) when first shown: a spinner while loading, the image once
/// it's here, a placeholder icon if it fails. Downloads are cached in memory and on disk (elg_set_image_cache).
/// A download fails, naming the limit, past a 64 KiB header section, a 64 MiB body, 5 redirects or 30 seconds.
///
/// @param url The image's URL (copied).
/// @param scale Pixels per point.
/// @param content_mode Resizable, keeping its aspect ratio this way (`ContentMode`: 0 fit, 1 fill); negative:
///   at its own size.
/// @param disk_cache false: kept in memory only, never in the disk cache.
/// @param max_pixels The most pixels the image may have (more: the failure phase); 0: the default, 2^27.
/// @param max_side The longest side it's decoded at (longer: scaled down to fit); 0: the default, 8192.
/// @return The image, owned by the caller, or null on failure.
ElgView* elg_async_image(ElgStr url, float scale, int32_t content_mode, bool disk_cache, uint64_t max_pixels, uint32_t max_side);

/// Wraps `set_image_cache()`: AsyncImage's disk cache. Downloads already under way use the cache they started
/// with. UI thread only.
///
/// @param disk Whether downloads are kept on disk between runs.
/// @param disk_limit The most the disk cache holds, in bytes; the least recently used go first past it.
/// @param directory Where the disk cache is; empty: the default, in the user's cache folder.
void elg_set_image_cache(bool disk, uint64_t disk_limit, ElgStr directory);

/// Wraps `clear_image_cache()`: forgets every downloaded image, in memory and on disk. Downloads under way
/// finish without being cached. UI thread only.
void elg_clear_image_cache(void);

/// Wraps `AsyncImage()` with a content function: like elg_async_image(), with a view of your own for each
/// phase.
///
/// @param url The image's URL (copied).
/// @param content Builds the view for each phase. args: ElgAsyncImagePhase*, ret: View*. Required: none is a
///   usage error.
/// @param scale Pixels per point.
/// @param disk_cache false: kept in memory only, never in the disk cache.
/// @param max_pixels The most pixels the image may have (more: the failure phase); 0: the default, 2^27.
/// @param max_side The longest side it's decoded at (longer: scaled down to fit); 0: the default, 8192.
/// @return The image, owned by the caller, or null on failure.
ElgView* elg_async_image_content(ElgStr url, ElgClosure content, float scale, bool disk_cache, uint64_t max_pixels, uint32_t max_side);

/// Wraps `Label()`: an icon followed by a title, spaced for buttons, menus and lists.
///
/// @param title A string prop: the title.
/// @param icon The icon (borrowed; required).
/// @return The label, owned by the caller, or null on failure.
ElgView* elg_label(ElgProp title, const ElgImageSource* icon);

/// Wraps `register_icon_set()`: makes "name.icon" available to Image. Records a UsageError if the name is taken
/// (unless `replace`) or the options are incomplete, and a ResourceError if a file can't be read.
///
/// @param name The set's name.
/// @param font The regular weight's font.
/// @param weights More weights (borrowed).
/// @param weight_count How many `weights` there are.
/// @param variants Variants (borrowed).
/// @param variant_count How many `variants` there are.
/// @param names The name-to-codepoint map's file, as the set ships it: CSS from icon webfonts, JSON, or
///   Material-style codepoints text. The same names apply to every weight and variant.
/// @param names_data Or the map's text (read during the call).
/// @param replace Replace a set registered under the same name.
void elg_register_icon_set(ElgStr name, ElgIconFont font, const ElgIconWeight* weights, size_t weight_count, const ElgIconVariant* variants, size_t variant_count, ElgStr names, ElgStr names_data, bool replace);

/// Wraps `set_default_icon_set()`: the set for icon names without a set prefix ("phosphor" unless changed).
///
/// @param name The set's name.
void elg_set_default_icon_set(ElgStr name);

// --- Fonts ---

/// Wraps `register_font()` with a file: makes it available as `Font::custom(family, ...)`. Register each
/// weight's file separately; a variable font draws every weight. Thread-safe.
///
/// @param family The family's name.
/// @param file The font file.
/// @param weight The file's `Weight`, 1...1000.
void elg_register_font_file(ElgStr family, ElgStr file, int32_t weight);

/// Wraps `register_font()` with font data in memory: like elg_register_font_file(). Thread-safe.
///
/// @param family The family's name.
/// @param data The font data (copied).
/// @param weight The data's `Weight`, 1...1000.
void elg_register_font_data(ElgStr family, ElgBytes data, int32_t weight);

/// Wraps `register_emoji_font()`: draws emoji with this color font (COLR/CPAL, e.g. Twemoji) before the
/// system's, in every text view. Thread-safe; register before the text is first shaped.
///
/// @param file The font file.
void elg_register_emoji_font(ElgStr file);

/// Writes a font into a closure's Font result (the `ret` of a reactive Font prop's closure).
///
/// @param target The closure's `ret`.
/// @param value The font (borrowed).
void elg_font_assign(ElgCppFont* target, const ElgFont* value);

/// Writes a color or gradient into a closure's ShapeStyle result (the `ret` of a reactive ShapeStyle prop's
/// closure).
///
/// @param target The closure's `ret`.
/// @param value The color or gradient (borrowed).
void elg_shape_style_assign(ElgCppShapeStyle* target, const ElgShapeStyle* value);

// --- View modifiers ---

/// Wraps `View::padding()` with insets.
///
/// @param v The view (borrowed).
/// @param insets An EdgeInsets prop (ElgEdgeInsets), in points.
/// @return `v` padded by `insets` (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_padding(const ElgView* v, ElgProp insets);

/// Wraps `View::padding()` on some edges.
///
/// @param v The view (borrowed).
/// @param edges `Edges` bits: 1 top, 2 leading, 4 bottom, 8 trailing.
/// @param length A float prop: the padding, in points.
/// @return `v` padded on `edges` (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_padding_edges(const ElgView* v, uint32_t edges, ElgProp length);

/// Wraps `View::frame()`.
///
/// @param v The view (borrowed).
/// @param o The frame (borrowed).
/// @return `v` in the frame (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_frame(const ElgView* v, const ElgFrameOptions* o);

/// Wraps `View::frame()` with a Size prop: a fixed size that follows state, laid out again whenever the size
/// changes.
///
/// @param v The view (borrowed).
/// @param size A Size prop (ElgSize), in points.
/// @param a Where the content sits in the frame.
/// @return `v` in the frame (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_frame_size(const ElgView* v, ElgProp size, ElgAlignment a);

/// Wraps `View::fixed_size()`: proposes nothing on the given axes, so the content takes its ideal size.
///
/// @param v The view (borrowed).
/// @param horizontal Its ideal width.
/// @param vertical Its ideal height.
/// @return `v` at its ideal size on those axes (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_fixed_size(const ElgView* v, bool horizontal, bool vertical);

/// Wraps `View::aspect_ratio()`: sizes the view to an aspect ratio within what's proposed.
///
/// @param v The view (borrowed).
/// @param has_ratio false: the view's own ideal size gives the ratio (an image's).
/// @param ratio Width / height, when `has_ratio`.
/// @param mode `ContentMode`: 0 fit (all of it shows), 1 fill (it covers the space).
/// @return `v` at that aspect ratio (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_aspect_ratio(const ElgView* v, bool has_ratio, float ratio, int32_t mode);

/// Wraps `View::resizable()`: a raster Image takes whatever size it's offered instead of its own.
///
/// @param v A file or data Image, before other modifiers (borrowed).
/// @return The resizable image (a new view, owned by the caller), or null on failure: a UsageError for any
///   other view.
ElgView* elg_mod_resizable(const ElgView* v);

/// Wraps `View::layout_priority()`: stacks give space to higher priorities first. Default 0.
///
/// @param v The view (borrowed).
/// @param priority The priority.
/// @return `v` with the priority (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_layout_priority(const ElgView* v, float priority);

/// Wraps `View::z_index()`: stacking order among siblings; higher draws in front and is hit first. Default 0.
///
/// @param v The view (borrowed).
/// @param z A float prop.
/// @return `v` at that z index (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_z_index(const ElgView* v, ElgProp z);

/// Wraps `View::offset()`: moves the content when drawn, without affecting layout.
///
/// @param v The view (borrowed).
/// @param x A float prop: the horizontal move, in points.
/// @param y A float prop: the vertical move, in points.
/// @return `v`, moved (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_offset(const ElgView* v, ElgProp x, ElgProp y);

/// Wraps `View::background()` with a view.
///
/// @param v The view (borrowed).
/// @param take_background Drawn behind `v`, sized to it (consumed).
/// @param a Where the background sits.
/// @return `v` on the background (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_background_view(const ElgView* v, ElgView* take_background, ElgAlignment a);

/// Wraps `View::background()` with a color or gradient filling the view's bounds.
///
/// @param v The view (borrowed).
/// @param style A ShapeStyle prop (ElgShapeStyle).
/// @return `v` on the background (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_background(const ElgView* v, ElgProp style);

/// Wraps `View::background()` with a color or gradient filling a shape.
///
/// @param v The view (borrowed).
/// @param style A ShapeStyle prop (ElgShapeStyle).
/// @param shape The shape, filling the view's bounds (borrowed).
/// @return `v` on the background (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_background_shape(const ElgView* v, ElgProp style, const ElgShape* shape);

/// Wraps `View::overlay()`.
///
/// @param v The view (borrowed).
/// @param take_overlay Drawn in front of `v`, sized to it (consumed).
/// @param a Where the overlay sits.
/// @return `v` under the overlay (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_overlay(const ElgView* v, ElgView* take_overlay, ElgAlignment a);

/// Wraps `View::border()`: a border drawn inside the view's bounds, or along `shape`.
///
/// @param v The view (borrowed).
/// @param c A Color prop: the border's color.
/// @param width The border's width, in points.
/// @param shape The border's shape (borrowed); null: the view's bounds.
/// @return `v` with the border (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_border(const ElgView* v, ElgProp c, float width, const ElgShape* shape);

/// Wraps `View::clipped()`: clips the content to the view's bounds.
///
/// @param v The view (borrowed).
/// @return `v`, clipped (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_clipped(const ElgView* v);

/// Wraps `View::clip_shape()`: clips the content to a shape filling the view's bounds.
///
/// @param v The view (borrowed).
/// @param shape The clip's shape (borrowed).
/// @return `v`, clipped (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_clip_shape(const ElgView* v, const ElgShape* shape);

/// Wraps `View::corner_radius()`: clips the content to a rounded rectangle.
///
/// @param v The view (borrowed).
/// @param radius The corners' radius, in points.
/// @return `v`, clipped (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_corner_radius(const ElgView* v, float radius);

/// Wraps `View::opacity()`: fades the view as a group (overlapping content doesn't show through itself).
///
/// @param v The view (borrowed).
/// @param opacity A float prop: 0 transparent ... 1 opaque.
/// @return `v` at that opacity (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_opacity(const ElgView* v, ElgProp opacity);

/// Wraps `View::shadow()`: a blurred shadow of the view's content.
///
/// @param v The view (borrowed).
/// @param s The shadow.
/// @return `v` with the shadow (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_shadow(const ElgView* v, ElgShadow s);

/// Wraps `View::inner_shadow()`: a shadow cast inside the view's content, from its edges inward.
///
/// @param v The view (borrowed).
/// @param s The shadow.
/// @return `v` with the shadow (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_inner_shadow(const ElgView* v, ElgShadow s);

/// Wraps `View::blur()`: a Gaussian blur of the content.
///
/// @param v The view (borrowed).
/// @param radius A float prop: the blur's radius, in points.
/// @param opaque The content fills its bounds: edges stay sharp instead of fading out.
/// @return `v`, blurred (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_blur(const ElgView* v, ElgProp radius, bool opaque);

/// Wraps `View::backdrop_blur()`: blurs what's drawn behind the view in the window (frosted glass), inside
/// `shape`. Like a background, it goes behind everything the view draws.
///
/// @param v The view (borrowed).
/// @param radius A float prop: the blur's radius, in points.
/// @param shape Where the blur shows (borrowed); null: the view's bounds.
/// @param saturation A float prop: 0 gray, 1 unchanged, above 1 more vivid.
/// @param brightness A float prop: added to each channel, -1 black ... 0 unchanged ... 1 white.
/// @param noise A float prop: grain, 0...1, so smooth gradients don't band.
/// @return `v` over the blurred backdrop (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_backdrop_blur(const ElgView* v, ElgProp radius, const ElgShape* shape, ElgProp saturation, ElgProp brightness, ElgProp noise);

/// Wraps `ColorFilterModifier`: the color adjustments `View::brightness()`, `contrast()`, `saturation()`,
/// `grayscale()`, `hue_rotation()`, `sepia()`, `color_invert()`, `color_multiply()` and `luminance_to_alpha()`.
///
/// @param v The view (borrowed).
/// @param kind `ColorFilter::Kind`: 0 brightness, 1 contrast, 2 saturation, 3 grayscale, 4 hue_rotation,
///   5 sepia, 6 invert, 7 multiply, 8 luminance_to_alpha.
/// @param amount A float prop: how much (degrees for hue_rotation); unused for multiply and
///   luminance_to_alpha.
/// @param c A Color prop: what multiply multiplies by; unused for the others.
/// @return `v`, adjusted (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_color_filter(const ElgView* v, int32_t kind, ElgProp amount, ElgProp c);

/// Wraps `View::blend_mode()`: how the view's pixels combine with what's behind them.
///
/// @param v The view (borrowed).
/// @param mode `BlendMode`, by its position in the enum (0 normal, 1 multiply, ...).
/// @return `v`, blended (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_blend_mode(const ElgView* v, int32_t mode);

/// Wraps `View::compositing_group()`: draws the content offscreen first, then composites it as one image.
///
/// @param v The view (borrowed).
/// @return `v` as a group (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_compositing_group(const ElgView* v);

/// Wraps `View::rotation_effect()`: rotates the drawn content clockwise about `anchor`, without affecting
/// layout or hit testing.
///
/// @param v The view (borrowed).
/// @param degrees A float prop: the rotation, in degrees.
/// @param anchor A unit point of the view's bounds; (0.5, 0.5) is the center.
/// @return `v`, rotated (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_rotation_effect(const ElgView* v, ElgProp degrees, ElgPoint anchor);

/// Wraps `View::scale_effect()`: scales the drawn content about `anchor`, without affecting layout or hit
/// testing. A uniform scale stays sharp; an uneven one renders offscreen first.
///
/// @param v The view (borrowed).
/// @param x A float prop: the horizontal scale, or both when `y` is null.
/// @param y A float prop: the vertical scale (borrowed; its closure is taken over); null: a uniform scale by
///   `x`.
/// @param anchor A unit point of the view's bounds; (0.5, 0.5) is the center.
/// @return `v`, scaled (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_scale_effect(const ElgView* v, ElgProp x, const ElgProp* y, ElgPoint anchor);

/// Wraps `View::mask()` with a view: shows the content only where `take_mask` is opaque.
///
/// @param v The view (borrowed).
/// @param take_mask The mask, sized and aligned like an overlay (consumed); only its alpha matters.
/// @param a Where the mask sits.
/// @return `v`, masked (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_mask(const ElgView* v, ElgView* take_mask, ElgAlignment a);

/// Wraps `View::mask()` with a color or gradient: shows the content only where `style` is opaque.
///
/// @param v The view (borrowed).
/// @param style A ShapeStyle prop (ElgShapeStyle) filling the view's bounds; only its alpha matters.
/// @return `v`, masked (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_mask_style(const ElgView* v, ElgProp style);

/// Wraps `View::content_shape()`: hit tests against `shape`, filling the bounds, instead of the drawn content.
///
/// @param v The view (borrowed).
/// @param shape The shape (borrowed).
/// @return `v` with that hit area (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_content_shape(const ElgView* v, const ElgShape* shape);

/// Wraps `View::allows_hit_testing()`.
///
/// @param v The view (borrowed).
/// @param enabled false: the view and everything in it ignore the pointer; events go to what's behind.
/// @return `v`, hit tested or not (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_allows_hit_testing(const ElgView* v, bool enabled);

/// Wraps `View::on_click()`: clicks pressed and released inside the view. The innermost click handler wins.
///
/// @param v The view (borrowed).
/// @param on_click Runs on each click. args: ElgClickEvent*. Required: none is a usage error.
/// @param button `MouseButton`: 0 left, 1 middle, 2 right, 3 other.
/// @param count The clicks: 1 single, 2 double (the first click goes on to outer handlers), 3 triple, ...
/// @return `v` with the handler (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_on_click(const ElgView* v, ElgClosure on_click, int32_t button, int32_t count);

/// Wraps `View::on_activate()`: the view's action, however it's used: a left click, Space or Enter while it
/// has focus, or a screen reader's default action. Makes the view focusable; disabled views don't activate.
///
/// @param v The view (borrowed).
/// @param on_activate The action. No args. Required: none is a usage error.
/// @return `v` with the action (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_on_activate(const ElgView* v, ElgClosure on_activate);

/// Wraps `View::on_appear()`: runs the action once the view is added (its window opened, an If or
/// ForEach showed it, or a lazy stack built it), on the UI thread, before that update is drawn.
///
/// @param v The view (borrowed).
/// @param on_appear The action. No args. May be none: nothing runs.
/// @return `v` with the action (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_on_appear(const ElgView* v, ElgClosure on_appear);

/// Wraps `View::on_disappear()`: runs the action once a view that appeared is gone (after its exit
/// transition, or when its window closed), on the UI thread.
///
/// @param v The view (borrowed).
/// @param on_disappear The action. No args. May be none: nothing runs.
/// @return `v` with the action (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_on_disappear(const ElgView* v, ElgClosure on_disappear);

/// Wraps `View::on_size_change()`: called after the first layout and whenever the view's size in pixels
/// changes, including with the display scale. Runs on the UI thread, before paint.
///
/// @param v The view (borrowed).
/// @param on_size_change args: ElgPixelSize* (the logical size times the display scale, rounded up; may be
///   zero). Required: none is a usage error.
/// @return `v` with the handler (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_on_size_change(const ElgView* v, ElgClosure on_size_change);

// --- Gestures ---

/// Wraps `View::recognize()` with a `DragGesture`. Once recognized, the drag takes the press over: a button
/// or click handler under it doesn't fire.
///
/// @param v The view (borrowed).
/// @param o When the drag begins.
/// @param began The drag was recognized. args: ElgDragEvent*; may be none.
/// @param changed The pointer moved (also right after `began`). args: ElgDragEvent*; may be none.
/// @param ended The button was released. args: ElgDragEvent*; may be none.
/// @param cancelled The pointer was lost before the release. No args; may be none.
/// @param options How it competes with other gestures for the press.
/// @return `v` with the gesture (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_drag_gesture(const ElgView* v, ElgDragOptions o, ElgClosure began, ElgClosure changed, ElgClosure ended, ElgClosure cancelled, ElgGestureOptions options);

/// Wraps `View::recognize()` with a `LongPressGesture`: runs `on_press` once a press has been held for the
/// duration. The click it would have been then doesn't happen.
///
/// @param v The view (borrowed).
/// @param on_press The action. No args.
/// @param o When a press is long.
/// @param pressing Called with true when a press that could become the long press goes down, and false when
///   it lifts, moves away or is taken by something else. args: bool*; may be none.
/// @param options How it competes with other gestures for the press.
/// @return `v` with the gesture (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_long_press_gesture(const ElgView* v, ElgClosure on_press, ElgLongPressOptions o, ElgClosure pressing, ElgGestureOptions options);

/// Wraps `View::recognize()` with a `MagnifyGesture`: pinching on a trackpad. The innermost one under the
/// pointer that takes the start gets the rest.
///
/// @param v The view (borrowed).
/// @param began The pinch started. args: ElgMagnifyEvent*; may be none.
/// @param changed The fingers moved. args: ElgMagnifyEvent*; may be none.
/// @param ended The pinch ended. args: ElgMagnifyEvent*; may be none.
/// @param cancelled The system took the gesture over. No args; may be none.
/// @return `v` with the gesture (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_magnify_gesture(const ElgView* v, ElgClosure began, ElgClosure changed, ElgClosure ended, ElgClosure cancelled);

/// Wraps `View::recognize()` with a `RotateGesture`: turning two fingers on a trackpad. The innermost one
/// under the pointer that takes the start gets the rest.
///
/// @param v The view (borrowed).
/// @param began The turn started. args: ElgRotateEvent*; may be none.
/// @param changed The fingers moved. args: ElgRotateEvent*; may be none.
/// @param ended The turn ended. args: ElgRotateEvent*; may be none.
/// @param cancelled The system took the gesture over. No args; may be none.
/// @return `v` with the gesture (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_rotate_gesture(const ElgView* v, ElgClosure began, ElgClosure changed, ElgClosure ended, ElgClosure cancelled);

/// Wraps `View::on_two_finger_double_tap()`: a two-finger double tap on a trackpad (usually: zoom to fit).
///
/// @param v The view (borrowed).
/// @param on_tap args: ElgPoint* (where, in window coordinates). Required: none is a usage error.
/// @return `v` with the gesture (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_on_two_finger_double_tap(const ElgView* v, ElgClosure on_tap);

// --- Pointer, scrolling, keys, text ---

/// Wraps `View::pointer_style()`: the pointer's shape over the view, like CSS's `cursor`. Views inside can set
/// their own.
///
/// @param v The view (borrowed).
/// @param style A PointerStyle prop (int32_t).
/// @return `v` with the pointer style (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_pointer_style(const ElgView* v, ElgProp style);

/// Wraps `View::on_pointer_enter()` and `View::on_pointer_leave()`: called at once when the pointer comes over
/// the view (its hit area), or when it leaves.
///
/// @param v The view (borrowed).
/// @param leave true: when the pointer leaves (on_pointer_leave); false: when it comes over (on_pointer_enter).
/// @param on_cross The action. No args.
/// @return `v` with the handler (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_on_pointer_boundary(const ElgView* v, bool leave, ElgClosure on_cross);

/// Wraps `View::on_hover_change()`: hover intent. Called with true once the pointer has rested on the view for
/// the hover delay, and false when it leaves (after the exit delay).
///
/// @param v The view (borrowed).
/// @param on_hover args: bool*.
/// @return `v` with the handler (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_on_hover_change(const ElgView* v, ElgClosure on_hover);

/// Wraps `View::on_pointer()`: raw pointer events over the view. Consuming a down captures the pointer, so the
/// moves and the up come here wherever it goes.
///
/// @param v The view (borrowed).
/// @param on_pointer args: ElgPointerEvent* (in the view's coordinates), ret: bool* (true consumes it).
///   Required: none is a usage error.
/// @return `v` with the handler (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_on_pointer(const ElgView* v, ElgClosure on_pointer);

/// Wraps `View::on_scroll()`: wheel and trackpad scrolling over the view.
///
/// @param v The view (borrowed).
/// @param on_scroll args: ElgScrollEvent* (in the view's coordinates), ret: bool* (true consumes it: scroll
///   views around it then don't scroll). Required: none is a usage error.
/// @return `v` with the handler (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_on_scroll(const ElgView* v, ElgClosure on_scroll);

/// Wraps `View::on_text_input()`: makes the view focusable and sees the text typed while it has focus: commits,
/// and an IME's compositions in progress. Keys still go to elg_mod_on_key().
///
/// @param v The view (borrowed).
/// @param on_text_input args: ElgTextInputEvent* (its text valid during the call), ret: bool* (true: handled).
///   Required: none is a usage error.
/// @return `v` with the handler (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_on_text_input(const ElgView* v, ElgClosure on_text_input);

/// Wraps `View::on_drop()`: files or text dragged from other apps can be dropped here. The innermost view under
/// the pointer that takes that kind of thing gets it.
///
/// @param v The view (borrowed).
/// @param files Takes dropped files. args: ElgDropFiles*; ret: a bool* that's ignored (what it returns has no
///   effect). None: files aren't taken.
/// @param text Takes dropped text. args: ElgDropText*; ret: a bool* that's ignored. None: text isn't taken.
/// @param targeted Called with true while a drag the view can take is over it (for a highlight), and false
///   when it leaves. args: bool*; may be none.
/// @return `v` taking drops (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_on_drop(const ElgView* v, ElgClosure files, ElgClosure text, ElgClosure targeted);

/// Wraps `View::accessibility_label()`: what the view is called, for screen readers.
///
/// @param v The view (borrowed).
/// @param label A string prop.
/// @return `v` with the label (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_accessibility_label(const ElgView* v, ElgProp label);

/// Wraps `View::accessibility_value()`: what the view holds, as words ("3 of 10", "50%").
///
/// @param v The view (borrowed).
/// @param value A string prop.
/// @return `v` with the value (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_accessibility_value(const ElgView* v, ElgProp value);

/// Wraps `View::accessibility_hint()`: what happens if the view is used, when the label doesn't say.
///
/// @param v The view (borrowed).
/// @param hint A string prop.
/// @return `v` with the hint (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_accessibility_hint(const ElgView* v, ElgProp hint);

/// Wraps `View::accessibility_hidden()`: leaves the view, and everything inside, out for screen readers
/// (decoration).
///
/// @param v The view (borrowed).
/// @param hidden Whether it's left out.
/// @return `v`, hidden or not (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_accessibility_hidden(const ElgView* v, bool hidden);

/// Wraps `View::accessibility_role()`: what the view is to screen readers, when the automatic choice isn't
/// right.
///
/// @param v The view (borrowed).
/// @param role `AccessibilityRole`, by its position in the enum (0 group, 1 label, 2 heading, 3 button, ...).
/// @return `v` with the role (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_accessibility_role(const ElgView* v, int32_t role);

/// Wraps `View::accessibility_element()`: one element for everything inside, labeled with their text.
///
/// @param v The view (borrowed).
/// @return `v` as one element (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_accessibility_element(const ElgView* v);

/// Wraps `View::accessibility_action()`: what a screen reader's default action does, for views made clickable
/// with gestures.
///
/// @param v The view (borrowed).
/// @param on_action The action. No args. Required: none is a usage error.
/// @return `v` with the action (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_accessibility_action(const ElgView* v, ElgClosure on_action);

/// Wraps `View::hover_delay()`: the hover delay for on_hover_change handlers and submenus inside (default:
/// enter 0.1 s, exit 0).
///
/// @param v The view (borrowed).
/// @param delay The delays, in seconds.
/// @return `v` with the delay (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_hover_delay(const ElgView* v, ElgHoverDelay delay);

/// Wraps `View::window_drag_area()`: pressing and dragging here moves the window (custom title bars), and
/// double-clicking maximizes it. Controls inside still work.
///
/// @param v The view (borrowed).
/// @param enabled Whether it moves the window.
/// @return `v` as a drag area or not (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_window_drag_area(const ElgView* v, bool enabled);

/// Wraps `View::context_menu()`: a right-click (or Shift+F10 or the Menu key while focused) opens the menu
/// `menu` builds. Item actions run after it closes.
///
/// @param v The view (borrowed).
/// @param menu Builds the menu each time it opens, usually with elg_menu(). ret: View*. Required: none is a
///   usage error.
/// @return `v` with the menu (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_context_menu(const ElgView* v, ElgClosure menu);

/// Wraps `View::floating()`: `content` floating above everything by the view while `take_is_presented` is
/// true, with no chrome of its own.
///
/// @param v The view (borrowed).
/// @param take_is_presented Whether it's shown (consumed); set back to false when it's dismissed.
/// @param content Builds the content each time it opens. ret: View*. Required: none is a usage error.
/// @param o The options (borrowed; required).
/// @return `v` with the floating content (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_floating(const ElgView* v, ElgBindingBool* take_is_presented, ElgClosure content, const ElgFloatingOptions* o);

/// Wraps `View::floating_container()`: marks the view as where `FloatingBoundary::container` content inside it
/// stays.
///
/// @param v The view (borrowed).
/// @return `v` as a container (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_floating_container(const ElgView* v);

/// Wraps `View::tooltip()`: shown in the TooltipStyle after the pointer rests on the view for a moment, until
/// it leaves or presses. Screen readers don't see it.
///
/// @param v The view (borrowed).
/// @param content Builds the tooltip, when `text` is null (required then). ret: View*. Dropped unused
///   when `text` is given.
/// @param text A string prop for a text tooltip (borrowed; its closure is taken over); null: `content`.
/// @param o The options (borrowed; required).
/// @return `v` with the tooltip (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_tooltip(const ElgView* v, ElgClosure content, const ElgProp* text, const ElgTooltipOptions* o);

/// Wraps `View::popover()`: a panel of `content` beside the view while `take_is_presented` is true. Clicking
/// outside it, Esc, or switching apps closes it and sets the binding back to false.
///
/// @param v The view (borrowed).
/// @param take_is_presented Whether it's shown (consumed).
/// @param content Builds the content each time it opens. ret: View*. Required: none is a usage error.
/// @param popover_placement Where the panel goes, by the view (borrowed; required).
/// @param boundary `FloatingBoundary`: 0 screen, 1 window, 2 container.
/// @param padded A bool prop: false lets the content reach the panel's edges.
/// @param popup_motion How it opens and closes; `has` false: the PopoverStyle's.
/// @return `v` with the popover (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_popover(const ElgView* v, ElgBindingBool* take_is_presented, ElgClosure content, const ElgFloatingPlacement* popover_placement, int32_t boundary, ElgProp padded, ElgPopupMotion popup_motion);

/// Wraps `View::focusable()`.
///
/// @param v The view (borrowed).
/// @param focusable true: the view takes keyboard focus (Tab order, clicks). false: the view and everything
///   inside never take focus.
/// @return `v`, focusable or not (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_focusable(const ElgView* v, bool focusable);

/// Wraps `View::focused()`: two-way focus. Makes the view focusable.
///
/// @param v The view (borrowed).
/// @param take_is_focused True while the view has focus; setting it true focuses the view, false removes
///   focus from it (consumed).
/// @return `v` with the binding (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_focused(const ElgView* v, ElgBindingBool* take_is_focused);

/// Wraps `View::on_key_press()`: runs `on_press` when `key` is pressed while the view, or something inside, has
/// focus.
///
/// @param v The view (borrowed).
/// @param key `Key`, by its position in the enum.
/// @param on_press The action. No args.
/// @return `v` with the handler (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_on_key_press(const ElgView* v, int32_t key, ElgClosure on_press);

/// Wraps `View::on_key()`: sees every key down and up while the view, or something inside, has focus.
/// Unhandled keys bubble out.
///
/// @param v The view (borrowed).
/// @param on_key args: ElgKeyEvent*, ret: bool* (true: handled).
/// @return `v` with the handler (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_on_key(const ElgView* v, ElgClosure on_key);

// --- Selection ---

/// Appends a key to the result of elg_mod_selection()'s `get`.
///
/// @param target The closure's `ret`.
/// @param key The key (its string is copied).
void elg_item_keys_push(ElgItemKeys* target, ElgItemKey key);

/// Wraps `View::selection()`: makes the rows of a stack over a ForEach selectable, by their ForEach keys. Put it
/// on the stack itself. Each row is drawn by the RowStyle.
///
/// @param v The stack (borrowed).
/// @param multiple A set of rows (Ctrl+click or Cmd+click, Shift ranges, select all); false: one row or none.
/// @param string_keys The ForEach's keys are strings; false: integers.
/// @param get The selected keys; a tracked read. ret: std::vector<ItemKey>* (filled with elg_item_keys_push).
///   Required: none is a usage error.
/// @param set Sets the selected keys; with `multiple` false, one key or none. args: ElgItemKeys*. Required:
///   none is a usage error.
/// @param activate Enter, or a double click on a row: opens what the row stands for. args: ElgItemKey* (its
///   string valid during the call); may be none.
/// @return The selectable stack (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_selection(const ElgView* v, bool multiple, bool string_keys, ElgClosure get, ElgClosure set, ElgClosure activate);

/// Wraps `View::font_weight()`: the weight of the font inside, keeping its size and family.
///
/// @param v The view (borrowed).
/// @param weight A Weight prop (int32_t, 1...1000).
/// @return `v` with the weight set inside (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_font_weight(const ElgView* v, ElgProp weight);

/// Wraps `View::font()`: the font of the text inside.
///
/// @param v The view (borrowed).
/// @param f A Font prop (ElgFont).
/// @return `v` with the font set inside (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_font(const ElgView* v, ElgProp f);

/// Wraps `View::foreground_style()`: the color of text and unfilled shapes inside.
///
/// @param v The view (borrowed).
/// @param c A Color prop.
/// @return `v` with the color set inside (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_foreground_style(const ElgView* v, ElgProp c);

/// Wraps `View::tint()`: the accent color of controls inside.
///
/// @param v The view (borrowed).
/// @param c A Color prop.
/// @return `v` with the tint set inside (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_tint(const ElgView* v, ElgProp c);

/// Wraps `View::color_scheme()`: light or dark, for ThemeColor tokens inside.
///
/// @param v The view (borrowed).
/// @param scheme A ColorScheme prop (int32_t: 0 light, 1 dark).
/// @return `v` with the scheme set inside (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_color_scheme(const ElgView* v, ElgProp scheme);

/// Wraps `View::theme()`: the theme inside.
///
/// @param v The view (borrowed).
/// @param theme The theme (borrowed; copied).
/// @return `v` with the theme set inside (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_theme(const ElgView* v, const ElgTheme* theme);

/// Wraps `View::disabled()`: controls inside stop responding and look disabled.
///
/// @param v The view (borrowed).
/// @param disabled A bool prop.
/// @return `v`, disabled or not (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_disabled(const ElgView* v, ElgProp disabled);

/// Wraps `View::animation()`: changes inside `v` animate with `animation` whenever `version` changed in the
/// same update.
///
/// @param v The view (borrowed).
/// @param animation The animation (borrowed; copied).
/// @param version A number that changes when the value the animation follows does; read as View::animation
