///
/// @param v The view (borrowed).
/// @param transition The transition (borrowed; copied).
/// @return `v` with the transition (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_transition(const ElgView* v, const ElgTransition* transition);

/// Wraps `View::animates_layout()`.
///
/// @param v The view (borrowed).
/// @param enabled false: this view and everything inside snap to new positions and sizes instead of easing
///   there. Colors, opacity and transitions still animate.
/// @return `v`, animating layout or not (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_animates_layout(const ElgView* v, bool enabled);

// --- Hot reload ---

/// Wraps `HotReload()`: the views module's content, rebuilt and reloaded when its sources change; a status
/// badge shows building, errors and reloads. The module is loaded right away.
///
/// @param module The views module as the build writes it (it's loaded from a copy).
/// @param build_command Run through the shell when a watched file changes; empty: never rebuild, only reload
///   when the module file itself changes.
/// @param watch Files and folders (searched recursively) whose changes trigger a rebuild.
/// @param watch_count How many `watch` paths there are.
/// @param show `HotReloadShow`: 0 the module's root view, 1 its previews.
/// @param app_hash `HotReloadOptions::app_hash`: the hash of the types this host shares with the module, the
///   one the module gives elg_rust_module_entry(); 0 for none. A load whose hash differs isn't mounted.
/// @return The view, owned by the caller, or null on failure.
ElgView* elg_hot_reload(ElgStr module, ElgStr build_command, const ElgStr* watch, size_t watch_count, int32_t show, uint64_t app_hash);

// --- Views modules (hot reload and previews) ---

/// The `ModuleEntry` of a Rust views module: its elg_module_entry (elegance's `preview` feature) returns this.
/// Called by each module as it loads (every reload is a new module), on the UI thread.
///
/// @param has_root The module has a root view.
/// @param previews The module's previews (borrowed; their strings are copied).
/// @param count How many `previews` there are.
/// @param build Builds this module's root view or one of its previews, by index; the entry calls it.
/// @param app_hash The hash of the types the app's host shares with this module (`ModuleEntry::app_hash`), the
///   one the host gives elg_hot_reload(); 0 for none.
/// @return The entry, of this module alone, kept by the shim for the rest of the process; null on failure. It
///   carries the hash of the Elegance headers this library was compiled with (`ModuleEntry::elegance_hash`).
const ElgModuleEntry* elg_rust_module_entry(bool has_root, const ElgPreviewDesc* previews, size_t count, ElgModuleBuild build, uint64_t app_hash);

// --- Grids ---

/// Wraps `VGrid()`, `HGrid()` and `Grid()`: children in columns row after row, in rows column after column, or a
/// table of GridRows.
///
/// @param desc The grid (borrowed).
/// @param children The children (consumed).
/// @param count How many `children` there are.
/// @return The grid, owned by the caller, or null on failure.
ElgView* elg_grid(const ElgGridDesc* desc, ElgView** children, size_t count);

/// Wraps `size_that_fits()` of `VGridLayout`, `HGridLayout` or `GridLayout`, for custom layouts that measure
/// their children as a grid does.
///
/// @param desc The grid (borrowed).
/// @param proposal The size offered to the grid.
/// @param children The custom layout's children (borrowed).
/// @param count How many `children` there are.
/// @return The size the grid takes; zero on failure.
ElgSize elg_grid_layout_size(const ElgGridDesc* desc, ElgProposedSize proposal, const ElgLayoutChild* children, size_t count);

/// Wraps `place_children()` of `VGridLayout`, `HGridLayout` or `GridLayout`, for custom layouts that place
/// their children as a grid does.
///
/// @param desc The grid (borrowed).
/// @param bounds Where the grid is, at the size elg_grid_layout_size() reported for `proposal`.
/// @param proposal The size offered to the grid.
/// @param children The custom layout's children (borrowed).
/// @param count How many `children` there are.
void elg_grid_layout_place(const ElgGridDesc* desc, ElgRect bounds, ElgProposedSize proposal, const ElgLayoutChild* children, size_t count);

/// Wraps `GridRow()`: one row of a Grid; each child is a cell.
///
/// @param row_alignment How this row's cells line up (`VerticalAlignment`); negative: the grid's.
/// @param cells The cells (consumed).
/// @param count How many `cells` there are.
/// @return The row, owned by the caller, or null on failure.
ElgView* elg_grid_row(int32_t row_alignment, ElgView** cells, size_t count);

/// Wraps `resolve_grid_tracks()`: the tracks `items` make in a length. Fixed tracks take their size; the rest
/// share what's left equally, within their limits; an adaptive item becomes as many tracks as fit in its share.
/// At least one track results.
///
/// @param items The items (borrowed).
/// @param count How many `items` there are.
/// @param has_length false: the tracks take their ideal sizes.
/// @param length_value The length to fill, in points, when `has_length`; infinity: ideal sizes.
/// @param spacing Between items without their own spacing; unset: `default_stack_spacing`.
/// @param each Called once per track, in order, during this call. args: ElgGridTrack*. Required: none is a
///   usage error.
void elg_resolve_grid_tracks(const ElgGridItem* items, size_t count, bool has_length, float length_value, ElgOptLen spacing, ElgClosure each);

/// Wraps `View::grid_cell_columns()`: a Grid cell that spans `count` columns.
///
/// @param v The cell (borrowed).
/// @param count How many columns it spans.
/// @return `v`, spanning them (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_grid_cell_columns(const ElgView* v, int32_t count);

/// Wraps `View::grid_cell_alignment()`: where this view sits in its grid cell, instead of its row's, column's or
/// grid's alignment.
///
/// @param v The cell (borrowed).
/// @param a Where it sits.
/// @return `v` with the alignment (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_grid_cell_alignment(const ElgView* v, ElgAlignment a);

/// Wraps `View::grid_column_alignment()`: the horizontal alignment of every cell in this cell's Grid column.
///
/// @param v The cell (borrowed).
/// @param a `HorizontalAlignment`.
/// @return `v` with the alignment (a new view, owned by the caller), or null on failure.
ElgView* elg_mod_grid_column_alignment(const ElgView* v, int32_t a);

// --- ABI layout ---

/// Describes the layout of this file's structs, for a binding's layout test: one line per struct,
/// "name size align", then " field:offset" for each of its fields, in order.
///
/// @param out Receives each line.
/// @param ctx Passed to `out`.
void elg_layouts_views(ElgStrSink out, void* ctx);

// --- Layout ---

/// A container laid out by Rust: an elg::Layout whose methods call `layout`, used like a stack.
///
/// @param layout Consumed closure; args: `ElgLayoutCall*`, ret: what its `op` says. Required: none
///   is a usage error.
/// @param children The child views: each is consumed; the array is borrowed.
/// @param count Number of `children`.
/// @return The container, owned by the caller, or nullptr on failure.
ElgView* elg_rust_layout_view(ElgClosure layout, ElgView** children, size_t count);

/// The Rust cache stored in `cache`, or null.
///
/// @param cache An ElgLayoutCall's `cache` (borrowed).
/// @return The `data` of the closure elg_layout_cache_set() stored, owned by the cache; null if
///   none is stored. Null on failure.
void* elg_layout_cache_get(const ElgLayoutCache* cache);

/// Stores a Rust cache in `cache` (LayoutCache::value), replacing (and dropping) the one before.
///
/// @param cache An ElgLayoutCall's `cache` (borrowed).
/// @param owner Consumed closure that's never called: its `data` is the cache, and its `drop` runs
///   when it's replaced or the view goes away.
void elg_layout_cache_set(ElgLayoutCache* cache, ElgClosure owner);

/// Reads LayoutCache::stale: set when the children change or one of them may have a new size.
///
/// @param cache An ElgLayoutCall's `cache` (borrowed).
/// @return true if the cache needs refreshing. False on failure.
bool elg_layout_cache_stale(const ElgLayoutCache* cache);

/// Sets LayoutCache::stale; clear it once the cache is refreshed.
///
/// @param cache An ElgLayoutCall's `cache` (borrowed).
/// @param stale Whether the cache needs refreshing.
void elg_layout_cache_set_stale(ElgLayoutCache* cache, bool stale);

/// Wraps `LayoutChild::size_that_fits()`: measures a child for a proposal.
///
/// @param child One of an ElgLayoutCall's `children`, or an ElgLayoutModifierCall's `content`
///   (borrowed).
/// @param proposal The proposed size.
/// @return The child's size in points, or zero on failure.
ElgSize elg_layout_child_size_that_fits(const ElgLayoutChild* child, ElgProposedSize proposal);

/// Wraps `LayoutChild::place()`: positions a child's top-left corner; it sizes itself from
/// `proposal`.
///
/// @param child One of an ElgLayoutCall's `children`, or an ElgLayoutModifierCall's `content`
///   (borrowed).
/// @param position Where its top-left corner goes, in points.
/// @param proposal The proposed size.
void elg_layout_child_place(const ElgLayoutChild* child, ElgPoint position, ElgProposedSize proposal);

/// Wraps `LayoutChild::layout_priority()`.
///
/// @param child A child (borrowed).
/// @return The child's layout priority. 0 on failure.
float elg_layout_child_priority(const ElgLayoutChild* child);

/// Wraps `LayoutChild::is_spacer()`.
///
/// @param child A child (borrowed).
/// @return true if the child is a Spacer. False on failure.
bool elg_layout_child_is_spacer(const ElgLayoutChild* child);

// --- Layout values set from Rust ---

/// Carries a Rust value for the parent layout without changing layout, like View::layout_value().
///
/// @param v The view to modify (borrowed).
/// @param owner Consumed closure: its `data` is the value, and its `call` (args: null, ret: `bool*`)
///   answers whether it holds the key the Rust side is looking up. A panic there counts as false
///   for the lookup, and propagates out of App::run like one in any callback. Required: none is a
///   usage error.
/// @return The modified view, owned by the caller, or nullptr on failure.
ElgView* elg_mod_rust_layout_value(const ElgView* v, ElgClosure owner);

/// The data of the matching Rust layout value on `child`, or null: `LayoutChild::value()` for the
/// one C++ key that carries every Rust key.
///
/// @param child A child (borrowed).
/// @return The `data` of the elg_mod_rust_layout_value() closure that matched, owned by its view;
///   null if none did, or on failure.
const void* elg_layout_child_rust_value(const ElgLayoutChild* child);

// --- Modifiers ---

/// An elg::ViewModifier implemented in Rust: `body` composes the content with other views and
/// modifiers, once, when the view is mounted.
///
/// @param v The view to modify (borrowed).
/// @param body Consumed closure; args: `View*`, the content (owned by the Rust side, which must
///   consume or free it); ret: `View*` (set it with elg_view_move_into()). Required: none is a
///   usage error.
/// @return The modified view, owned by the caller, or nullptr on failure.
ElgView* elg_mod_rust_view_modifier(const ElgView* v, ElgClosure body);

/// An elg::LayoutModifier implemented in Rust: it takes part in layout, wrapping the view.
///
/// @param v The view to modify (borrowed).
/// @param layout Consumed closure; args: `ElgLayoutModifierCall*`, ret: what its `op` says. For
///   layout_priority, `has` false keeps the content's own. Required: none is a usage error.
/// @return The modified view, owned by the caller, or nullptr on failure.
ElgView* elg_mod_rust_layout_modifier(const ElgView* v, ElgClosure layout);

/// An elg::DecorationModifier implemented in Rust: a secondary view sized to the content, which
/// doesn't affect layout.
///
/// @param v The view to modify (borrowed).
/// @param decoration Consumed closure that builds the decoration; args: null, ret: `View*` (set it
///   with elg_view_move_into()). Required: none is a usage error.
/// @param placement DecorationModifier::Placement (behind, in_front, mask): 0 drawn behind the
///   content, 1 in front of it, 2 not drawn but masking the content with its alpha.
/// @param a How the decoration is aligned with the content.
/// @return The modified view, owned by the caller, or nullptr on failure.
ElgView* elg_mod_rust_decoration_modifier(const ElgView* v, ElgClosure decoration, int32_t placement, ElgAlignment a);

/// An elg::EnvironmentModifier implemented in Rust: changes inherited values for everything inside
/// the view.
///
/// @param v The view to modify (borrowed).
/// @param apply Consumed closure; args: `EnvironmentValues*`, to change with the elg_env_set_*
///   functions; ret: null. Required: none is a usage error.
/// @return The modified view, owned by the caller, or nullptr on failure.
ElgView* elg_mod_rust_environment_modifier(const ElgView* v, ElgClosure apply);

/// An elg::EffectModifier implemented in Rust: changes how the view's content is drawn and hit
/// tested, not its layout.
///
/// @param v The view to modify (borrowed).
/// @param apply Consumed closure; args: `Effects*`, to change with the elg_effects_* functions;
///   ret: null. Required: none is a usage error.
/// @return The modified view, owned by the caller, or nullptr on failure.
ElgView* elg_mod_rust_effect_modifier(const ElgView* v, ElgClosure apply);

/// Sets Effects::clip_shape: the content is clipped to `shape`, which fills the view's bounds.
///
/// @param e The effects (borrowed).
/// @param shape The shape (borrowed; copied); null: no clip.
void elg_effects_set_clip_shape(ElgEffects* e, const ElgShape* shape);

/// Sets Effects::opacity.
///
/// @param e The effects (borrowed).
/// @param opacity The opacity, 0 to 1: an ElgProp of float.
void elg_effects_set_opacity(ElgEffects* e, ElgProp opacity);

/// Sets Effects::shadow, a drop shadow.
///
/// @param e The effects (borrowed).
/// @param s The shadow (borrowed); null: none.
void elg_effects_set_shadow(ElgEffects* e, const ElgShadow* s);

/// Sets Effects::offset_x and offset_y: moves the drawn content (and where it's hit) without
/// affecting layout.
///
/// @param e The effects (borrowed).
/// @param x Horizontal offset in points: an ElgProp of float.
/// @param y Vertical offset in points: an ElgProp of float.
void elg_effects_set_offset(ElgEffects* e, ElgProp x, ElgProp y);

/// Sets Effects::z_index: the stacking order among siblings.
///
/// @param e The effects (borrowed).
/// @param z The z index: an ElgProp of float; null: unset.
void elg_effects_set_z_index(ElgEffects* e, const ElgProp* z);

/// Sets Effects::content_shape: the view is hit tested on `shape` (filling its bounds) instead of
/// where its content draws.
///
/// @param e The effects (borrowed).
/// @param shape The shape (borrowed; copied); null: where the content draws.
void elg_effects_set_content_shape(ElgEffects* e, const ElgShape* shape);

/// Sets Effects::inner_shadow, a shadow inside the content's edges.
///
/// @param e The effects (borrowed).
/// @param s The shadow (borrowed); null: none.
void elg_effects_set_inner_shadow(ElgEffects* e, const ElgShadow* s);

/// Sets Effects::blur and blur_opaque.
///
/// @param e The effects (borrowed).
/// @param radius The blur radius in points: an ElgProp of float; null: no blur.
/// @param opaque Whether the content fills its bounds: its edges then stay sharp instead of fading
///   out.
void elg_effects_set_blur(ElgEffects* e, const ElgProp* radius, bool opaque);

/// Sets Effects::color_filter: a color adjustment applied to the content's pixels, in sRGB with
/// straight alpha, as CSS filter functions are.
///
/// @param e The effects (borrowed).
/// @param kind A ColorFilter::Kind: 0 brightness, 1 contrast, 2 saturation, 3 grayscale,
///   4 hue_rotation, 5 sepia, 6 invert, 7 multiply, 8 luminance_to_alpha. kind < 0: none.
/// @param amount An ElgProp of float: degrees for hue_rotation; unused for multiply and
///   luminance_to_alpha. Ignored, and its closure dropped, when `kind` < 0.
/// @param c An ElgProp of elg::Color, for multiply only. Ignored, and its closure dropped, when
///   `kind` < 0.
void elg_effects_set_color_filter(ElgEffects* e, int32_t kind, ElgProp amount, ElgProp c);

/// Reads Effects::blend_mode.
///
/// @param e The effects (borrowed).
/// @return The elg::BlendMode (0 normal; see elg_effects_set_blend_mode()). 0 on failure.
int32_t elg_effects_blend_mode(const ElgEffects* e);

/// Sets Effects::blend_mode: how the view's pixels combine with what's behind them, as CSS's
/// mix-blend-mode.
///
/// @param e The effects (borrowed).
/// @param mode An elg::BlendMode: 0 normal, 1 multiply, 2 darken, 3 color_burn, 4 plus_darker,
///   5 screen, 6 lighten, 7 color_dodge, 8 plus_lighter, 9 overlay, 10 soft_light, 11 hard_light,
///   12 difference, 13 exclusion, 14 hue, 15 saturation, 16 color, 17 luminosity.
void elg_effects_set_blend_mode(ElgEffects* e, int32_t mode);

/// Reads Effects::compositing_group.
///
/// @param e The effects (borrowed).
/// @return true if the content is drawn offscreen even when nothing else needs it. False on failure.
bool elg_effects_compositing_group(const ElgEffects* e);

/// Sets Effects::compositing_group.
///
/// @param e The effects (borrowed).
/// @param group Whether to draw the content offscreen even when nothing else needs it.
void elg_effects_set_compositing_group(ElgEffects* e, bool group);

/// Sets Effects::rotation: the drawn content turns about the anchor (elg_effects_set_anchor()).
///
/// @param e The effects (borrowed).
/// @param degrees Clockwise, as an ElgProp of float; null: unset.
void elg_effects_set_rotation(ElgEffects* e, const ElgProp* degrees);

/// Sets Effects::scale_x and scale_y: the drawn content scales about the anchor
/// (elg_effects_set_anchor()).
///
/// @param e The effects (borrowed).
/// @param x Horizontal scale (1: as is), as an ElgProp of float; null: unset.
/// @param y Vertical scale, as an ElgProp of float; null: unset.
void elg_effects_set_scale(ElgEffects* e, const ElgProp* x, const ElgProp* y);

/// Reads Effects::anchor.
///
/// @param e The effects (borrowed).
/// @return The unit point rotation and scale are about; (0.5, 0.5) is the middle. Zero on failure.
ElgPoint elg_effects_anchor(const ElgEffects* e);

/// Sets Effects::anchor: what rotation and scale are about.
///
/// @param e The effects (borrowed).
/// @param anchor A unit point of the view's bounds: (0, 0) top-leading, (1, 1) bottom-trailing.
void elg_effects_set_anchor(ElgEffects* e, ElgPoint anchor);

/// Reads Effects::allows_hit_testing.
///
/// @param e The effects (borrowed).
/// @return false if the view lets clicks through. False on failure.
bool elg_effects_allows_hit_testing(const ElgEffects* e);

/// Sets Effects::allows_hit_testing.
///
/// @param e The effects (borrowed).
/// @param enabled false: the view isn't hit, and clicks go to what's behind it.
void elg_effects_set_allows_hit_testing(ElgEffects* e, bool enabled);

// --- Event handlers ---

/// An elg::EventModifier implemented in Rust: handles input for the view, with one handler per
/// mounted view.
///
/// @param v The view to modify (borrowed).
/// @param make_handler Consumed closure, called when the view mounts; args: null, ret:
///   `ElgClosure*`, the new handler, which Elegance consumes. The handler's args:
///   `ElgEventCall*`; its ret: what the call's `op` says. Required: none is a usage error.
/// @return The modified view, owned by the caller, or nullptr on failure.
ElgView* elg_mod_rust_event_modifier(const ElgView* v, ElgClosure make_handler);

// --- ABI layout ---

/// Describes the layout of this file's structs, for a binding's layout test: one line per struct,
/// "name size align", then " field:offset" for each of its fields, in order.
///
/// @param out Receives each line.
/// @param ctx Passed to `out`.
void elg_layouts_ext(ElgStrSink out, void* ctx);

// --- Audio ---

/// Wraps `audio_output_devices()`: the system's audio outputs (speakers, headphones, virtual
/// devices).
///
/// @param each Borrowed closure, called once per device before this returns; args: `ElgDevice*`,
///   ret: null. Required: none is a usage error.
void elg_audio_output_devices(ElgClosure each);

/// Wraps `Sound::load()` for a file: a short sound, decoded into memory once (WAV, FLAC, or MP3).
/// Callable from any thread.
///
/// @param file The file's path.
/// @return The sound, owned by the caller (elg_sound_free()), or nullptr with a ResourceError if
///   the file can't be read or decoded.
ElgSound* elg_sound_load_file(ElgStr file);

/// Wraps `Sound::load()` for encoded audio in memory.
/// Callable from any thread.
///
/// @param data The encoded audio (WAV, FLAC, or MP3), read during the call.
/// @return The sound, owned by the caller (elg_sound_free()), or nullptr with a ResourceError if
///   it can't be decoded.
ElgSound* elg_sound_load_data(ElgBytes data);

/// Copies a sound; copies share the decoded audio.
/// Callable from any thread.
///
/// @param sound The sound (borrowed).
/// @return The copy, owned by the caller (elg_sound_free()). Null on failure.
ElgSound* elg_sound_clone(const ElgSound* sound);

/// Frees a sound.
/// Callable from any thread.
///
/// @param sound The sound (consumed); may be null.
void elg_sound_free(ElgSound* sound);

/// Wraps `Sound::play()`: plays the sound in a new voice, so plays overlap. Without an output
/// device it does nothing.
/// Callable from any thread.
///
/// @param sound The sound (borrowed).
/// @param volume 0 to 1, and beyond, amplified.
/// @param pitch Playback speed and pitch: 1 as recorded, 2 an octave up.
/// @param pan -1 left to 1 right.
void elg_sound_play(const ElgSound* sound, float volume, float pitch, float pan);

/// Wraps `Sound::duration()`.
/// Callable from any thread.
///
/// @param sound The sound (borrowed).
/// @return The length in seconds. 0 on failure.
double elg_sound_duration(const ElgSound* sound);

/// Wraps `AudioPlayer(file)`: music, speech, anything long, decoded while it plays.
///
/// @param file The file's path (WAV, FLAC, or MP3).
/// @return The player, owned by the caller (elg_audio_player_free()), or nullptr with a
///   ResourceError if the file can't be opened or isn't audio.
ElgAudioPlayer* elg_audio_player_new(ElgStr file);

/// Copies a player; copies control the same player.
///
/// @param player The player (borrowed).
/// @return The copy, owned by the caller (elg_audio_player_free()). Null on failure.
ElgAudioPlayer* elg_audio_player_clone(const ElgAudioPlayer* player);

/// Frees a player; it stops when the last copy goes.
///
/// @param player The player (consumed); may be null.
void elg_audio_player_free(ElgAudioPlayer* player);

/// Wraps `AudioPlayer::play()`, `pause()`, `toggle()` and `stop()` (which pauses and goes back to
/// the start).
///
/// @param player The player (borrowed).
/// @param op 0 play, 1 pause, 2 toggle, 3 stop.
void elg_audio_player_control(const ElgAudioPlayer* player, int32_t op);

/// Wraps `AudioPlayer::seek()`.
///
/// @param player The player (borrowed).
/// @param seconds Where to go, from the start; clamped to the duration.
void elg_audio_player_seek(const ElgAudioPlayer* player, double seconds);

/// Wraps `AudioPlayer::set_volume()`.
///
/// @param player The player (borrowed).
/// @param volume 0 to 1, and beyond, amplified; negative counts as 0.
void elg_audio_player_set_volume(const ElgAudioPlayer* player, float volume);

/// Wraps `AudioPlayer::set_looping()`.
///
/// @param player The player (borrowed).
/// @param looping Whether it starts over when it reaches the end.
void elg_audio_player_set_looping(const ElgAudioPlayer* player, bool looping);

/// Wraps `AudioPlayer::is_playing()` and `is_looping()`. Tracked reads, for the UI thread.
///
/// @param player The player (borrowed).
/// @param which 0 playing, 1 looping.
/// @return The flag, or false on failure.
bool elg_audio_player_flag(const ElgAudioPlayer* player, int32_t which);

/// Wraps `AudioPlayer::time()`, `duration()` and `volume()`. Tracked reads, for the UI thread:
/// views showing them update while it plays.
///
/// @param player The player (borrowed).
/// @param which 0 time, 1 duration (both in seconds), 2 volume.
/// @return The value, or 0 on failure.
double elg_audio_player_value(const ElgAudioPlayer* player, int32_t which);

/// Wraps `AudioPlayer::time_binding()` and `volume_binding()`, for a Slider: reading follows
/// playback, writing seeks or sets the volume.
///
/// @param player The player (borrowed).
/// @param which 0 time, 1 volume.
/// @return The binding, owned by the caller (elg_binding_f32_free()), or nullptr on failure.
ElgBindingF32* elg_audio_player_binding(const ElgAudioPlayer* player, int32_t which);

/// Wraps `AudioStream(AudioStreamOptions)`: live audio out, samples written as they're made
/// (elg_audio_stream_write()) or mixed on demand by `on_render`. It starts playing when made.
/// Callable from any thread.
///
/// @param device_id An output's ElgDevice::id; empty: the system's default (followed when it
///   changes).
/// @param sample_rate Frames per second, clamped to 8000 to 192000.
/// @param channels 1 or 2 (clamped).
/// @param on_render Optional consumed closure (`call` null: none) that fills each buffer the device
///   asks for instead of playing what was written. `on_render` (args: ElgRenderBuffer*) runs on
///   the audio thread; ret: null. Keep it short and lock-light.
/// @return The stream, owned by the caller (elg_audio_stream_free()), or nullptr on failure.
ElgAudioStream* elg_audio_stream_new(ElgStr device_id, uint32_t sample_rate, uint32_t channels, ElgClosure on_render);

/// Copies a stream; copies share it.
/// Callable from any thread.
///
/// @param stream The stream (borrowed).
/// @return The copy, owned by the caller (elg_audio_stream_free()). Null on failure.
ElgAudioStream* elg_audio_stream_clone(const ElgAudioStream* stream);

/// Frees a stream; it stops when the last copy goes.
/// Callable from any thread.
///
/// @param stream The stream (consumed); may be null.
void elg_audio_stream_free(ElgAudioStream* stream);

/// Wraps `AudioStream::write()`: queues samples to play (without `on_render`). Callable from any
/// thread. Beyond about a second queued, the oldest are dropped.
///
/// @param stream The stream (borrowed).
/// @param samples Interleaved samples, -1 to 1, copied.
/// @param count Number of samples (frames times channels).
void elg_audio_stream_write(const ElgAudioStream* stream, const float* samples, size_t count);

/// Wraps `AudioStream::clear()` (drops what's queued), `start()` and `stop()` (which pauses it).
/// Callable from any thread.
///
/// @param stream The stream (borrowed).
/// @param op 0 clear, 1 start, 2 stop.
void elg_audio_stream_control(const ElgAudioStream* stream, int32_t op);

/// Wraps `AudioStream::queued_frames()`.
/// Callable from any thread.
///
/// @param stream The stream (borrowed).
/// @return How many frames are queued, or 0 on failure.
size_t elg_audio_stream_queued_frames(const ElgAudioStream* stream);

/// Wraps `AudioStream::set_volume()`.
/// Callable from any thread.
///
/// @param stream The stream (borrowed).
/// @param volume 0 to 1, and beyond, amplified; negative counts as 0.
void elg_audio_stream_set_volume(const ElgAudioStream* stream, float volume);

/// Wraps `AudioStream::error()`: why it can't play (no device, failed to open). A tracked read.
///
/// @param stream The stream (borrowed).
/// @param out Receives the error; empty when fine.
/// @param ctx Passed to `out`.
void elg_audio_stream_error(const ElgAudioStream* stream, ElgStrSink out, void* ctx);

/// Wraps `AudioStream::sample_rate()`.
/// Callable from any thread.
///
/// @param stream The stream (borrowed).
/// @return Frames per second, after clamping. 0 on failure.
uint32_t elg_audio_stream_sample_rate(const ElgAudioStream* stream);

/// Wraps `AudioStream::channels()`.
/// Callable from any thread.
///
/// @param stream The stream (borrowed).
/// @return The number of channels, after clamping. 0 on failure.
uint32_t elg_audio_stream_channels(const ElgAudioStream* stream);

// --- Capture ---

/// Wraps `audio_input_devices()`: the system's audio inputs (microphones, line in, virtual
/// devices).
///
/// @param each Borrowed closure, called once per device before this returns; args: `ElgDevice*`,
///   ret: null. Required: none is a usage error.
void elg_audio_input_devices(ElgClosure each);

/// Wraps `AudioRecorder(AudioRecorderOptions)`: records from a microphone into memory. It starts
/// with elg_audio_recorder_control(). Windows asks the person for access; when it's denied, the
/// recorder's error says so.
///
/// @param device_id An input's ElgDevice::id; empty: the system's default input.
/// @param sample_rate Frames per second, clamped to 8000 to 192000.
/// @param channels 1 or 2 (clamped).
/// @param on_samples Optional consumed closure (`call` null: none) that gets each block of
///   samples as it arrives. `on_samples` (args: ElgSamples*) runs on the audio thread; ret: null.
///   Keep it short, and don't touch views or state from it.
/// @param keeps_samples false: samples only go to `on_samples`, so memory doesn't grow while it
///   records; the duration and samples then stay empty.
/// @return The recorder, owned by the caller (elg_audio_recorder_free()), or nullptr on failure.
ElgAudioRecorder* elg_audio_recorder_new(ElgStr device_id, uint32_t sample_rate, uint32_t channels, ElgClosure on_samples, bool keeps_samples);

/// Copies a recorder; copies share the recording.
///
/// @param recorder The recorder (borrowed).
/// @return The copy, owned by the caller (elg_audio_recorder_free()). Null on failure.
ElgAudioRecorder* elg_audio_recorder_clone(const ElgAudioRecorder* recorder);

/// Frees a recorder; it stops when the last copy goes.
///
/// @param recorder The recorder (consumed); may be null.
void elg_audio_recorder_free(ElgAudioRecorder* recorder);

/// Wraps `AudioRecorder::start()` (which continues the recording), `stop()`, `toggle()` and
/// `clear()` (which drops what was recorded).
///
/// @param recorder The recorder (borrowed).
/// @param op 0 start, 1 stop, 2 toggle, 3 clear.
void elg_audio_recorder_control(const ElgAudioRecorder* recorder, int32_t op);

/// Wraps `AudioRecorder::is_recording()`. A tracked read, for the UI thread.
///
/// @param recorder The recorder (borrowed).
/// @return true while recording; false on failure.
bool elg_audio_recorder_is_recording(const ElgAudioRecorder* recorder);

/// Wraps `AudioRecorder::duration()`. A tracked read, for the UI thread.
///
/// @param recorder The recorder (borrowed).
/// @return Seconds recorded, or 0 on failure.
double elg_audio_recorder_duration(const ElgAudioRecorder* recorder);

/// Wraps `AudioRecorder::level()`, for a live input meter. A tracked read, for the UI thread.
///
/// @param recorder The recorder (borrowed).
/// @return The input's recent peak, 0 to 1, while recording; 0 on failure.
float elg_audio_recorder_level(const ElgAudioRecorder* recorder);

/// Wraps `AudioRecorder::error()`: why it can't record (e.g. access was denied). A tracked read.
///
/// @param recorder The recorder (borrowed).
/// @param out Receives the error; empty when fine.
/// @param ctx Passed to `out`.
void elg_audio_recorder_error(const ElgAudioRecorder* recorder, ElgStrSink out, void* ctx);

/// Wraps `AudioRecorder::sample_rate()`.
///
/// @param recorder The recorder (borrowed).
/// @return Frames per second, after clamping. 0 on failure.
uint32_t elg_audio_recorder_sample_rate(const ElgAudioRecorder* recorder);

/// Wraps `AudioRecorder::channels()`.
///
/// @param recorder The recorder (borrowed).
/// @return The number of channels, after clamping. 0 on failure.
uint32_t elg_audio_recorder_channels(const ElgAudioRecorder* recorder);

/// Wraps `AudioRecorder::samples()`: calls `each` (args: ElgSamples*) once with all the samples.
///
/// @param recorder The recorder (borrowed).
/// @param each Borrowed closure, called once before this returns; args: `ElgSamples*`, ret: null.
///   Required: none is a usage error.
void elg_audio_recorder_samples(const ElgAudioRecorder* recorder, ElgClosure each);

/// Wraps `AudioRecorder::save_wav()`: writes the recording as a 16-bit WAV file.
///
/// @param recorder The recorder (borrowed).
/// @param file The file's path. A ResourceError is recorded if it can't be written.
void elg_audio_recorder_save_wav(const ElgAudioRecorder* recorder, ElgStr file);

/// Wraps `AudioRecorder::wav()`: calls `each` (args: ElgBytes*) once with the WAV file's bytes
/// (16-bit).
///
/// @param recorder The recorder (borrowed).
/// @param each Borrowed closure, called once before this returns; args: `ElgBytes*`, ret: null.
///   Required: none is a usage error.
void elg_audio_recorder_wav(const ElgAudioRecorder* recorder, ElgClosure each);

/// Wraps `AudioRecorder::sound()`: the recording as a Sound, to play it back.
///
/// @param recorder The recorder (borrowed).
/// @return The sound, owned by the caller (elg_sound_free()), or nullptr on failure.
ElgSound* elg_audio_recorder_sound(const ElgAudioRecorder* recorder);

/// Wraps `camera_devices()`: the system's cameras.
///
/// @param each Borrowed closure, called once per camera before this returns; args: `ElgDevice*`,
///   ret: null. Required: none is a usage error.
void elg_camera_devices(ElgClosure each);

/// Wraps `Camera(CameraOptions)`: a camera's live picture, for elg_camera_view(). It starts with
/// elg_camera_start().
///
/// @param device_id A camera's ElgDevice::id; empty: the first camera.
/// @param width Preferred frame width in pixels; the camera's closest mode is used.
/// @param height Preferred frame height in pixels.
/// @param mirrored Whether the preview shows a mirror image, as people expect of themselves.
/// @return The camera, owned by the caller (elg_camera_free()), or nullptr on failure.
ElgCamera* elg_camera_new(ElgStr device_id, uint32_t width, uint32_t height, bool mirrored);

/// Copies a camera; copies share it.
///
/// @param camera The camera (borrowed).
/// @return The copy, owned by the caller (elg_camera_free()). Null on failure.
ElgCamera* elg_camera_clone(const ElgCamera* camera);

/// Frees a camera; it stops when the last copy (and the last view showing it) goes.
///
/// @param camera The camera (consumed); may be null.
void elg_camera_free(ElgCamera* camera);

/// Wraps `Camera::start()` and `stop()`.
///
/// @param camera The camera (borrowed).
/// @param start true to start, false to stop.
void elg_camera_start(const ElgCamera* camera, bool start);

/// Wraps `Camera::is_running()`. A tracked read, for the UI thread.
///
/// @param camera The camera (borrowed).
/// @return true while it runs; false on failure.
bool elg_camera_is_running(const ElgCamera* camera);

/// Wraps `Camera::size()`. A tracked read, for the UI thread.
///
/// @param camera The camera (borrowed).
/// @return The frames' size in pixels; zero until the first one, and on failure.
ElgSize elg_camera_size(const ElgCamera* camera);

/// Wraps `Camera::error()`: why it can't run (e.g. access was denied). A tracked read.
///
/// @param camera The camera (borrowed).
/// @param out Receives the error; empty when fine.
/// @param ctx Passed to `out`.
void elg_camera_error(const ElgCamera* camera, ElgStrSink out, void* ctx);

/// Wraps `Camera::mirrored()`.
///
/// @param camera The camera (borrowed).
/// @return Whether the preview shows a mirror image. False on failure.
bool elg_camera_mirrored(const ElgCamera* camera);

/// Wraps `Camera::snapshot()`: calls `each` (args: ElgBytes*) with a PNG of the latest frame
/// (not mirrored); returns false if there's none.
///
/// @param camera The camera (borrowed).
/// @param each Borrowed closure, called at most once before this returns; args: `ElgBytes*`, ret:
///   null. Required: none is a usage error.
/// @return true if `each` got a frame; false before the first frame, and on failure.
bool elg_camera_snapshot(const ElgCamera* camera, ElgClosure each);

/// Wraps `CameraView()`: the camera's picture, filling (cropped to) or fitted into the space
/// offered.
///
/// @param camera The camera (borrowed; the view shares it).
/// @param mode An elg::ContentMode: 0 fit, 1 fill (the C++ default).
/// @return The new view, owned by the caller, or nullptr on failure.
ElgView* elg_camera_view(const ElgCamera* camera, int32_t mode);

// --- Video ---

/// Wraps `VideoPlayer(const std::string&)`: a video and its playback. Build players on the UI
/// thread. Loading is asynchronous: errors show in elg_video_player_error().
///
/// @param source A file path or an http(s) URL.
/// @return The player, owned by the caller (elg_video_player_free()), or nullptr on failure.
ElgVideoPlayer* elg_video_player_new(ElgStr source);

/// Wraps `VideoPlayer(const std::filesystem::path&)`: like elg_video_player_new(), for a file.
///
/// @param file The file's path.
/// @return The player, owned by the caller (elg_video_player_free()), or nullptr on failure.
ElgVideoPlayer* elg_video_player_new_file(ElgStr file);

/// Copies a player; copies control the same video.
///
/// @param player The player (borrowed).
/// @return The copy, owned by the caller (elg_video_player_free()). Null on failure.
ElgVideoPlayer* elg_video_player_clone(const ElgVideoPlayer* player);

/// Frees a player; the video stops when the last copy (and the last view showing it) goes.
///
/// @param player The player (consumed); may be null.
void elg_video_player_free(ElgVideoPlayer* player);

/// Wraps `VideoPlayer::play()`, `pause()`, `toggle()` and `stop()` (which pauses and goes back to
/// the start).
///
/// @param player The player (borrowed).
/// @param op 0 play, 1 pause, 2 toggle, 3 stop.
void elg_video_player_control(const ElgVideoPlayer* player, int32_t op);

/// Wraps `VideoPlayer::seek()`.
///
/// @param player The player (borrowed).
/// @param seconds Where to go, from the start.
void elg_video_player_seek(const ElgVideoPlayer* player, double seconds);

/// Wraps `VideoPlayer::set_volume()`.
///
/// @param player The player (borrowed).
/// @param volume 0 to 1.
void elg_video_player_set_volume(const ElgVideoPlayer* player, float volume);

/// Wraps `VideoPlayer::set_muted()`.
///
/// @param player The player (borrowed).
/// @param muted Whether its sound is muted.
void elg_video_player_set_muted(const ElgVideoPlayer* player, bool muted);

/// Wraps `VideoPlayer::set_looping()`.
///
/// @param player The player (borrowed).
/// @param looping Whether it starts over when it reaches the end.
void elg_video_player_set_looping(const ElgVideoPlayer* player, bool looping);

/// Wraps `VideoPlayer::is_playing()`, `is_ready()` (the duration and size are known), `is_muted()`
/// and `is_looping()`. Tracked reads, for the UI thread.
///
/// @param player The player (borrowed).
/// @param which 0 playing, 1 ready, 2 muted, 3 looping.
/// @return The flag, or false on failure.
bool elg_video_player_flag(const ElgVideoPlayer* player, int32_t which);

/// Wraps `VideoPlayer::time()`, `duration()` and `volume()`. Tracked reads, for the UI thread.
///
/// @param player The player (borrowed).
/// @param which 0 time, 1 duration (both in seconds), 2 volume.
/// @return The value, or 0 on failure.
double elg_video_player_value(const ElgVideoPlayer* player, int32_t which);

/// Wraps `VideoPlayer::natural_size()`. A tracked read, for the UI thread.
///
/// @param player The player (borrowed).
/// @return The video's size in pixels; zero until it's ready, and on failure.
ElgSize elg_video_player_natural_size(const ElgVideoPlayer* player);

/// Wraps `VideoPlayer::error()`: why it can't play (unsupported format, missing file, network
/// error). A tracked read.
///
/// @param player The player (borrowed).
/// @param out Receives the error; empty when fine.
/// @param ctx Passed to `out`.
void elg_video_player_error(const ElgVideoPlayer* player, ElgStrSink out, void* ctx);

/// Wraps `VideoPlayer::progress_binding()` (0 to 1; writing seeks) and `volume_binding()`, for
/// Sliders.
///
/// @param player The player (borrowed).
/// @param which 0 progress, 1 volume.
/// @return The binding, owned by the caller (elg_binding_f32_free()), or nullptr on failure.
ElgBindingF32* elg_video_player_binding(const ElgVideoPlayer* player, int32_t which);

/// Wraps `VideoView()`: the video's picture, fitted into (or filling, clipped to) the space
/// offered, on black. Its ideal size is the video's own.
///
/// @param player The player (borrowed; the view shares it).
/// @param mode An elg::ContentMode: 0 fit (the C++ default), 1 fill.
/// @return The new view, owned by the caller, or nullptr on failure.
ElgView* elg_video_view(const ElgVideoPlayer* player, int32_t mode);

/// Wraps `VideoControls()`: play/pause, a scrubber, the time, and mute, to lay over (or under) a
/// video view.
///
/// @param player The player (borrowed; the view shares it).
/// @return The new view, owned by the caller, or nullptr on failure.
ElgView* elg_video_controls(const ElgVideoPlayer* player);

// --- External GPU images ---

/// Wraps `GpuImageView()`: shows the frames published to an ElgGpuImage (elg/gpu_image.h).
///
/// @param image The image (borrowed; the view keeps its source alive independently of the
///   handle); null: an empty view.
/// @param mode An elg::ContentMode: 0 fit, 1 fill.
/// @return The new view, owned by the caller, or nullptr on failure.
ElgView* elg_gpu_image_view(const ElgGpuImage* image, int32_t mode);

/// Wraps `VideoFeed()`: video the app makes itself (a decoder of its own, a screen capture), shown
/// by elg_video_feed_view().
/// Callable from any thread.
///
/// @return The feed, owned by the caller (elg_video_feed_free()), or nullptr on failure.
ElgVideoFeed* elg_video_feed_new(void);

/// Copies a feed; copies share it.
/// Callable from any thread.
///
/// @param feed The feed (borrowed).
/// @return The copy, owned by the caller (elg_video_feed_free()). Null on failure.
ElgVideoFeed* elg_video_feed_clone(const ElgVideoFeed* feed);

/// Frees a feed.
/// Callable from any thread.
///
/// @param feed The feed (consumed); may be null.
void elg_video_feed_free(ElgVideoFeed* feed);

/// Whether two feeds are the same feed (copies of one another): `VideoFeed`'s operator==.
/// Callable from any thread.
///
/// @param a A feed (borrowed).
/// @param b Another feed (borrowed).
/// @return true for the same feed. False on failure.
bool elg_video_feed_eq(const ElgVideoFeed* a, const ElgVideoFeed* b);

/// Wraps `VideoFeed::push()`: a new frame. Callable from any thread. Frames are packed (no row
/// padding), top to bottom. A frame with a zero dimension, or fewer bytes than its size needs, is
/// ignored.
///
/// @param feed The feed (borrowed).
/// @param format A VideoFeed::Format: 0 bgra, 1 nv12, 2 i420.
/// @param width Width in pixels.
/// @param height Height in pixels.
/// @param pixels The frame's bytes, copied.
/// @param count Number of bytes at `pixels`.
/// @param full_range YUV in 0...255 rather than 16...235.
void elg_video_feed_push(const ElgVideoFeed* feed, int32_t format, uint32_t width, uint32_t height, const uint8_t* pixels, size_t count, bool full_range);

/// Wraps `VideoFeed::clear()`: no picture (black) until the next push. Callable from any thread.
///
/// @param feed The feed (borrowed).
void elg_video_feed_clear(const ElgVideoFeed* feed);

/// Wraps `VideoFeed::size()`. A tracked read, for the UI thread.
///
/// @param feed The feed (borrowed).
/// @return The frames' size in pixels; zero before the first, and on failure.
ElgSize elg_video_feed_size(const ElgVideoFeed* feed);

/// Wraps `VideoFeed::has_frame()`. A tracked read, for the UI thread.
///
/// @param feed The feed (borrowed).
/// @return false before the first push, after elg_video_feed_clear(), and on failure.
bool elg_video_feed_has_frame(const ElgVideoFeed* feed);

/// Wraps `VideoFeedView()`: the feed's picture, fitted into (or filling, clipped to) the space
/// offered, on black.
///
/// @param feed The feed (borrowed; the view shares it).
/// @param mode An elg::ContentMode: 0 fit (the C++ default), 1 fill.
/// @param mirrored Whether to show it flipped left to right (someone's own camera).
/// @return The new view, owned by the caller, or nullptr on failure.
ElgView* elg_video_feed_view(const ElgVideoFeed* feed, int32_t mode, bool mirrored);

// --- Desktop ---

/// Wraps `choose_files()`: the system's open dialog, over the active window. Call it on the UI
/// thread of a running App; otherwise it records a UsageError.
///
/// @param fs The file type filters, read during the call.
/// @param filter_count Number of `fs`.
/// @param directory Where the dialog opens; empty: the system's choice.
/// @param multiple Whether several files can be chosen.
/// @param done Consumed closure, called once on the UI thread when the dialog closes. `done` args:
///   ElgPaths* (empty if cancelled). ret: null. Required: none is a usage error.
void elg_choose_files(const ElgFileFilter* fs, size_t filter_count, ElgStr directory, bool multiple, ElgClosure done);

/// Wraps `choose_save_file()`: the system's save dialog. The file isn't created; the dialog asked
/// about replacing an existing one. Call it on the UI thread of a running App; otherwise it records
/// a UsageError.
///
/// @param fs The file type filters, read during the call.
/// @param filter_count Number of `fs`.
/// @param directory Where the dialog opens; empty: the system's choice.
/// @param name The suggested file name.
/// @param done Consumed closure, called once on the UI thread when the dialog closes; args:
///   `ElgPaths*`, the chosen path (none if cancelled); ret: null. Required: none is a usage error.
void elg_choose_save_file(const ElgFileFilter* fs, size_t filter_count, ElgStr directory, ElgStr name, ElgClosure done);

/// Wraps `choose_folders()`: the system's folder dialog. Call it on the UI thread of a running
/// App; otherwise it records a UsageError.
///
/// @param directory Where the dialog opens; empty: the system's choice.
/// @param multiple Whether several folders can be chosen.
/// @param done Consumed closure, called once on the UI thread when the dialog closes; args:
///   `ElgPaths*`, the chosen folders (none if cancelled); ret: null. Required: none is a usage
///   error.
void elg_choose_folders(ElgStr directory, bool multiple, ElgClosure done);

/// Wraps `notify()`: shows a system notification (Windows: a toast, also kept in the notification
/// center). Call it on the UI thread of a running App; otherwise it records a UsageError.
///
/// @param title The notification's title.
/// @param body Its text.
/// @param on_click Optional consumed closure (`call` null: none), run on the UI thread when the
///   notification is clicked; args and ret: null.
void elg_notify(ElgStr title, ElgStr body, ElgClosure on_click);

/// Wraps `TrayIcon(TrayIconOptions)`: an icon in the system tray (Windows: the notification area)
/// with a menu, shown while any copy lives. Call it while an App runs; otherwise it records a
/// UsageError.
///
/// @param icon A file or data image (borrowed; must not be null); all fields empty: a plain dot in
///   the theme's accent color.
/// @param tooltip Shown when the pointer rests on the icon.
/// @param menu The menu's items, read during the call; their closures are consumed.
/// @param count Number of `menu` items.
/// @return The tray icon, owned by the caller (elg_tray_icon_free()), or nullptr on failure.
ElgTrayIcon* elg_tray_icon_new(const ElgImageSource* icon, ElgStr tooltip, const ElgTrayMenuItem* menu, size_t count);

/// Copies a tray icon handle; copies share the icon.
///
/// @param icon The tray icon (borrowed).
/// @return The copy, owned by the caller (elg_tray_icon_free()). Null on failure.
ElgTrayIcon* elg_tray_icon_clone(const ElgTrayIcon* icon);

/// Frees a tray icon handle; the icon goes away with the last copy.
///
/// @param icon The tray icon (consumed); may be null.
void elg_tray_icon_free(ElgTrayIcon* icon);

/// Wraps `TrayIcon::set_tooltip()`.
///
/// @param icon The tray icon (borrowed).
/// @param tooltip The new tooltip.
void elg_tray_icon_set_tooltip(const ElgTrayIcon* icon, ElgStr tooltip);

/// Wraps `TrayIcon::set_menu()`: replaces the menu.
///
/// @param icon The tray icon (borrowed).
/// @param menu The new menu's items, read during the call; their closures are consumed.
/// @param count Number of `menu` items.
void elg_tray_icon_set_menu(const ElgTrayIcon* icon, const ElgTrayMenuItem* menu, size_t count);

// --- ABI layout (this file's structs and elg/gpu_image.h's) ---

/// Describes the layout of this file's structs and elg/gpu_image.h's, for a binding's layout test: one
/// line per struct, "name size align", then " field:offset" for each of its fields, in order.
///
/// @param out Receives each line.
/// @param ctx Passed to `out`.
void elg_layouts_platform(ElgStrSink out, void* ctx);

// --- Buttons ---

/// Copies a style handle (`s`, borrowed); both point at the same style. Returns the copy, owned by
/// the caller, or null on failure.
ElgButtonStyle* elg_button_style_clone(const ElgButtonStyle* s);

/// Frees a style handle (consumed; may be null). The style lives on while views or other handles
/// hold it.
void elg_button_style_free(ElgButtonStyle* s);

/// Sets the style of this family's controls inside `v`, as View::button_style() and the other
/// *_style() modifiers do. Both are borrowed; the view keeps its own reference to the style.
/// Returns the new view, owned by the caller, or null on failure.
ElgView* elg_mod_button_style(const ElgView* v, const ElgButtonStyle* style);

/// Copies a configuration (borrowed), e.g. to keep one past the call that got it. Returns the copy,
/// owned by the caller, or null on failure.
ElgButtonConfiguration* elg_button_config_clone(const ElgButtonConfiguration* c);

/// Frees a configuration (consumed; may be null): one a Rust style's make_body got, or a copy.
void elg_button_config_free(ElgButtonConfiguration* c);

/// The style's make_body(), its body for configuration `c`, so a Rust style can wrap or reuse
/// another style (e.g. the one in the environment). Call it from a style's make_body, while
/// Environment<K>() is available. `s` and `c` are borrowed. Returns the body, owned by the caller,
/// or null on failure.
ElgView* elg_button_style_make_body(const ElgButtonStyle* s, const ElgButtonConfiguration* c);

/// A style implemented in Rust, for families whose style has only make_body(). It calls `make_body`
/// (required: none is a usage error) once per control as it's built, with args: a heap copy of the
/// configuration, owned by the Rust side (free it with elg_button_config_free), ret: View*. Returns
/// the style, owned by the caller (free it with elg_button_style_free), or null on failure.
ElgButtonStyle* elg_button_style_rust(ElgClosure make_body);

/// A built-in ButtonStyle.
///
/// @param kind 0 `ProminentButtonStyle` (filled with the tint; the default), 1 `BorderedButtonStyle`, anything
///   else `PlainButtonStyle`.
/// @return The style, owned by the caller (free it with elg_button_style_free()). Null on failure.
ElgButtonStyle* elg_button_style_builtin(int32_t kind);

/// The button's label (`ButtonConfiguration::label`).
///
/// @param c The configuration (borrowed).
/// @return A copy of the label, owned by the caller. Null on failure.
ElgView* elg_button_config_label(const ElgButtonConfiguration* c);

/// One of the button's states (`ButtonConfiguration`): a tracked read, so read it inside reactive arguments.
///
/// @param c The configuration (borrowed).
/// @param which 0 pressed (with the pointer still over it), 1 hovered, 2 enabled, anything else focused.
/// @return The state; false on failure.
bool elg_button_config_state(const ElgButtonConfiguration* c, int32_t which);

// --- Toggles ---

/// Copies a style handle (`s`, borrowed); both point at the same style. Returns the copy, owned by
/// the caller, or null on failure.
ElgToggleStyle* elg_toggle_style_clone(const ElgToggleStyle* s);

/// Frees a style handle (consumed; may be null). The style lives on while views or other handles
/// hold it.
void elg_toggle_style_free(ElgToggleStyle* s);

/// Sets the style of this family's controls inside `v`, as View::button_style() and the other
/// *_style() modifiers do. Both are borrowed; the view keeps its own reference to the style.
/// Returns the new view, owned by the caller, or null on failure.
ElgView* elg_mod_toggle_style(const ElgView* v, const ElgToggleStyle* style);

/// Copies a configuration (borrowed), e.g. to keep one past the call that got it. Returns the copy,
/// owned by the caller, or null on failure.
ElgToggleConfiguration* elg_toggle_config_clone(const ElgToggleConfiguration* c);

/// Frees a configuration (consumed; may be null): one a Rust style's make_body got, or a copy.
void elg_toggle_config_free(ElgToggleConfiguration* c);

/// The style's make_body(), its body for configuration `c`, so a Rust style can wrap or reuse
/// another style (e.g. the one in the environment). Call it from a style's make_body, while
/// Environment<K>() is available. `s` and `c` are borrowed. Returns the body, owned by the caller,
/// or null on failure.
ElgView* elg_toggle_style_make_body(const ElgToggleStyle* s, const ElgToggleConfiguration* c);

/// A ToggleStyle implemented in Rust: its `make_body()` calls `make_body`.
///
/// @param make_body Builds a toggle's body, once per toggle as it's built. args: a heap copy of the
///   configuration (ToggleConfiguration*, owned by the Rust side: free it with elg_toggle_config_free()), ret:
///   View*. Required: none is a usage error.
/// @param animation How a flip animates (borrowed; copied); null: it flips at once.
/// @return The style, owned by the caller (free it with elg_toggle_style_free()), or null on failure.
ElgToggleStyle* elg_toggle_style_rust(ElgClosure make_body, const ElgAnimation* animation);

/// Wraps `SwitchToggleStyle`: the label, then a sliding switch in the tint. The default ToggleStyle.
