ElgCheckboxConfiguration* elg_checkbox_config_clone(const ElgCheckboxConfiguration* c);

/// Frees a configuration (consumed; may be null): one a Rust style's make_body got, or a copy.
void elg_checkbox_config_free(ElgCheckboxConfiguration* c);

/// The style's make_body(), its body for configuration `c`, so a Rust style can wrap or reuse
